    // ── the panels' height, and the font ────────────────────────────────────────────────────

    /// `Ctrl+Up` brings the panels' bottom edge *up*, which is less panel and more of the
    /// output underneath. It read the other way round until somebody pressed it.
    #[test]
    fn ctrl_up_makes_the_panels_shorter_and_ctrl_down_gives_the_rows_back() {
        let mut app = app();
        assert_eq!(app.cfg.panel.height_cut, 0);
        press(&mut app, "Ctrl+Up");
        press(&mut app, "Ctrl+Up");
        assert_eq!(app.cfg.panel.height_cut, 2, "two rows off the panels");
        press(&mut app, "Ctrl+Down");
        assert_eq!(app.cfg.panel.height_cut, 1);
        press(&mut app, "Ctrl+Down");
        press(&mut app, "Ctrl+Down");
        assert_eq!(app.cfg.panel.height_cut, 0, "and no further");
    }

    /// `Ctrl+Alt+R` undoes every `Ctrl+arrow` at once: the line back in the middle and the
    /// rows back to the panels, which is where a fresh configuration starts.
    #[test]
    fn one_key_puts_the_panels_back_as_they_started() {
        let mut app = app();
        for key in ["Ctrl+Left", "Ctrl+Left", "Ctrl+Left", "Ctrl+Up", "Ctrl+Up"] {
            press(&mut app, key);
        }
        assert_eq!(app.cfg.panel.split, 47);
        assert_eq!(app.cfg.panel.height_cut, 2);
        press(&mut app, "Ctrl+Alt+R");
        let start = fcmd_config::PanelCfg::default();
        assert_eq!(app.cfg.panel.split, start.split);
        assert_eq!(app.cfg.panel.height_cut, start.height_cut);
    }

    #[test]
    fn the_font_keys_ask_the_terminal_and_say_that_is_what_they_did() {
        let mut app = app();
        // `Ctrl+Alt+0` and not `Ctrl+0`, which is the tenth view mode, nor `Ctrl+Shift+0`,
        // which sets the first folder shortcut: a number key belongs to the panels twice
        // over and the font is the newcomer.
        for (key, want) in [("Ctrl++", 1i8), ("Ctrl+-", -1), ("Ctrl+Alt+0", 0)] {
            press(&mut app, key);
            let by = app
                .take_requests()
                .into_iter()
                .find_map(|r| match r {
                    Request::Font { by } => Some(by),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("{key} asked for nothing"));
            assert_eq!(by, want, "{key}");
            // A program cannot know whether the terminal did it, and the line says so.
            assert!(app.status.contains("terminal"), "{}", app.status);
        }
    }

