        app.run(Command::FileChecksumVerify);
        let id = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::Verify { id, .. } => Some(id),
                _ => None,
            })
            .expect("a verify request");
        app.handle_event(Event::VerifyDone {
            id,
            verdicts: Vec::new(),
            cancelled: false,
            problem: Some("a.txt: not a list of digests this can check".into()),
        });
        assert!(app.status_error);
