    /// A file that is not in the folder the panel shows — opened from a search, or the panel
    /// moved on while it was being read — takes the panel to its own folder, and the cursor
    /// lands on it once that folder has been read.
    #[test]
    fn ctrl_f10_takes_the_panel_to_the_folder_of_a_file_it_is_not_showing() {
        let dir = tempfile::tempdir().unwrap();
        let deep = dir.path().join("deep");
        std::fs::create_dir(&deep).unwrap();
        std::fs::write(deep.join("a.txt"), b"a\n").unwrap();
        std::fs::write(deep.join("found.txt"), b"found\n").unwrap();
        let mut app = app_on_disk(dir.path());
        let found = deep.join("found.txt");
        app.open_viewer_on(&found, VPath::local(&found));
        assert!(app.mode.viewer().is_some(), "the viewer opened");

        app.run(Command::ViewerToPanel);
        assert!(app.mode.viewer().is_none());
        assert_eq!(app.panel().cwd, VPath::local(&deep));
        assert_eq!(app.panel().want_cursor.as_deref(), Some("found.txt"));
        // The folder arrives, and the cursor is put on the file in it.
        let entries = fcmd_vfs::local::list_blocking(&VPath::local(&deep), &CancelToken::new())
            .expect("the folder");
        let generation = app.panels[app.active].generation;
        app.handle_event(Event::Listed {
            panel: app.active,
            generation,
            result: Ok(entries),
        });
        assert_eq!(app.panel().current().unwrap().name_str(), "found.txt");
    }

    /// `F4` on a search result edits the file on the line the text was found on, and `F3`
    /// reads it from there: the offset the search kept is the whole point of the row.
    #[test]
    fn a_search_result_opens_where_the_text_was_found() {
        let dir = tempfile::tempdir().unwrap();
        let text: String = (1..=40).map(|n| format!("line {n}\n")).collect();
        let file = dir.path().join("notes.txt");
        std::fs::write(&file, &text).unwrap();
        let at = text.find("line 30").unwrap() as u64;
        let mut app = app_on_disk(dir.path());
        let entries =
            fcmd_vfs::local::list_blocking(&VPath::local(dir.path()), &CancelToken::new())
                .expect("the test directory");
        let entry = entries
            .into_iter()
            .find(|e| e.name_str() == "notes.txt")
            .expect("the file");
        let results = |app: &mut App| {
            app.mode = Mode::Find(Box::new(FindView {
                id: 1,
                label: "line 30".into(),
                rows: vec![(VPath::local(&file), entry.clone())],
                found_at: vec![Some(at)],
                scores: vec![None],
                cursor: 0,
                top: 0,
                scanning: None,
                files: 1,
                dirs: 1,
                done: true,
                stopped: false,
                elapsed: std::time::Duration::ZERO,
                cancel: CancelToken::new(),
                problems: Vec::new(),
            }));
        };

        results(&mut app);
        press(&mut app, "F4");
        let editor = app.mode.editor().expect("the editor opened");
        assert_eq!(editor.cursor.line, 29, "line 30, counted from one");

        results(&mut app);
        press(&mut app, "F3");
        let viewer = app.mode.viewer().expect("the viewer opened");
        assert!(
            viewer.top > 0 && viewer.top <= at,
            "the viewer starts at the match, not at the top: {}",
            viewer.top
        );
    }

