    #[test]
    fn ctrl_o_shows_what_a_command_printed_and_the_exit_code_is_not_hidden() {
        let mut app = app();
        typed(&mut app, "false");
        press(&mut app, "Enter");
        let id = match app.requests.iter().find_map(|r| match r {
            Request::Shell { id, .. } => Some(*id),
            _ => None,
        }) {
            Some(id) => id,
            None => panic!("no shell request"),
        };
        app.handle_event(Event::ShellDone {
            id,
            line: "false".into(),
            output: "nothing to say\n".into(),
            status: Some(1),
        });
        assert!(
            app.status_error,
            "a non-zero exit is not hidden: {}",
            app.status
        );
        // `Ctrl+O` takes the panels off the screen rather than opening a screen of its own:
        // the mode is still the normal one, so the command line and the keys keep working.
        press(&mut app, "Ctrl+O");
        assert!(app.panels_off);
        assert!(app.mode.is_normal());
        assert!(app.user_screen.iter().any(|l| l == "$ false"));
        assert!(app.user_screen.iter().any(|l| l == "nothing to say"));
        // A command typed with the panels off runs exactly as it does with them on.
        typed(&mut app, "echo again");
        press(&mut app, "Enter");
        assert!(shell_requests(&app).iter().any(|c| c == "echo again"));
        // And the same key brings them back.
        press(&mut app, "Ctrl+O");
        assert!(!app.panels_off);
        assert!(app.mode.is_normal());
    }

    /// The id of the shell request the last `Enter` queued.
    fn shell_id(app: &App) -> u64 {
        match app.requests.iter().find_map(|r| match r {
            Request::Shell { id, .. } => Some(*id),
            _ => None,
        }) {
            Some(id) => id,
            None => panic!("no shell request"),
        }
    }

    #[test]
    fn what_a_command_prints_arrives_while_it_runs_and_the_panels_come_back_after_it() {
        let mut app = app();
        typed(&mut app, "make");
        press(&mut app, "Enter");
        let id = shell_id(&app);
        // The heading is up before a single line has been printed: the output has to have
        // somewhere to land, and the panels are off so it can be watched arriving.
        assert_eq!(app.user_screen.last().map(String::as_str), Some("$ make"));
        assert!(app.panels_off, "the screen shows the command while it runs");
        assert!(app.mode.is_normal(), "everything else stays live");

        app.handle_event(Event::ShellOutput {
            id,
            text: "cc -c main.c\ncc -c util.c\n".into(),
        });
        assert_eq!(
            app.user_screen.last().map(String::as_str),
            Some("cc -c util.c")
        );
        app.handle_event(Event::ShellOutput {
            id,
            text: "cc -o prog\n".into(),
        });
        assert_eq!(
            app.user_screen.last().map(String::as_str),
            Some("cc -o prog")
        );
        // The window counts back from the end, so nothing had to be scrolled to see them.
        assert_eq!(app.user_scroll, 0);

        app.handle_event(Event::ShellDone {
            id,
            line: "make".into(),
            output: String::new(),
            status: Some(0),
        });
        // The panels come back by themselves, and what was printed is still there under
        // `Ctrl+O` — and only once, which is the point of the output not being sent twice.
        assert!(!app.panels_off);
        assert_eq!(
            app.user_screen
                .iter()
                .filter(|l| *l == "cc -o prog")
                .count(),
            1
        );
    }

    #[test]
    fn the_screen_the_command_took_is_given_back_the_moment_the_key_asks_for_it() {
        let mut app = app();
        typed(&mut app, "make");
        press(&mut app, "Enter");
        let id = shell_id(&app);
        assert!(app.panels_off);
        // `Ctrl+O` while it runs: the panels come back and the command carries on, its
        // output still landing on the screen behind them.
        press(&mut app, "Ctrl+O");
        assert!(!app.panels_off);
        app.handle_event(Event::ShellOutput {
            id,
            text: "still going\n".into(),
        });
        assert!(app.user_screen.iter().any(|l| l == "still going"));
        // And the end of the command does not take the screen away a second time.
        app.handle_event(Event::ShellDone {
            id,
            line: "make".into(),
            output: String::new(),
            status: Some(0),
        });
        assert!(!app.panels_off);
    }

    #[test]
    fn the_panels_stay_when_the_setting_says_so_and_the_output_still_arrives_as_it_is_printed() {
        let mut app = app();
        app.cfg.ui.command_screen = false;
        typed(&mut app, "make");
        press(&mut app, "Enter");
        let id = shell_id(&app);
        assert!(!app.panels_off, "the panels are left alone");
        app.handle_event(Event::ShellOutput {
            id,
            text: "cc -c main.c\n".into(),
        });
        // The line is on the screen `Ctrl+O` opens as soon as it is printed, which is the
        // half of this that is not about which screen is in front.
        assert!(app.user_screen.iter().any(|l| l == "cc -c main.c"));
    }

    #[test]
    fn a_line_rewritten_in_place_is_kept_as_what_it_ended_up_saying() {
        let mut app = app();
        typed(&mut app, "copy");
        press(&mut app, "Enter");
        let id = shell_id(&app);
        // A progress bar writes its line over and over with a carriage return between the
        // tries. The screen keeps lines, so what is kept is the last of them.
        app.handle_event(Event::ShellOutput {
            id,
            text: "10%\r50%\r100%\n".into(),
        });
        assert_eq!(app.user_screen.last().map(String::as_str), Some("100%"));
    }

    #[test]
    fn with_the_panels_off_the_pages_turn_through_what_was_printed() {
        let mut app = app();
        app.user_screen = (0..200).map(|n| format!("line {n}")).collect();
        app.rows = 20;
        press(&mut app, "Ctrl+O");
        assert_eq!(
            app.user_scroll, 0,
            "it opens at the end, where the last command is"
        );
        press(&mut app, "PgUp");
        assert_eq!(app.user_scroll, 20);
        press(&mut app, "PgUp");
        assert_eq!(app.user_scroll, 40);
        press(&mut app, "PgDn");
        assert_eq!(app.user_scroll, 20);
        // Never past the first line, and never past the last.
        for _ in 0..40 {
            press(&mut app, "PgUp");
        }
        assert_eq!(app.user_scroll, 199);
        for _ in 0..40 {
            press(&mut app, "PgDn");
        }
        assert_eq!(app.user_scroll, 0);
        // With the panels on, the same keys page through the listing again.
        press(&mut app, "Ctrl+O");
        press(&mut app, "PgUp");
        assert_eq!(app.user_scroll, 0);
    }

    #[test]
    fn two_commands_at_once_are_refused_rather_than_queued_silently() {
        let mut app = app();
        typed(&mut app, "sleep 10");
        press(&mut app, "Enter");
        typed(&mut app, "echo second");
        press(&mut app, "Enter");
        assert_eq!(shell_requests(&app), ["sleep 10"]);
        assert!(app.status_error, "{}", app.status);
    }

    #[test]
    fn f9_opens_the_menu_on_the_side_that_has_the_focus() {
        let mut app = app();
        press(&mut app, "F9");
        assert!(matches!(app.mode, Mode::Menu { menu: 0, .. }));
        press(&mut app, "Esc");
        assert!(app.mode.is_normal());

        app.active = 1;
        press(&mut app, "F9");
        assert!(matches!(app.mode, Mode::Menu { menu: 4, .. }));
    }

    #[test]
    fn the_menu_walks_sideways_and_skips_separators() {
        let mut app = app();
        press(&mut app, "F9");
        press(&mut app, "Right");
        let Mode::Menu { menu, item, .. } = app.mode else {
            panic!("the menu closed")
        };
        assert_eq!(menu, 1);
        assert_eq!(item, 0);
        press(&mut app, "Left");
        press(&mut app, "Left");
        assert!(matches!(app.mode, Mode::Menu { menu: 4, .. }));

        // Down from the last entry before a separator must land on an entry, never on the line.
        press(&mut app, "Esc");
        press(&mut app, "F9");
        for _ in 0..40 {
            press(&mut app, "Down");
            let Mode::Menu { menu, item, .. } = app.mode else {
                panic!("the menu closed")
            };
            assert!(
                matches!(menu::menus()[menu].items[item], menu::Entry::Item(_)),
                "the cursor stopped on a separator"
            );
        }
    }

    #[test]
    fn a_menu_entry_runs_its_command_on_its_own_panel() {
        let mut app = app();
        app.active = 0;
        // The Right menu acts on the right panel even when the left one has the focus.
        open(&mut app, 4, "menu-brief");
        assert_eq!(app.panels[1].view, ViewMode::Brief);
        assert_eq!(app.panels[0].view, ViewMode::Full);
        assert_eq!(app.active, 1);
    }

    /// *Options → Plugins configuration*: the plugins found, `Enter` turns one off and on
    /// again — written to the configuration, and its commands leaving and coming back to `F11`
    /// at once — and `F3` is its card. One that did not load is listed and cannot be turned on.
    #[test]
    fn the_plugins_configuration_turns_a_plugin_off_and_on() {
        let mut app = app();
        app.plugins = vec![
            PluginRow {
                id: "demo".into(),
                name: "Demo".into(),
                version: "1.0".into(),
                author: "Someone".into(),
                description: "Does a thing".into(),
                dir: std::path::PathBuf::from("/plugins/demo"),
                provides: vec![("command", 1)],
                notes: Vec::new(),
                loaded: true,
            },
            PluginRow::broken("/plugins/bad/plugin.toml: [plugin] has no id"),
        ];
        app.plugin_commands = vec![PluginCommand {
            plugin: "demo".into(),
            id: "user.demo.go".into(),
            label: "Demo: go".into(),
            scope: fcmd_cmd::Scope::Panel,
            program: std::path::PathBuf::from("/plugins/demo/go.sh"),
            needs: Vec::new(),
            timeout: None,
            confirm: None,
            when: Default::default(),
        }];
        // From the menu, as a list.
        open(&mut app, 3, "menu-plugins-config");
        let Mode::Pick(pick) = &app.mode else {
            panic!("no list: {:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::PluginsConfig);
        assert_eq!(pick.rows.len(), 2);
        assert!(pick.rows[0].label.contains("demo") && pick.rows[0].label.contains('✓'));
        assert!(pick.rows[1].label.contains("bad"), "{}", pick.rows[1].label);

        // `F3` is the card.
        press(&mut app, "F3");
        let Mode::Message { lines, .. } = &app.mode else {
            panic!("no card: {:?}", app.mode)
        };
        let card = lines.join("\n");
        assert!(
            card.contains("Someone") && card.contains("Demo: go"),
            "{card}"
        );
        press(&mut app, "Esc");

        // `Enter` turns it off: written down, and greyed out in `F11`, saying where it was
        // turned off.
        app.run(Command::OptPlugins);
        press(&mut app, "Enter");
        assert_eq!(app.cfg.plugins.disabled, vec!["demo".to_string()]);
        assert!(!app.status.is_empty());
        press(&mut app, "Esc");
        app.run(Command::PluginCommands);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert!(
            pick.rows[0].label.contains("turned off"),
            "{}",
            pick.rows[0].label
        );
        assert_eq!(
            app.plugin_dim,
            ["0"],
            "a plugin turned off is offered as if it were on"
        );
        // And on again.
        app.mode = Mode::Normal;
        app.run(Command::OptPlugins);
        press(&mut app, "Enter");
        assert!(app.cfg.plugins.disabled.is_empty());
        press(&mut app, "Esc");
        app.run(Command::PluginCommands);
        assert!(matches!(&app.mode, Mode::Pick(p) if p.kind == PickKind::Plugins));
        app.mode = Mode::Normal;

        // The one that did not load cannot be turned on.
        app.run(Command::OptPlugins);
        press(&mut app, "Down");
        press(&mut app, "Enter");
        assert!(app.status_error, "{}", app.status);
        assert!(app.cfg.plugins.disabled.is_empty());
    }

    /// The settings browser: every key, the value it is at, and the three keys that change
    /// one. Generated from the configuration, so it cannot drift from it (SPEC 07 §2e).
    #[test]
    fn the_settings_browser_lists_every_setting_and_changes_one() {
        let mut app = app();
        app.run(Command::OptSettings);
        let Mode::Pick(pick) = &app.mode else {
            panic!("no list: {}", app.status)
        };
        assert_eq!(pick.kind, crate::menu::PickKind::Settings);
        assert!(pick.rows.len() > 40, "only {} settings", pick.rows.len());
        // The keys are the ones `--set` and the configuration file use.
        assert!(pick.rows.iter().any(|r| r.value == "ui.key_bar"));
        assert!(
            pick.rows
                .iter()
                .any(|r| r.label.starts_with("ui.key_bar = true")),
            "the value is on the row"
        );
        // A `[[block]]` has an editor of its own and is not a row here.
        assert!(!pick.rows.iter().any(|r| r.value.starts_with("highlight")));

        // `Space` flips a yes-or-no setting, and the list comes back with the new value on
        // the row rather than going away.
        let at = pick
            .rows
            .iter()
            .position(|r| r.value == "panel.show_hidden")
            .expect("the hidden-files setting");
        let Mode::Pick(pick) = &mut app.mode else {
            unreachable!()
        };
        pick.cursor = at;
        assert!(app.cfg.panel.show_hidden, "it starts on, as FAR has it");
        press(&mut app, "Space");
        assert!(!app.cfg.panel.show_hidden, "`Space` did not flip it");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list did not come back: {:?}", app.mode)
        };
        assert_eq!(pick.cursor, at, "and it comes back on the same row");
        assert!(
            pick.rows[at].label.contains("= false"),
            "{}",
            pick.rows[at].label
        );
        // A setting that is no longer the built-in one is marked.
        assert!(
            pick.rows[at].label.ends_with('·'),
            "{}",
            pick.rows[at].label
        );

        // `Del` puts the built-in value back, and the mark goes with it.
        press(&mut app, "Del");
        assert!(app.cfg.panel.show_hidden);
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list did not come back: {:?}", app.mode)
        };
        assert!(
            !pick.rows[at].label.ends_with('·'),
            "{}",
            pick.rows[at].label
        );

        // `Enter` types a value, and one the setting cannot take is refused with a reason
        // while the list stays where it was.
        press(&mut app, "Enter");
        let Mode::Prompt(prompt) = &app.mode else {
            panic!("no prompt: {:?}", app.mode)
        };
        assert_eq!(prompt.text, "true", "the prompt opens on the value");
        let Mode::Prompt(prompt) = &mut app.mode else {
            unreachable!()
        };
        prompt.text = "maybe".to_string();
        press(&mut app, "Enter");
        assert!(app.status_error, "`maybe` is not a boolean: {}", app.status);
        assert!(matches!(app.mode, Mode::Pick(_)), "{:?}", app.mode);
        assert!(app.cfg.panel.show_hidden, "and nothing was changed");

        // A setting that is not a yes-or-no says what `Space` cannot do for it.
        let Mode::Pick(pick) = &mut app.mode else {
            unreachable!()
        };
        pick.cursor = pick
            .rows
            .iter()
            .position(|r| r.value == "ui.theme")
            .expect("the theme setting");
        press(&mut app, "Space");
        assert_eq!(app.status, app.i18n.t("opt-not-a-toggle"));
    }

    /// *Options → Code pages* is the viewer's own list, opened where there is no file to
    /// read: what it is for there is marking the three or four one uses and naming them.
    #[test]
    fn the_options_menu_opens_the_code_page_list_and_marks_a_favourite() {
        let mut app = app();
        open(&mut app, 3, "menu-codepages");
        let Mode::Pick(pick) = &app.mode else {
            panic!("no list: {}", app.status)
        };
        assert_eq!(pick.kind, crate::menu::PickKind::Codepages);
        assert!(pick.rows.len() > 30, "every code page is in it");

        // `Ins` marks the row under the cursor, and the mark is a line of the settings file
        // rather than something this session keeps to itself.
        let id = pick.rows[pick.cursor].value.clone();
        press(&mut app, "Ins");
        assert!(
            app.cfg.codepages.iter().any(|c| c.id == id && c.favourite),
            "`{id}` is not marked: {:?}",
            app.cfg.codepages
        );
        press(&mut app, "Ins");
        assert!(
            !app.cfg.codepages.iter().any(|c| c.id == id),
            "unmarking a page that has no name of its own leaves nothing behind"
        );
        press(&mut app, "Esc");
        assert!(app.mode.is_normal());
    }

    /// FAR's issue #241: the times of one file carried to another through the dialog,
    /// all three at once.
    #[test]
    fn the_attributes_dialog_copies_times_from_one_file_to_another() {
        let dir = tempfile::tempdir().unwrap();
        let old = dir.path().join("old.txt");
        let new = dir.path().join("new.txt");
        std::fs::write(&old, b"x").unwrap();
        std::fs::write(&new, b"y").unwrap();
        let then =
            std::time::SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(1_000_000_000);
        std::fs::File::options()
            .write(true)
            .open(&old)
            .unwrap()
            .set_modified(then)
            .unwrap();

        let mut app = app();
        app.panels[app.active].cwd = VPath::local(dir.path());
        let entries =
            fcmd_vfs::local::list_blocking(&app.panels[app.active].cwd, &CancelToken::new())
                .unwrap();
        let (panel, generation) = (app.active, app.panels[app.active].generation);
        app.handle_event(Event::Listed {
            panel,
            generation,
            result: Ok(entries),
        });
        let on = |app: &mut App, name: &str| {
            let row = app.panels[app.active].listing.row_of_name(name).unwrap();
            app.panels[app.active].cursor_to(row);
            press(app, "Ctrl+A");
        };

        on(&mut app, "new.txt");
        press(&mut app, "Ctrl+Shift+V");
        assert!(app.status_error, "nothing was copied yet: {}", app.status);
        press(&mut app, "Esc");

        on(&mut app, "old.txt");
        let Mode::Form(form) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        let wanted = form.text_value("attr.mtime");
        assert!(!wanted.is_empty());
        press(&mut app, "Ctrl+Shift+C");
        assert!(!app.status_error, "{}", app.status);
        press(&mut app, "Esc");

        on(&mut app, "new.txt");
        let Mode::Form(form) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_ne!(form.text_value("attr.mtime"), wanted);
        press(&mut app, "Ctrl+Shift+V");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog stays open")
        };
        assert_eq!(form.text_value("attr.mtime"), wanted, "the old file's time");
    }

    /// `Ctrl+A`: what a file is, and what the dialog then does about it.
    #[test]
    fn the_attributes_dialog_shows_what_a_file_is_and_sets_what_it_is_told() {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("one.txt");
        std::fs::write(&file, b"x").unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&file, std::fs::Permissions::from_mode(0o644)).unwrap();
        }

        let mut app = app();
        app.panels[app.active].cwd = VPath::local(dir.path());
        let entries =
            fcmd_vfs::local::list_blocking(&app.panels[app.active].cwd, &CancelToken::new())
                .unwrap();
        let (panel, generation) = (app.active, app.panels[app.active].generation);
        app.handle_event(Event::Listed {
            panel,
            generation,
            result: Ok(entries),
        });
        app.requests.clear();
        let row = app.panels[app.active]
            .listing
            .row_of_name("one.txt")
            .expect("the file is listed");
        app.panels[app.active].cursor_to(row);

        press(&mut app, "Ctrl+A");
        let Mode::Form(form) = &app.mode else {
            panic!("Ctrl+A should open the attributes dialog: {:?}", app.mode)
        };
        assert_eq!(form.kind, FormKind::Attributes);
        // The name is in it, and on Unix so is what the file is now.
        let text: String = form
            .fields
            .iter()
            .map(|f| format!("{f:?}"))
            .collect::<Vec<_>>()
            .join(" ");
        assert!(text.contains("one.txt"), "{text}");
        #[cfg(unix)]
        assert!(text.contains("rw-r--r--"), "{text}");

        // Unix: the twelve boxes are there and start from the mode the file has.
        #[cfg(unix)]
        {
            assert!(form.toggle_value("attr.ur"), "the owner may read");
            assert!(form.toggle_value("attr.uw"), "and write");
            assert!(!form.toggle_value("attr.ux"), "but not run it");
            assert!(!form.toggle_value("attr.ow"), "and the world may not write");
        }

        // Take the group's read bit off and answer the dialog: the file changes, and only in
        // the way the box said.
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let Mode::Form(form) = &mut app.mode else {
                unreachable!("the dialog is open")
            };
            let at = form
                .fields
                .iter()
                .position(
                    |f| matches!(f, crate::form::Field::Toggle { key, .. } if *key == "attr.gr"),
                )
                .expect("the row is there");
            form.cursor = at;
            press(&mut app, "Space");
            press(&mut app, "Enter");
            let (paths, change, recursive) = match app.take_requests().into_iter().next() {
                Some(Request::SetAttrs {
                    paths,
                    change,
                    recursive,
                    ..
                }) => (paths, change, recursive),
                other => panic!("no attribute change was started: {other:?}"),
            };
            // One box was pressed, so one bit is in the masks and the other eleven are
            // answered as they were: over one file the dialog still covers all twelve.
            assert_eq!(change.mode_over(0o644), 0o604, "only that bit moved");
            assert_eq!(change.mode_set | change.mode_clear, 0o7777, "all answered");
            assert_eq!(paths, vec![VPath::local(&file)]);
            assert!(!recursive, "nothing here is a directory");

            // And the worker's half of it, which is the engine doing what the box said.
            let outcome = fcmd_jobs::set_attributes(
                &fcmd_jobs::LocalFs,
                &paths,
                &change,
                recursive,
                &CancelToken::new(),
                &mut |_, _| {},
            );
            assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
            assert_eq!(
                std::fs::metadata(&file).unwrap().permissions().mode() & 0o777,
                0o604
            );
        }
    }

    /// The owner row: `chown`, which the dialog used to show and not offer.
    ///
    /// Three things, because they are the three ways the row can be answered: left alone, in
    /// which case nothing is handed to anybody; typed as a name nothing knows, which is said
    /// back rather than guessed at; and typed as the two numbers, which come through as the
    /// two numbers.
    #[cfg(unix)]
    #[test]
    fn the_attributes_dialog_hands_a_file_to_whoever_the_owner_row_names() {
        use std::os::unix::fs::MetadataExt;

        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("mine.txt");
        std::fs::write(&file, b"x").unwrap();
        let meta = std::fs::metadata(&file).unwrap();

        let mut app = app();
        app.panels[app.active].cwd = VPath::local(dir.path());
        let entries =
            fcmd_vfs::local::list_blocking(&app.panels[app.active].cwd, &CancelToken::new())
                .unwrap();
        let (panel, generation) = (app.active, app.panels[app.active].generation);
        app.handle_event(Event::Listed {
            panel,
            generation,
            result: Ok(entries),
        });
        app.requests.clear();
        let row = app.panels[app.active]
            .listing
            .row_of_name("mine.txt")
            .expect("the file is listed");
        app.panels[app.active].cursor_to(row);

        // The row is offered, and it opens at the owner the file has — so the format is in
        // front of the reader rather than in the manual.
        press(&mut app, "Ctrl+A");
        let Mode::Form(form) = &app.mode else {
            panic!("Ctrl+A opens the attributes dialog: {:?}", app.mode)
        };
        let opened = form.text_value("attr.owner");
        assert!(
            opened.contains(':'),
            "the row opens at `user:group`: {opened:?}"
        );

        // Left alone: nothing is handed to anybody, which is what stops a dialog over a
        // hundred files from giving them all to whoever the cursor was on.
        press(&mut app, "Enter");
        let change = match app.take_requests().into_iter().next() {
            Some(Request::SetAttrs { change, .. }) => change,
            other => panic!("no attribute change was started: {other:?}"),
        };
        assert!(
            !change.touches_owner(),
            "a row nobody typed in is not a chown: {:?}",
            (change.uid, change.gid)
        );
        // Answering the dialog leaves the job's own box on screen; the panels are back for
        // the next round.
        app.mode = Mode::Normal;

        // A name nothing knows: said back, and nothing is started.
        press(&mut app, "Ctrl+A");
        set_owner_row(&mut app, "fcmd-no-such-account");
        press(&mut app, "Enter");
        assert!(
            app.status.contains("fcmd-no-such-account"),
            "the name that could not be looked up is named: {}",
            app.status
        );
        assert!(
            app.take_requests().is_empty(),
            "and nothing was started for it"
        );
        // And the dialog is still there, with what was typed still in it: a refused answer
        // that took the dialog with it would make the reader type the whole thing again.
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog is back: {:?}", app.mode)
        };
        assert_eq!(form.text_value("attr.owner"), "fcmd-no-such-account");

        // The two numbers: through as the two numbers. A filesystem with no matching
        // accounts shows numbers, so typing them back has to mean them.
        press(&mut app, "Ctrl+A");
        set_owner_row(&mut app, &format!("{}:{}", meta.uid(), meta.gid()));
        press(&mut app, "Enter");
        let change = match app.take_requests().into_iter().next() {
            Some(Request::SetAttrs { change, .. }) => change,
            other => panic!("no attribute change was started: {other:?}"),
        };
        assert_eq!(change.uid, Some(meta.uid()));
        assert_eq!(change.gid, Some(meta.gid()));
    }

    /// Type a whole answer into the owner row of the dialog that is open.
    #[cfg(unix)]
    fn set_owner_row(app: &mut App, text: &str) {
        let Mode::Form(form) = &mut app.mode else {
            panic!("the dialog is open")
        };
        for field in &mut form.fields {
            if let crate::form::Field::Text {
                key, value, caret, ..
            } = field
            {
                if *key == "attr.owner" {
                    *value = text.to_string();
                    *caret = value.chars().count();
                    return;
                }
            }
        }
        panic!("the owner row is in the dialog");
    }

    /// `Ctrl+A` over several files that do not agree: the boxes for the bits they differ
    /// about open at `[?]`, and pressing `OK` without touching one leaves that bit as each
    /// file has it (SPEC 03 §7). Before this, the dialog wrote the mode of the file under the
    /// cursor onto everything selected.
    #[cfg(unix)]
    #[test]
    fn the_attributes_of_a_mixed_selection_are_asked_three_ways() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempfile::tempdir().unwrap();
        let (one, two) = (dir.path().join("one.txt"), dir.path().join("two.txt"));
        std::fs::write(&one, b"x").unwrap();
        std::fs::write(&two, b"y").unwrap();
        // They agree about the owner's bits and disagree about the group's read bit.
        std::fs::set_permissions(&one, std::fs::Permissions::from_mode(0o640)).unwrap();
        std::fs::set_permissions(&two, std::fs::Permissions::from_mode(0o600)).unwrap();

        let mut app = app();
        app.panels[app.active].cwd = VPath::local(dir.path());
        let entries =
            fcmd_vfs::local::list_blocking(&app.panels[app.active].cwd, &CancelToken::new())
                .unwrap();
        let (panel, generation) = (app.active, app.panels[app.active].generation);
        app.handle_event(Event::Listed {
            panel,
            generation,
            result: Ok(entries),
        });
        app.requests.clear();
        // Both selected, the cursor on the first.
        for name in ["one.txt", "two.txt"] {
            let row = app.panels[app.active]
                .listing
                .row_of_name(name)
                .expect("listed");
            app.panels[app.active].cursor_to(row);
            press(&mut app, "Insert");
        }
        let row = app.panels[app.active]
            .listing
            .row_of_name("one.txt")
            .expect("listed");
        app.panels[app.active].cursor_to(row);

        press(&mut app, "Ctrl+A");
        let Mode::Form(form) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        // The bit they agree about is an ordinary box; the one they do not is `[?]`.
        assert_eq!(form.tri_value("attr.ur"), Some(true), "both are readable");
        assert_eq!(form.tri_value("attr.gr"), None, "and they disagree here");
        let drawn: Vec<String> = form.rows().into_iter().map(|r| r.text).collect();
        assert!(
            drawn.iter().any(|r| r.starts_with("[?]")),
            "a mixed box is drawn as FAR draws it: {drawn:?}"
        );

        // Answer the dialog without touching anything: each file keeps the bit it had.
        press(&mut app, "Enter");
        let Some(Request::SetAttrs { paths, change, .. }) = app.take_requests().into_iter().next()
        else {
            panic!("no attribute change was started")
        };
        assert_eq!(paths.len(), 2);
        let outcome = fcmd_jobs::set_attributes(
            &fcmd_jobs::LocalFs,
            &paths,
            &change,
            false,
            &CancelToken::new(),
            &mut |_, _| {},
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let mode_of =
            |p: &std::path::Path| std::fs::metadata(p).unwrap().permissions().mode() & 0o7777;
        assert_eq!(mode_of(&one), 0o640, "the first kept its group read bit");
        assert_eq!(mode_of(&two), 0o600, "and the second kept its absence");

        // Now press that box twice — through "on" to "off" — and both files lose the bit,
        // which is the other half of three states: it can be answered as well as left.
        // (Answering the dialog left the progress box in front; the job itself is run above
        // rather than by the loop, so the panel is put back by hand.)
        app.mode = Mode::Normal;
        app.panels[app.active].selection.clear();
        for name in ["one.txt", "two.txt"] {
            let row = app.panels[app.active]
                .listing
                .row_of_name(name)
                .expect("listed");
            app.panels[app.active].cursor_to(row);
            press(&mut app, "Insert");
        }
        let row = app.panels[app.active]
            .listing
            .row_of_name("one.txt")
            .expect("listed");
        app.panels[app.active].cursor_to(row);
        press(&mut app, "Ctrl+A");
        let Mode::Form(form) = &mut app.mode else {
            panic!("the dialog is open")
        };
        let at = form
            .fields
            .iter()
            .position(|f| matches!(f, crate::form::Field::Tri { key, .. } if *key == "attr.gr"))
            .expect("the row is three-state");
        form.cursor = at;
        press(&mut app, "Space");
        press(&mut app, "Space");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog is open")
        };
        assert_eq!(
            form.tri_value("attr.gr"),
            Some(false),
            "off, not left alone"
        );
        press(&mut app, "Enter");
        let Some(Request::SetAttrs { paths, change, .. }) = app.take_requests().into_iter().next()
        else {
            panic!("no attribute change was started")
        };
        let outcome = fcmd_jobs::set_attributes(
            &fcmd_jobs::LocalFs,
            &paths,
            &change,
            false,
            &CancelToken::new(),
            &mut |_, _| {},
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert_eq!(mode_of(&one), 0o600, "the bit was taken off");
        assert_eq!(mode_of(&two), 0o600, "and the other was already without it");
    }

    /// Every list is filterable now, not only the four that were: typing narrows it, `Esc`
    /// clears what was typed before it closes anything, and where the rows have keys of
    /// their own the letters stay theirs and `Alt` and a letter is the filter.
    #[test]
    fn typing_into_a_list_narrows_it_and_esc_takes_the_filter_back_off() {
        let mut app = app();
        // The code pages: thirty-odd rows, no keys of their own — the list this is for.
        app.run(Command::OptCodepages);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert!(!pick.letters_are_hotkeys(), "no row has a key of its own");
        let all = pick.rows.len();
        assert!(all > 10, "a list worth filtering: {all}");

        press(&mut app, "k");
        press(&mut app, "o");
        press(&mut app, "i");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list closed")
        };
        assert_eq!(pick.filter, "koi");
        assert!(pick.rows.len() < all, "the list did not narrow");
        assert!(
            pick.rows
                .iter()
                .all(|r| r.label.to_lowercase().contains("koi")),
            "{:?}",
            pick.rows
        );
        // The title says what was typed, so a list with three rows in it explains itself.
        assert!(pick.heading().contains("koi"), "{}", pick.heading());

        // `Backspace` takes a letter back.
        press(&mut app, "Backspace");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list closed")
        };
        assert_eq!(pick.filter, "ko");

        // `Esc` clears the filter and keeps the list; a second one closes it.
        press(&mut app, "Esc");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the first Esc closed the list instead of the filter")
        };
        assert!(pick.filter.is_empty());
        assert_eq!(pick.rows.len(), all, "the whole list is back");
        press(&mut app, "Esc");
        assert!(matches!(app.mode, Mode::Normal), "{:?}", app.mode);
    }

    /// And `Alt+←/→` slides the rows sideways, for a list of paths wider than its box.
    #[test]
    fn a_list_of_long_rows_can_be_read_sideways() {
        let mut app = app();
        app.run(Command::OptCodepages);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.left, 0);
        press(&mut app, "Alt+Right");
        press(&mut app, "Alt+Right");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list closed")
        };
        assert_eq!(pick.left, 2);
        press(&mut app, "Alt+Left");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list closed")
        };
        assert_eq!(pick.left, 1);
        // Typing is a different list, so it starts from the left again.
        press(&mut app, "u");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list closed")
        };
        assert_eq!(pick.left, 0, "a narrowed list is read from its left");
        // And it never goes past the left edge.
        press(&mut app, "Alt+Left");
        press(&mut app, "Alt+Left");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list closed")
        };
        assert_eq!(pick.left, 0);
    }

    /// `Tab` on a dialog row that names a path completes it, as a shell does — and still
    /// goes to the buttons where there is nothing to complete, so the key never stops
    /// working.
    #[test]
    fn tab_completes_a_path_in_a_dialog_and_otherwise_walks_it() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join("target-one")).unwrap();
        std::fs::create_dir_all(dir.path().join("target-two")).unwrap();
        std::fs::create_dir_all(dir.path().join("elsewhere")).unwrap();

        let mut app = app();
        // The copy dialog, which has the destination row in it.
        press(&mut app, "Down"); // off the `..` row, onto a file
        app.run(Command::FileCopyCurrent);
        let Mode::Form(form) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(form.kind, FormKind::Copy);
        let at = form
            .fields
            .iter()
            .position(
                |f| matches!(f, crate::form::Field::Text { key, .. } if *key == "copy.target"),
            )
            .expect("the destination row is there");
        form.cursor = at;
        form.button = None;
        let typed = format!("{}/tar", dir.path().display());
        form.put_text_at_cursor(typed.clone(), typed.chars().count());

        // Two names start that way, so it goes as far as they agree and says how many.
        press(&mut app, "Tab");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed")
        };
        assert_eq!(
            form.text_value("copy.target"),
            format!("{}/target-", dir.path().display()),
            "it did not stop where the names stop agreeing"
        );
        assert!(app.status.contains('2'), "{}", app.status);
        assert!(form.button.is_none(), "Tab completed rather than leaving");

        // One more letter and one `Tab`: the whole name, with the separator a directory gets
        // so the next `Tab` goes inside it.
        let Mode::Form(form) = &mut app.mode else {
            panic!("the dialog closed")
        };
        form.type_char('o');
        press(&mut app, "Tab");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed")
        };
        assert_eq!(
            form.text_value("copy.target"),
            format!(
                "{}/target-one{}",
                dir.path().display(),
                std::path::MAIN_SEPARATOR
            ),
            "the name, with the separator this platform writes"
        );

        // And with nothing left to complete, `Tab` is what it is everywhere else in the
        // dialog: on to the next control, which here is the first row of the conflict group.
        press(&mut app, "Tab");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed")
        };
        assert!(form.button.is_none(), "Tab left the rows");
        assert!(
            matches!(
                form.fields.get(form.cursor),
                Some(crate::form::Field::Radio { .. })
            ),
            "Tab went to the next control"
        );
    }

    /// `Tab` walks the whole dialog and comes round again — rows, then buttons, then the
    /// first row — and `Shift+Tab` walks it backwards. Before this it went to the buttons
    /// and stayed there, which left no way back to a field one wanted to correct.
    #[test]
    fn tab_walks_the_whole_dialog_and_comes_round_again() {
        let mut app = app();
        app.run(Command::OptSystem);
        let Mode::Form(form) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        // Every row the cursor can stop on, and how many buttons there are under them.
        let rows = (0..form.fields.len())
            .filter(|i| {
                !matches!(
                    form.fields[*i],
                    crate::form::Field::Separator
                        | crate::form::Field::Note(_)
                        | crate::form::Field::Dim(_)
                )
            })
            .count();
        let buttons = form.buttons.len();
        assert!(rows > 1 && buttons > 1, "{rows} rows, {buttons} buttons");
        let first = form.cursor;

        // Through the rows: each `Tab` is one more row, and none of them is a button yet.
        for _ in 1..rows {
            press(&mut app, "Tab");
            let Mode::Form(form) = &app.mode else {
                panic!("the dialog closed")
            };
            assert!(form.button.is_none(), "still among the rows");
        }
        // Then the buttons, in order.
        for at in 0..buttons {
            press(&mut app, "Tab");
            let Mode::Form(form) = &app.mode else {
                panic!("the dialog closed")
            };
            assert_eq!(form.button, Some(at));
        }
        // And round to the first row again, rather than back to the first button.
        press(&mut app, "Tab");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed")
        };
        assert!(form.button.is_none(), "the ring came back to the rows");
        assert_eq!(form.cursor, first);

        // Backwards is the last button, which is the way out — one key from the first row.
        press(&mut app, "Shift+Tab");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed")
        };
        assert_eq!(form.button, Some(buttons - 1));
    }

    /// The bottom row inside a dialog is the dialog's own, as it is in FAR: the panels' keys
    /// are not on the screen, so the bar must not offer them. What it says is only what the
    /// dialog answers, which is why it is short.
    #[test]
    fn the_key_bar_in_a_dialog_is_the_dialogs_own() {
        let mut app = app();
        // With the panels in front there is no dialog bar at all, and the panels' own stands.
        assert!(app.keybar_dialog(Mods::NONE).is_none());

        app.run(Command::OptSystem);
        let bar = app.keybar_dialog(Mods::NONE).expect("a dialog is open");
        assert_eq!(
            bar.iter().map(|(n, _)| *n).collect::<Vec<_>>(),
            vec![1, 10],
            "the help page and OK, which is what a settings dialog answers"
        );
        assert_ne!(bar, app.keybar(), "it is not the panels' row");
        // Under `Ctrl` it is the key that moves the dialog, and nothing else.
        assert_eq!(
            app.keybar_dialog(Mods::CTRL)
                .expect("a dialog is open")
                .iter()
                .map(|(n, _)| *n)
                .collect::<Vec<_>>(),
            vec![5]
        );
        // Nothing the dialog answers is held down: twelve empty boxes, so the row stays
        // where it is and `F5` is still the fifth box along — not the panels' labels.
        let shift = app.keybar_dialog(Mods::SHIFT).expect("a dialog is open");
        assert_eq!(shift.len(), 12);
        assert!(shift.iter().all(|(_, label)| label.is_empty()), "{shift:?}");

        // The copy dialog has one more: the folder list, on `Alt+F10`.
        app.mode = Mode::Normal;
        press(&mut app, "Down");
        app.run(Command::FileCopyCurrent);
        let alt = app
            .keybar_dialog(Mods::ALT)
            .expect("the copy dialog is open");
        assert_eq!(alt.len(), 1);
        assert_eq!(alt[0].0, 10);

        // A list says what `F10` does there, which is leave rather than answer.
        app.mode = Mode::Normal;
        app.run(Command::PanelHistory);
        let bar = app.keybar_dialog(Mods::NONE).expect("a list is open");
        assert_eq!(bar.last().map(|(n, _)| *n), Some(10));
        assert_eq!(
            bar.last().map(|(_, l)| l.clone()),
            Some(app.i18n.t("key-cancel"))
        );
    }

    /// `F1` in a dialog is the page about dialogs, and the dialog is waiting behind it with
    /// what was typed into it still there. The bar says `Help`; this is what makes it true.
    #[test]
    fn f1_in_a_dialog_opens_the_page_about_dialogs_and_comes_back_to_it() {
        let mut app = app();
        press(&mut app, "Down");
        app.run(Command::FileCopyCurrent);
        let Mode::Form(form) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        form.set_text("copy.target", "/tmp/somewhere".to_string());
        // Pushed one column over first, so the help can be shown not to undo that.
        press(&mut app, "Ctrl+F5");
        press(&mut app, "Right");
        press(&mut app, "Esc");
        assert_eq!(app.form_offset, (1, 0));

        press(&mut app, "F1");
        let Mode::Help { chapter, .. } = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(
            *chapter,
            crate::help::Chapter::Here(crate::help::Where::Dialog)
        );

        press(&mut app, "F10");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog came back: {:?}", app.mode)
        };
        assert_eq!(form.kind, FormKind::Copy);
        assert_eq!(
            app.form_offset,
            (1, 0),
            "and where it had been pushed to is kept: `F1` did not close it"
        );
        assert_eq!(
            form.text_value("copy.target"),
            "/tmp/somewhere",
            "and what was typed into it is still there"
        );
    }

    /// A group of round boxes is one setting: the dot moves to the row that is picked, the
    /// rest of the group goes out, and the value the dialog reports is that row's.
    #[test]
    fn a_group_of_round_boxes_answers_for_the_whole_group() {
        let mut app = app();
        press(&mut app, "Down");
        app.run(Command::FileCopyCurrent);
        let Mode::Form(form) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        let group: Vec<usize> = form
            .fields
            .iter()
            .enumerate()
            .filter_map(|(i, f)| {
                matches!(f, crate::form::Field::Radio { key, .. } if *key == "copy.conflict")
                    .then_some(i)
            })
            .collect();
        assert_eq!(
            group.len(),
            7,
            "FAR's six answers, and the size one (FAR #493)"
        );
        let on = |form: &crate::form::Form| {
            form.fields
                .iter()
                .filter(|f| matches!(f, crate::form::Field::Radio { on, .. } if *on))
                .count()
        };
        assert_eq!(on(form), 1, "exactly one of them starts picked");

        // `Space` on the last row of the group picks it, and only it.
        form.cursor = *group.last().expect("a group");
        press(&mut app, "Space");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed")
        };
        assert_eq!(on(form), 1);
        assert_eq!(form.choice_value("copy.conflict"), "append");
        // The rows are drawn as round boxes, with the dot on the one that is picked.
        let rows = form.rows();
        let drawn: Vec<String> = rows
            .iter()
            .map(|r| r.text.clone())
            .filter(|t| t.starts_with('('))
            .collect();
        assert_eq!(drawn.len(), 7);
        assert_eq!(
            drawn.iter().filter(|t| t.starts_with("(•)")).count(),
            1,
            "{drawn:?}"
        );
    }

    /// `Alt+F10` on a dialog row that names a file opens the directory it is in, as a list:
    /// `Enter` on a directory walks into it, `Enter` on a file is the answer and lands in the
    /// row that asked, and `Esc` leaves the row as it was.
    #[test]
    fn alt_f10_on_a_row_that_names_a_file_browses_for_one() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join("keys")).unwrap();
        std::fs::write(dir.path().join("keys").join("id_ed25519"), b"-").unwrap();
        std::fs::write(dir.path().join("notes.txt"), b"-").unwrap();
        let here = dir.path().display().to_string();

        let mut app = app();
        app.mode = Mode::Form(Box::new(crate::form::Form::site(None, &app.i18n)));
        let Mode::Form(form) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        form.cursor = form
            .fields
            .iter()
            .position(|f| matches!(f, crate::form::Field::Text { key, .. } if *key == "site.key"))
            .expect("the key-file row");
        form.set_text("site.key", here.clone());

        // The row names a directory, so that is where the list opens: `..` above it, the
        // directories next with a separator after the name, then the files.
        press(&mut app, "Alt+F10");
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::Browse);
        assert_eq!(pick.title, here, "the heading says which directory it is");
        let labels: Vec<String> = pick.rows.iter().map(|r| r.label.clone()).collect();
        assert_eq!(labels.first().map(String::as_str), Some(".."));
        let folder = format!("keys{}", std::path::MAIN_SEPARATOR);
        assert!(labels.contains(&folder), "{labels:?}");
        assert!(labels.contains(&"notes.txt".to_string()), "{labels:?}");
        assert!(app.browse_for.is_some(), "the dialog waits behind it");

        // `Enter` on a directory goes into it rather than answering anything.
        let at = labels
            .iter()
            .position(|label| *label == folder)
            .expect("the folder");
        let Mode::Pick(pick) = &mut app.mode else {
            panic!("the list closed")
        };
        pick.cursor = at;
        press(&mut app, "Enter");
        let Mode::Pick(pick) = &app.mode else {
            panic!("it is still a list: {:?}", app.mode)
        };
        assert_eq!(pick.title, dir.path().join("keys").display().to_string());

        // `Esc` puts the dialog back with the row exactly as it was.
        press(&mut app, "Esc");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog came back: {:?}", app.mode)
        };
        assert_eq!(form.text_value("site.key"), here);
        assert!(app.browse_for.is_none());

        // And again, as far as the file: that is the answer.
        press(&mut app, "Alt+F10");
        let Mode::Pick(pick) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        pick.cursor = pick
            .rows
            .iter()
            .position(|r| r.label == folder)
            .expect("the folder");
        press(&mut app, "Enter");
        let Mode::Pick(pick) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        pick.cursor = pick
            .rows
            .iter()
            .position(|r| r.label == "id_ed25519")
            .expect("the key file");
        press(&mut app, "Enter");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog came back with the answer: {:?}", app.mode)
        };
        assert_eq!(
            form.text_value("site.key"),
            dir.path()
                .join("keys")
                .join("id_ed25519")
                .display()
                .to_string()
        );
        assert!(app.browse_for.is_none());
    }

    /// `Ctrl+F5` hands the arrows to the dialog, so it can be pushed off whatever it is
    /// covering; `Enter` and `Esc` leave it where it was put without answering or closing it.
    #[test]
    fn ctrl_f5_moves_a_dialog_and_enter_only_stops_moving_it() {
        let mut app = app();
        app.run(Command::OptSystem);
        assert!(matches!(app.mode, Mode::Form(_)), "{:?}", app.mode);
        assert_eq!(app.form_offset, (0, 0));

        press(&mut app, "Ctrl+F5");
        assert!(app.form_moving);
        press(&mut app, "Down");
        press(&mut app, "Down");
        press(&mut app, "Right");
        assert_eq!(app.form_offset, (1, 2), "the arrows moved the dialog");

        // The rows were not walked while the dialog was being moved.
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed")
        };
        assert_eq!(form.cursor_row(), 0, "the cursor stayed where it was");

        // `Enter` stops the move and does not answer the dialog.
        press(&mut app, "Enter");
        assert!(!app.form_moving);
        assert!(matches!(app.mode, Mode::Form(_)), "Enter answered it");
        assert_eq!(app.form_offset, (1, 2), "and it stayed where it was put");

        // `Esc` now closes it as it always did, and the offset goes with the dialog.
        press(&mut app, "Esc");
        assert!(matches!(app.mode, Mode::Normal), "{:?}", app.mode);
        press(&mut app, "Down");
        assert_eq!(
            app.form_offset,
            (0, 0),
            "the next dialog opens where it belongs"
        );
    }

    /// The key bar follows the modifier, and what it shows is what the keymap really does.
    #[test]
    fn the_key_bar_changes_with_the_modifier_and_never_lies() {
        let mut app = app();
        let plain = app.keybar_for(Mods::NONE);
        assert_eq!(plain, app.keybar());

        let shift = app.keybar_for(Mods::SHIFT);
        let labels: Vec<&str> = shift.iter().map(|(_, l)| l.as_str()).collect();
        assert!(labels.contains(&"Add"), "{labels:?}");
        assert!(labels.contains(&"Extrct"), "{labels:?}");
        assert!(labels.contains(&"ArcCmd"), "{labels:?}");
        assert!(labels.contains(&"SelUp"), "{labels:?}");

        let ctrl = app.keybar_for(Mods::CTRL);
        assert_eq!(
            ctrl.iter().find(|(n, _)| *n == 1).map(|(_, l)| l.as_str()),
            Some("Left")
        );
        let alt = app.keybar_for(Mods::ALT);
        assert_eq!(
            alt.iter().find(|(n, _)| *n == 7).map(|(_, l)| l.as_str()),
            Some("Find")
        );

        // Every label on a modifier bar belongs to a key that really runs something: the bar
        // is built from the keymap, so it cannot promise what the program will not do.
        for mods in [Mods::SHIFT, Mods::CTRL, Mods::ALT] {
            for (n, label) in app.keybar_for(mods) {
                let key = Key {
                    code: KeyCode::F(n),
                    mods,
                };
                assert!(
                    app.keymap.resolve(&[Scope::Panel], key).is_some(),
                    "F{n} is on the bar as `{label}` and bound to nothing"
                );
            }
        }

        // And the bar goes back to plain as soon as the key is pressed.
        app.handle_input(Input::Mods(Mods::SHIFT));
        assert_eq!(app.held, Mods::SHIFT);
        press(&mut app, "Shift+F11");
        assert_eq!(app.held, Mods::NONE);
        // `Shift+F11` is FAR's `Group`: the sort groups, not the folders-first flag, which
        // is a setting in the panel dialog here as it is there.
        assert!(
            app.panel().sort.groups,
            "Shift+F11 did not turn the sort groups on"
        );
    }

    /// The disk-usage list asks for every unmeasured folder, shows it as still to come, fills
    /// it in when the size arrives — moving it to the top if it is the biggest — and `Enter`
    /// on it goes in.
    #[test]
    fn disk_usage_measures_fills_in_and_goes_in() {
        let mut app = app();
        app.requests.clear();
        press(&mut app, "Alt+Shift+F3");
        let asked: Vec<String> = app
            .requests
            .iter()
            .filter_map(|r| match r {
                Request::DirSize { path, .. } => Some(path.display_name()),
                _ => None,
            })
            .collect();
        assert_eq!(asked, vec!["docs".to_string()]);
        let Mode::Pick(pick) = &app.mode else {
            panic!("no list: {:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::Usage);
        let docs = pick.rows.iter().find(|r| r.value == "docs").unwrap();
        assert!(docs.label.contains('…'), "{}", docs.label);
        assert_eq!(pick.rows[0].value, "c.rs", "the largest file first");

        app.handle_event(Event::DirSized {
            panel: 0,
            path: VPath::local("/home/mb/docs"),
            bytes: 10_000,
            files: 3,
        });
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list closed: {:?}", app.mode)
        };
        assert_eq!(pick.rows[0].value, "docs", "{:#?}", pick.rows);
        assert!(pick.rows[0].label.contains('█'), "{}", pick.rows[0].label);
        assert!(pick.rows[0].label.contains('%'), "{}", pick.rows[0].label);
        // The cursor stayed on the row it was on, `c.rs`, which is now second.
        assert_eq!(pick.chosen().unwrap().value, "c.rs");

        app.requests.clear();
        press(&mut app, "Home");
        press(&mut app, "Enter");
        assert!(matches!(app.mode, Mode::Normal));
        assert!(
            app.requests
                .iter()
                .any(|r| matches!(r, Request::Read { path, .. } if path.display_name() == "docs")),
            "Enter goes into the folder: {:?}",
            app.requests
        );
    }

    /// `Tab` in the disk usage list asks for the whole tree, the screen says it is measuring
    /// until the walk answers, and then `Enter` and `Backspace` walk the tree, `Tab` changes
    /// between the map and the list, and `Enter` on a file leaves the panel on it.
    #[test]
    fn the_usage_map_is_walked_by_a_worker_and_enter_on_a_file_moves_the_panel() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join("big/inner")).unwrap();
        std::fs::write(dir.path().join("big/inner/film.mkv"), vec![0u8; 4000]).unwrap();
        std::fs::write(dir.path().join("big/notes.txt"), vec![0u8; 1000]).unwrap();
        std::fs::write(dir.path().join("small.rs"), vec![0u8; 2000]).unwrap();
        let mut app = editing_app(dir.path());
        let cwd = app.panels[0].cwd.clone();
        press(&mut app, "Alt+Shift+F3");
        app.requests.clear();
        press(&mut app, "Tab");
        let Mode::Usage(view) = &app.mode else {
            panic!("no map: {:?}", app.mode)
        };
        assert!(view.tree.is_none(), "nothing is walked by the key itself");
        let Some(Request::UsageTree { id, root, cancel }) = app
            .take_requests()
            .into_iter()
            .find(|r| matches!(r, Request::UsageTree { .. }))
        else {
            panic!("no walk was asked for")
        };
        assert_eq!(root, cwd);
        // The walk reports, and the screen keeps the figure.
        app.handle_event(Event::UsageProgress {
            id,
            files: 2,
            bytes: 5000,
        });
        assert!(matches!(&app.mode, Mode::Usage(v) if v.progress == (2, 5000)));
        // An answer that is another walk's is not this screen's.
        let tree = fcmd_jobs::usage::walk(&fcmd_jobs::LocalFs, &root, &cancel, &mut |_, _| {});
        app.handle_event(Event::UsageTree {
            id: id + 1,
            tree: tree.clone(),
        });
        assert!(matches!(&app.mode, Mode::Usage(v) if v.tree.is_none()));
        app.handle_event(Event::UsageTree { id, tree });

        let chosen = |app: &App| -> String {
            let Mode::Usage(view) = &app.mode else {
                panic!("the map closed: {:?}", app.mode)
            };
            let tree = view.tree.as_ref().expect("the tree is there");
            tree.node(view.chosen().expect("a row")).name.clone()
        };
        assert_eq!(chosen(&app), "big", "the largest first");
        press(&mut app, "Backspace");
        assert!(app.status_error, "nothing above the folder that was asked");
        press(&mut app, "Enter");
        assert_eq!(chosen(&app), "inner");
        press(&mut app, "Enter");
        assert_eq!(chosen(&app), "film.mkv");
        press(&mut app, "Backspace");
        assert_eq!(chosen(&app), "inner", "back on the folder that was left");
        // The list of the same folder, where the arrows are rows.
        press(&mut app, "Tab");
        assert!(matches!(&app.mode, Mode::Usage(v) if v.list));
        press(&mut app, "Down");
        assert_eq!(chosen(&app), "notes.txt");
        app.requests.clear();
        press(&mut app, "Enter");
        assert!(matches!(app.mode, Mode::Normal), "{:?}", app.mode);
        let want = cwd.join("big");
        assert!(
            app.requests
                .iter()
                .any(|r| matches!(r, Request::Read { path, .. } if *path == want)),
            "the panel goes to the file's folder: {:?}",
            app.requests
        );
        assert_eq!(app.panels[0].want_cursor.as_deref(), Some("notes.txt"));
    }

    /// `Esc` while the tree is still being walked stops the walk and closes the screen, and
    /// `G` on a folder takes the panel into it.
    #[test]
    fn the_usage_map_stops_its_walk_on_esc_and_g_goes_to_a_folder() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir(dir.path().join("docs")).unwrap();
        std::fs::write(dir.path().join("docs/a.md"), vec![0u8; 100]).unwrap();
        let mut app = editing_app(dir.path());
        let cwd = app.panels[0].cwd.clone();
        press(&mut app, "Alt+Shift+F3");
        press(&mut app, "Tab");
        let cancel = match &app.mode {
            Mode::Usage(view) => view.cancel.clone(),
            other => panic!("no map: {other:?}"),
        };
        // Any other key waits for the walk; `Esc` ends it.
        press(&mut app, "Enter");
        assert!(matches!(app.mode, Mode::Usage(_)));
        assert!(!cancel.is_cancelled());
        press(&mut app, "Esc");
        assert!(matches!(app.mode, Mode::Normal));
        assert!(cancel.is_cancelled(), "the worker is told to stop");

        press(&mut app, "Alt+Shift+F3");
        app.requests.clear();
        press(&mut app, "Tab");
        let Some(Request::UsageTree { id, root, cancel }) = app.take_requests().pop() else {
            panic!("no walk was asked for")
        };
        let tree = fcmd_jobs::usage::walk(&fcmd_jobs::LocalFs, &root, &cancel, &mut |_, _| {});
        app.handle_event(Event::UsageTree { id, tree });
        press(&mut app, "g");
        assert!(matches!(app.mode, Mode::Normal));
        let want = cwd.join("docs");
        assert!(
            app.requests
                .iter()
                .any(|r| matches!(r, Request::Read { path, .. } if *path == want)),
            "{:?}",
            app.requests
        );
    }

    fn rename_preview(app: &App) -> Vec<String> {
        let Mode::Form(form) = &app.mode else {
            panic!("no dialog: {:?}", app.mode)
        };
        assert_eq!(form.kind, FormKind::MultiRename);
        form.fields
            .iter()
            .filter_map(|f| match f {
                crate::form::Field::Note(n) => Some(n.clone()),
                _ => None,
            })
            .collect()
    }

    /// The whole road: two files selected, a mask typed and the preview following each key,
    /// OK starting one rename of both, the answer offering undo, and undo the same plan the
    /// other way round.
    #[test]
    fn a_multi_rename_previews_renames_and_undoes() {
        let mut app = app();
        app.panels[0].cursor = 3; // b.rs
        press(&mut app, "Ins");
        press(&mut app, "Ins"); // and c.rs
        press(&mut app, "Ctrl+Shift+F6");
        assert!(rename_preview(&app).iter().any(|l| l.contains("b.rs =")));
        // The caret is at the end of `[N]`: what is typed goes after it.
        type_text(&mut app, "_old");
        let preview = rename_preview(&app);
        assert!(
            preview.iter().any(|l| l.contains("b.rs → b_old.rs")),
            "{preview:#?}"
        );
        assert!(
            preview.iter().any(|l| l.contains("c.rs → c_old.rs")),
            "{preview:#?}"
        );

        app.requests.clear();
        press(&mut app, "F10");
        let (dir, plan, undo) = app
            .requests
            .iter()
            .find_map(|r| match r {
                Request::Rename { dir, plan, undo } => Some((dir.clone(), plan.clone(), *undo)),
                _ => None,
            })
            .expect("OK starts the rename");
        assert!(!undo);
        assert_eq!(
            plan,
            vec![
                ("b.rs".to_string(), "b_old.rs".to_string()),
                ("c.rs".to_string(), "c_old.rs".to_string())
            ]
        );
        app.handle_event(Event::Renamed {
            dir: dir.clone(),
            plan: plan.clone(),
            undo: false,
            result: Ok(2),
        });
        assert!(app.status.contains('2'), "{}", app.status);

        app.requests.clear();
        app.run(Command::FileMultiRenameUndo);
        let back = app
            .requests
            .iter()
            .find_map(|r| match r {
                Request::Rename {
                    plan, undo: true, ..
                } => Some(plan.clone()),
                _ => None,
            })
            .expect("undo starts the reverse");
        assert_eq!(
            back,
            vec![
                ("b_old.rs".to_string(), "b.rs".to_string()),
                ("c_old.rs".to_string(), "c.rs".to_string())
            ]
        );
        app.handle_event(Event::Renamed {
            dir,
            plan: back,
            undo: true,
            result: Ok(2),
        });
        assert!(app.rename_undo.is_none(), "an undo is not itself undone");
    }

    /// Two files to one name: the preview says which, and OK leaves the dialog open with
    /// nothing started — all or nothing.
    #[test]
    fn a_multi_rename_with_a_collision_starts_nothing() {
        let mut app = app();
        app.panels[0].cursor = 3;
        press(&mut app, "Ins");
        press(&mut app, "Ins");
        press(&mut app, "Ctrl+Shift+F6");
        for _ in 0..3 {
            press(&mut app, "Backspace");
        }
        type_text(&mut app, "same");
        let preview = rename_preview(&app);
        assert!(preview.iter().any(|l| l.starts_with('✗')), "{preview:#?}");
        app.requests.clear();
        press(&mut app, "F10");
        assert!(matches!(app.mode, Mode::Form(_)), "the dialog stays open");
        assert!(!app
            .requests
            .iter()
            .any(|r| matches!(r, Request::Rename { .. })));
    }

    /// A `.gz` holds one file. A folder in the dialog is refused while it is still open, with
    /// the tar that would take it named; one file starts a job, named `a.txt.gz` the way
    /// `gzip` would name it.
    #[test]
    fn a_gz_is_packed_from_one_file_and_a_folder_is_sent_to_the_tar() {
        let mut app = app();
        app.last_pack = fcmd_arc::Format::Gz;
        app.panels[0].cursor = 1; // docs, a directory
        app.run(Command::FilePack);
        app.requests.clear();
        press(&mut app, "F10");
        assert!(
            matches!(app.mode, Mode::Form(_)),
            "the dialog should stay open: {:?}",
            app.mode
        );
        assert!(
            !app.requests
                .iter()
                .any(|r| matches!(r, Request::Pack { .. })),
            "a folder must not start a gz"
        );
        let said = app.status.clone();
        assert!(said.contains("tar.gz"), "{said}");

        let mut app = app_with_cursor_on_a_file();
        app.last_pack = fcmd_arc::Format::Gz;
        app.run(Command::FilePack);
        app.requests.clear();
        press(&mut app, "F10");
        let (archive, format) = app
            .requests
            .iter()
            .find_map(|r| match r {
                Request::Pack {
                    archive, format, ..
                } => Some((archive.clone(), *format)),
                _ => None,
            })
            .expect("one file starts a pack");
        assert_eq!(format, fcmd_arc::Format::Gz);
        assert!(archive.to_string().ends_with("a.txt.gz"), "{archive}");
    }

    fn app_with_cursor_on_a_file() -> App {
        let mut app = app();
        app.panels[0].cursor = 2; // a.txt
        app
    }

    /// The archive dialog can be told to clear up after itself — but only if the archive was
    /// really written. A pack that failed must leave the originals where they are.
    #[test]
    fn the_originals_go_only_after_an_archive_that_was_written() {
        let run = |clean: bool| {
            let mut app = app();
            app.panels[0].cursor = 2; // a.txt
            app.run(Command::FilePack);
            let Mode::Form(form) = &app.mode else {
                panic!("no dialog: {:?}", app.mode)
            };
            // Down to the `delete after archiving` row and tick it, as a user would.
            let row = form
                .fields
                .iter()
                .position(|f| matches!(f, crate::form::Field::Toggle { key, .. } if *key == "pack.delete"))
                .expect("the dialog has the row");
            for _ in 0..row {
                press(&mut app, "Down");
            }
            press(&mut app, "Space");
            assert!(
                matches!(&app.mode, Mode::Form(f) if f.toggle_value("pack.delete")),
                "the row did not tick"
            );
            app.requests.clear();
            press(&mut app, "F10"); // the shortcut for OK
            let id = match app.requests.iter().find_map(|r| match r {
                Request::Pack { id, .. } => Some(*id),
                _ => None,
            }) {
                Some(id) => id,
                None => panic!("no pack was started: {:?}", app.requests),
            };
            app.requests.clear();
            let outcome = Outcome {
                files: 1,
                bytes: 100,
                errors: if clean {
                    Vec::new()
                } else {
                    vec![(VPath::local("/home/mb/a.txt"), "no room".into())]
                },
                ..Outcome::default()
            };
            app.handle_event(Event::JobDone {
                id,
                kind: JobKind::Pack,
                outcome,
            });
            app.requests
                .iter()
                .filter_map(|r| match r {
                    Request::Job { spec, .. } if spec.kind == JobKind::Delete => {
                        Some(spec.sources.clone())
                    }
                    _ => None,
                })
                .next()
        };

        let deleted = run(true).expect("the originals go after a clean pack");
        assert_eq!(deleted.len(), 1);
        assert!(deleted[0].to_string().ends_with("a.txt"), "{deleted:?}");
        assert!(
            run(false).is_none(),
            "a pack that failed must not delete the files it was given"
        );
    }

    /// `Alt+F1` is a table, not a list of paths: every row says what the thing is, and the
    /// rows that are not filesystems carry a number to reach them by.
    #[test]
    fn the_drive_dialog_is_a_table_and_its_panels_are_numbered() {
        let mut app = app();
        app.connected.push("sftp://mb@host:22".into());
        app.run(Command::PanelDrive(fcmd_cmd::Side::Left));
        let Mode::Pick(pick) = &app.mode else {
            panic!("no dialog: {:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::Drives);

        // The first row is a place on this machine — `/` on Unix, a drive letter on Windows
        // — and it says what it is rather than only where it is.
        let first = pick.rows.first().expect("at least one drive");
        assert!(
            first.label.split_whitespace().count() > 1,
            "the row has no columns: {}",
            first.label
        );
        assert!(
            pick.rows.iter().any(|r| r.value.ends_with(['/', '\\'])),
            "no filesystem among the drives: {:?}",
            pick.rows
        );

        // The connection is below the drives, numbered, and the number reaches it. After it
        // come the panels that are not filesystems at all, numbered on from there.
        let connection = pick
            .rows
            .iter()
            .position(|r| r.value == "sftp://mb@host:22/")
            .expect("the open connection is a row");
        assert_eq!(pick.rows[connection].hotkey, Some('0'));
        assert_eq!(pick.by_hotkey('0'), Some(connection));
        for value in [":netbox", ":processes", ":temp"] {
            assert!(
                pick.rows.iter().any(|r| r.value == value),
                "{value} is not offered: {:?}",
                pick.rows
            );
        }
        // And the number column is drawn for everyone once anybody has one.
        let lines = pick.lines();
        assert!(lines[connection].contains('0'), "{:?}", lines[connection]);

        press(&mut app, "0");
        assert!(app.mode.is_normal(), "the number did not take the row");
        assert!(
            app.panels[0]
                .cwd
                .to_string()
                .starts_with("sftp://mb@host:22"),
            "{}",
            app.panels[0].cwd
        );
    }

    /// `F8` on the process list ends the process under the cursor — after a question whose
    /// lit button is *Cancel*, and with the list read again once it is gone.
    #[test]
    fn f8_on_the_process_list_ends_the_process_after_asking() {
        let mut app = app();
        app.open_process_panel(0);
        if app.panels[0].temp_origin() != Some(":processes") {
            return;
        }
        app.panels[0].cursor = 0;
        let row = app.panels[0].current().unwrap().clone();
        let pid: u32 = app.panels[0]
            .path_of(&row)
            .display_name()
            .parse()
            .expect("a process row ends in its pid");
        app.take_requests();
        press(&mut app, "F8");
        let Mode::Confirm(c) = &app.mode else {
            panic!("a question first: {:?}", app.mode)
        };
        assert_eq!(c.button, 1, "Cancel is lit");
        assert!(c.lines[0].contains(&pid.to_string()), "{:?}", c.lines);
        press(&mut app, "Esc");
        assert!(app.take_requests().is_empty(), "nothing on Esc");
        press(&mut app, "Delete");
        press(&mut app, "Left");
        press(&mut app, "Enter");
        let asked = app.take_requests().into_iter().find_map(|r| match r {
            Request::KillProcess { pid, .. } => Some(pid),
            _ => None,
        });
        assert_eq!(asked, Some(pid));
        app.handle_event(Event::ProcessKilled {
            side: 0,
            name: "x".into(),
            result: Err("Access is denied".into()),
        });
        assert!(app.status_error && app.status.contains("Access is denied"));
    }

    /// `F3` on the process list is the process, not a file: the card says what the system
    /// will say about it, and it says it on every platform — the pid comes off the row and
    /// the answers come from the system there and then.
    #[test]
    fn f3_on_the_process_list_shows_the_process() {
        let mut app = app();
        app.open_process_panel(0);
        // A platform whose process list we cannot read says so and leaves the panel alone —
        // macOS and the BSDs keep it behind a `sysctl` we do not call (SPEC 02 §14).
        if app.panels[0].temp_origin() != Some(":processes") {
            assert!(
                !app.status.is_empty(),
                "nothing opened and nothing was said"
            );
            return;
        }
        // Onto a row that is a process rather than the parent entry.
        app.panels[0].cursor = 0;
        // The pid of the row, which is the one thing every platform knows about it.
        let pid = app.panels[0]
            .current()
            .map(|e| app.panels[0].path_of(e))
            .map(|p| p.display_name().to_string())
            .expect("a row");
        press(&mut app, "F3");
        // The card is a page and is read in the viewer: environment and loaded modules are
        // longer than any screen, and a dialog cannot scroll.
        let Mode::Viewer(viewer) = &mut app.mode else {
            panic!("no card: {:?}", app.mode)
        };
        let rows = viewer.rows(80, 40);
        assert!(rows.len() >= 3, "the card says almost nothing: {rows:?}");
        let text = rows
            .iter()
            .map(|r| r.text.as_str())
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            text.contains(&pid),
            "the card is about something else: {text}"
        );
        // Its own name is the frame's, so the viewer does not claim to have opened a file.
        assert!(viewer.path.display_name().contains(&pid), "{}", viewer.path);
        // And `Esc` closes it and leaves the panel alone.
        press(&mut app, "Esc");
        assert!(app.mode.is_normal());
        assert_eq!(app.panels[0].temp_origin(), Some(":processes"));
    }

    /// Comparing the whole of two trees: the pairing is by the path under each root, and the
    /// answer is a panel of what differs rather than a selection nobody can see.
    #[test]
    fn two_trees_are_compared_all_the_way_down() {
        let left = tempfile::tempdir().expect("left");
        let right = tempfile::tempdir().expect("right");
        // The same path on both sides, with the same bytes: not a difference.
        for root in [left.path(), right.path()] {
            std::fs::create_dir(root.join("sub")).expect("sub");
            std::fs::write(root.join("sub").join("same.txt"), b"identical").expect("same");
        }
        // The same path, different bytes and a different size.
        std::fs::write(left.path().join("sub").join("differs.txt"), b"one").expect("l");
        std::fs::write(right.path().join("sub").join("differs.txt"), b"another").expect("r");
        // One side only, each way, and both deep enough to need the walk.
        std::fs::write(left.path().join("sub").join("mine.txt"), b"mine").expect("mine");
        std::fs::write(right.path().join("sub").join("theirs.txt"), b"theirs").expect("theirs");

        let mut app = app();
        app.panels[0].cwd = VPath::local(left.path());
        app.panels[1].cwd = VPath::local(right.path());
        app.active = 0;
        app.cfg.compare.subdirs = true;
        // By size alone. The two copies of `same.txt` are written a moment apart, and on a
        // filesystem that keeps the time to the nanosecond that moment is a difference —
        // which is true of the comparison and nothing to do with what this test is about.
        app.cfg.compare.time = false;
        app.run(Command::ToolCompare);
        press(&mut app, "F10");
        let (id, l, r, work, cancel) = app
            .take_requests()
            .into_iter()
            .find_map(|request| match request {
                Request::CompareTrees {
                    id,
                    left,
                    right,
                    work,
                    cancel,
                } => Some((id, left, right, work, cancel)),
                _ => None,
            })
            .expect("a comparison of the trees was asked for");
        assert!(work.depth.is_none(), "0 means all the way down");

        let (tx, rx) = std::sync::mpsc::channel();
        crate::run_compare_trees(id, l, r, work, cancel, tx);
        while let Ok(event) = rx.try_recv() {
            app.handle_event(event);
        }

        assert_eq!(app.panels[0].temp_origin(), Some(":compare"));
        let rows: Vec<String> = (0..app.panels[0].listing.len())
            .filter_map(|row| app.panels[0].listing.row(row))
            .map(|e| e.name_str().to_string())
            .collect();
        assert_eq!(rows.len(), 3, "{rows:?}");
        assert!(
            rows.iter()
                .any(|r| r.starts_with('≠') && r.ends_with("differs.txt")),
            "{rows:?}"
        );
        assert!(
            rows.iter()
                .any(|r| r.starts_with('→') && r.ends_with("mine.txt")),
            "{rows:?}"
        );
        assert!(
            rows.iter()
                .any(|r| r.starts_with('←') && r.ends_with("theirs.txt")),
            "{rows:?}"
        );
        // The one that is the same on both sides is not a row at all.
        assert!(!rows.iter().any(|r| r.contains("same.txt")), "{rows:?}");
        // Each row is a real file, so the keys that act on a file act on it.
        for row in 0..app.panels[0].listing.len() {
            let entry = app.panels[0].listing.row(row).expect("a row");
            let path = app.panels[0].path_of(entry);
            assert!(path.as_path().exists(), "{path}");
        }

        // One level deep leaves `sub` unopened, so the trees look the same from up there.
        app.cfg.compare.depth = 1;
        app.run(Command::ToolCompare);
        press(&mut app, "F10");
        let (id, l, r, work, cancel) = app
            .take_requests()
            .into_iter()
            .find_map(|request| match request {
                Request::CompareTrees {
                    id,
                    left,
                    right,
                    work,
                    cancel,
                } => Some((id, left, right, work, cancel)),
                _ => None,
            })
            .expect("asked again");
        assert_eq!(work.depth, Some(1));
        let (tx, rx) = std::sync::mpsc::channel();
        crate::run_compare_trees(id, l, r, work, cancel, tx);
        while let Ok(event) = rx.try_recv() {
            app.handle_event(event);
        }
        assert!(!app.status.is_empty());
    }

    /// The third thing the compare plugin does: find what is a copy of what, under one
    /// directory, and show the groups rather than deleting anything.
    #[test]
    fn duplicates_are_found_grouped_and_shown_as_a_panel() {
        let dir = tempfile::tempdir().expect("temp dir");
        std::fs::write(dir.path().join("one.txt"), b"the very same bytes").expect("one");
        std::fs::create_dir(dir.path().join("sub")).expect("sub");
        std::fs::write(
            dir.path().join("sub").join("two.txt"),
            b"the very same bytes",
        )
        .expect("two");
        // Not a copy of anything, and must not be in the list.
        std::fs::write(dir.path().join("other.txt"), b"something else entirely").expect("other");
        // Two empty files are copies of each other and are left out on purpose: every
        // machine has hundreds, and a list that starts with them is a list nobody reads.
        std::fs::write(dir.path().join("empty-a.txt"), b"").expect("empty a");
        std::fs::write(dir.path().join("empty-b.txt"), b"").expect("empty b");

        let mut app = app();
        app.panels[0].cwd = VPath::local(dir.path());
        app.active = 0;
        app.run(Command::ToolDuplicates);
        let (id, root, cancel) = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::Duplicates { id, root, cancel } => Some((id, root, cancel)),
                _ => None,
            })
            .expect("a hunt was asked for");

        // The real worker, on this thread: the walk, the hashing and the grouping are the
        // ones the binary runs.
        let (tx, rx) = std::sync::mpsc::channel();
        crate::run_duplicates(id, root, cancel, tx);
        let mut finished = false;
        while let Ok(event) = rx.try_recv() {
            if matches!(event, Event::DuplicatesDone { .. }) {
                finished = true;
            }
            app.handle_event(event);
        }
        assert!(finished, "the hunt said nothing");

        assert_eq!(app.panels[0].temp_origin(), Some(":duplicates"));
        let rows: Vec<String> = (0..app.panels[0].listing.len())
            .filter_map(|r| app.panels[0].listing.row(r))
            .map(|e| e.name_str().to_string())
            .collect();
        assert_eq!(rows.len(), 2, "{rows:?}");
        assert!(rows.iter().all(|r| r.starts_with("001")), "{rows:?}");
        assert!(rows.iter().any(|r| r.ends_with("one.txt")), "{rows:?}");
        assert!(rows.iter().any(|r| r.contains("two.txt")), "{rows:?}");
        assert!(
            !rows
                .iter()
                .any(|r| r.contains("other") || r.contains("empty")),
            "{rows:?}"
        );
        // The sentence says what was found and what it is costing.
        assert!(app.status.contains('1'), "{}", app.status);
        // And the rows are the real files: a delete out of this panel deletes them.
        let first = app.panels[0].current().expect("a row");
        let path = app.panels[0].path_of(first);
        assert!(path.as_path().exists(), "{path}");
    }

    /// FAR's last two sort keys: neither field is in the listing, so the panel asks for it
    /// and sorts again when the answer arrives.
    #[test]
    fn sorting_by_description_asks_for_the_file_and_sorts_when_it_comes() {
        let mut app = app();
        app.handle_event(Event::Listed {
            panel: 0,
            generation: app.panels[0].listing.generation,
            result: Ok(vec![
                entry("alpha.txt", EntryKind::File, 10),
                entry("beta.txt", EntryKind::File, 20),
                entry("gamma.txt", EntryKind::File, 30),
            ]),
        });
        app.take_requests();

        // `Ctrl+F10` is FAR's key for it, and it asks for the descriptions the way the view
        // that shows them does.
        press(&mut app, "Ctrl+F10");
        assert_eq!(app.panels[0].sort.key, SortKey::Descr);
        let asked = app
            .take_requests()
            .into_iter()
            .any(|r| matches!(r, Request::Descriptions { .. }));
        assert!(asked, "the descriptions were not asked for");

        // Until they arrive the order is what it was; when they do, it is by description,
        // and the files nobody described are after the ones somebody did.
        let mut descriptions = fcmd_core::descriptions::Descriptions::default();
        descriptions.set("gamma.txt", "the first thing to read");
        descriptions.set("alpha.txt", "zebra, so it sorts last of the two");
        app.handle_event(Event::Descriptions {
            panel: 0,
            generation: app.panels[0].generation,
            descriptions,
        });
        let rows: Vec<String> = (0..app.panels[0].listing.len())
            .filter_map(|row| app.panels[0].listing.row(row))
            .map(|e| e.name_str().to_string())
            .collect();
        assert_eq!(rows, vec!["gamma.txt", "alpha.txt", "beta.txt"], "{rows:?}");

        // And by owner, on FAR's other key, with the same shape.
        press(&mut app, "Ctrl+F11");
        assert_eq!(app.panels[0].sort.key, SortKey::Owner);
        let asked = app
            .take_requests()
            .into_iter()
            .any(|r| matches!(r, Request::Owners { .. }));
        assert!(asked, "the owners were not asked for");
        let owners = [
            (
                "beta.txt".to_string(),
                ("ada".to_string(), "staff".to_string()),
            ),
            (
                "alpha.txt".to_string(),
                ("zoe".to_string(), "staff".to_string()),
            ),
        ]
        .into_iter()
        .collect();
        app.handle_event(Event::Owners {
            panel: 0,
            generation: app.panels[0].generation,
            owners,
        });
        let rows: Vec<String> = (0..app.panels[0].listing.len())
            .filter_map(|row| app.panels[0].listing.row(row))
            .map(|e| e.name_str().to_string())
            .collect();
        assert_eq!(rows, vec!["beta.txt", "alpha.txt", "gamma.txt"], "{rows:?}");
    }

    /// The comparison dialog: what it is told is what it keeps, and what it keeps is what
    /// the comparison then means by "the same file".
    #[test]
    fn the_comparison_dialog_keeps_what_it_is_told() {
        use std::time::{Duration, SystemTime};

        let mut app = app();
        // Two listings holding one name each, a second apart and the same size.
        let when = SystemTime::UNIX_EPOCH + Duration::from_secs(1_700_000_000);
        let mut left = entry("a.txt", EntryKind::File, 10);
        left.mtime = Some(when);
        let mut right = entry("a.txt", EntryKind::File, 10);
        right.mtime = Some(when + Duration::from_secs(1));
        for (panel, e) in [(0usize, left), (1usize, right)] {
            app.handle_event(Event::Listed {
                panel,
                generation: app.panels[panel].listing.generation,
                result: Ok(vec![e]),
            });
        }

        // With no tolerance the right-hand copy is the newer one, and the only one marked.
        app.run(Command::ToolCompareDirs);
        assert_eq!(app.panels[0].selection.len(), 0);
        assert_eq!(app.panels[1].selection.len(), 1);

        // The dialog: two seconds of tolerance, which is what a FAT filesystem forces on
        // anybody who copies to a memory stick.
        app.run(Command::ToolCompare);
        let Mode::Form(form) = &app.mode else {
            panic!("no dialog: {:?}", app.mode)
        };
        assert_eq!(form.kind, crate::menu::FormKind::Compare);
        set_text(&mut app, "compare.seconds", "2");
        press(&mut app, "F10");
        assert!(app.mode.is_normal(), "{}", app.status);
        // Kept, so the next comparison is the one that was set up.
        assert_eq!(app.cfg.compare.seconds, 2);
        // And one second apart is now the same moment: nothing is marked at all.
        assert_eq!(app.panels[1].selection.len(), 0, "{}", app.status);
        assert_eq!(app.panels[0].selection.len(), 0);

        // Everything that differs, rather than only the newer copy: both sides of the pair.
        app.cfg.compare.seconds = 0;
        app.cfg.compare.newer_only = false;
        app.run(Command::ToolCompareDirs);
        assert_eq!(app.panels[0].selection.len(), 1);
        assert_eq!(app.panels[1].selection.len(), 1);

        // And a number the dialog cannot make sense of keeps the dialog open and says so.
        app.run(Command::ToolCompare);
        set_text(&mut app, "compare.seconds", "soon");
        press(&mut app, "F10");
        assert!(matches!(app.mode, Mode::Form(_)), "the dialog closed");
        assert!(!app.status.is_empty());
    }

    /// The prompt is the configuration's, and `%GITBRANCH%` in it is the branch — which is
    /// the one thing a prompt in a repository is asked for and could not say.
    #[test]
    fn the_prompt_says_which_branch_one_is_on() {
        let mut app = app();
        // The default is what it always was: the path and a sign.
        assert!(app.prompt().ends_with("> "), "{}", app.prompt());

        let dir = tempfile::tempdir().expect("temp dir");
        std::fs::create_dir(dir.path().join(".git")).expect("the git directory");
        std::fs::write(
            dir.path().join(".git").join("HEAD"),
            "ref: refs/heads/work\n",
        )
        .expect("HEAD");
        app.panels[0].cwd = VPath::local(dir.path());
        app.active = 0;
        app.cfg.cmdline.prompt = "$w $c%GITBRANCH%$f$g ".to_string();
        let prompt = app.prompt();
        assert!(prompt.ends_with("(work)> "), "{prompt:?}");
        assert!(prompt.starts_with(
            &dir.path()
                .file_name()
                .unwrap()
                .to_string_lossy()
                .to_string()
        ));

        // A detached head is the commit, shortened, as everything else that shows one does.
        std::fs::write(
            dir.path().join(".git").join("HEAD"),
            "9f1c0de4a5b6c7d8e9f0a1b2c3d4e5f607182930\n",
        )
        .expect("HEAD");
        // The directory has not changed, so the answer is the one already read: the lookup is
        // once per directory and not once per frame.
        assert!(app.prompt().ends_with("(work)> "));
        app.branch_at = None;
        assert!(app.prompt().ends_with("(9f1c0de)> "), "{}", app.prompt());

        // Somewhere that is not a repository says nothing, and `$h` takes the bracket back
        // out — which is the format's own business, not the prompt's.
        let empty = tempfile::tempdir().expect("temp dir");
        app.panels[0].cwd = VPath::local(empty.path());
        app.branch_at = None;
        assert!(app.prompt().ends_with("()> "), "{}", app.prompt());
    }

    /// The switches the dialog carries, which are FAR's: `Ctrl` and the digit a column is
    /// numbered by takes the column away and brings it back, `Ctrl+7` the rows that are not
    /// drives at all, and the choice is kept in the configuration rather than for this one
    /// opening of the dialog.
    #[test]
    fn the_drive_dialog_switches_its_own_columns() {
        let mut app = app();
        app.run(Command::PanelDrive(fcmd_cmd::Side::Left));
        let Mode::Pick(pick) = &app.mode else {
            panic!("no dialog: {:?}", app.mode)
        };
        let was = pick.rows.first().expect("a drive").label.clone();
        assert!(app.cfg.drives.show_type);

        // `Ctrl+1` takes the type column away: the row is shorter, and the dialog is still
        // open on the same row.
        press(&mut app, "Ctrl+1");
        assert!(!app.cfg.drives.show_type, "the setting did not change");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the dialog closed: {:?}", app.mode)
        };
        let now = pick.rows.first().expect("a drive").label.clone();
        assert!(
            now.chars().count() < was.chars().count(),
            "nothing went away: {was:?} -> {now:?}"
        );
        assert!(!app.status.is_empty(), "nothing was said about it");

        // And again brings it back, which is what a switch means.
        press(&mut app, "Ctrl+1");
        assert!(app.cfg.drives.show_type);
        let Mode::Pick(pick) = &app.mode else {
            panic!("the dialog closed")
        };
        assert_eq!(pick.rows.first().map(|r| r.label.clone()), Some(was));

        // `Ctrl+7` is the three panels that are not drives.
        press(&mut app, "Ctrl+7");
        assert!(!app.cfg.drives.show_panels);
        let Mode::Pick(pick) = &app.mode else {
            panic!("the dialog closed")
        };
        assert!(
            !pick.rows.iter().any(|r| r.value.starts_with(':')),
            "the panels are still there: {:?}",
            pick.rows
        );
        press(&mut app, "Ctrl+7");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the dialog closed")
        };
        assert!(pick.rows.iter().any(|r| r.value == ":processes"));
    }

    /// `F9` in the drive dialog opens the same switches as a dialog, and what it is told is
    /// kept and shown when the list comes back.
    #[test]
    fn f9_in_the_drive_dialog_opens_the_switches_as_a_dialog() {
        let mut app = app();
        app.run(Command::PanelDrive(fcmd_cmd::Side::Right));
        press(&mut app, "F9");
        let Mode::Form(form) = &app.mode else {
            panic!("no dialog: {:?}", app.mode)
        };
        assert_eq!(form.kind, crate::menu::FormKind::Drives);
        // Every row says which key it is, so the dialog is also the list of the keys.
        let rows = form.rows();
        assert!(
            rows.iter().filter(|r| r.text.contains("Ctrl+")).count() >= 9,
            "{:?}",
            rows.iter().map(|r| r.text.clone()).collect::<Vec<_>>()
        );

        // Turn the type column off here rather than with its key.
        set_toggle(&mut app, "drives.show_type", false);
        press(&mut app, "F10");
        assert!(!app.cfg.drives.show_type);
        // And the list is back, for the panel it was opened for.
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list did not come back: {:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::Drives);
        assert_eq!(pick.side, 1);
    }

    /// `Alt+Ins`: the screen grabber. The key asks the loop for the frame, because that is
    /// where the frame is; then the rectangle one marks is what goes on the clipboard.
    #[test]
    fn the_screen_grabber_copies_the_rectangle_it_is_shown() {
        let mut app = app();
        press(&mut app, "Alt+Ins");
        assert!(app.grab_wanted, "the key asks the loop for the screen");
        assert!(app.mode.is_normal(), "and nothing happens until it answers");

        // What the loop hands over: the frame that is on the terminal.
        let mut screen = fcmd_ui::Buffer::new(20, 3);
        let style = fcmd_ui::Style::default();
        screen.put_str(0, 0, "one two three", style, 20);
        screen.put_str(0, 1, "four five six", style, 20);
        app.open_grab(&screen);
        assert!(!app.grab_wanted);
        assert!(matches!(app.mode, Mode::Grab(_)), "{:?}", app.mode);
        let _ = app.take_requests();

        // With nothing marked, the key copies the row the cursor is on.
        press(&mut app, "Down");
        press(&mut app, "Enter");
        assert!(app.mode.is_normal(), "and it closes");
        let copied = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::Clipboard { text } => Some(text),
                _ => None,
            })
            .expect("nothing was copied");
        assert_eq!(copied, "four five six");

        // And with a rectangle marked, the rectangle. `Shift` drops the mark where the
        // cursor stands, so this is the three columns of `two` and of what is under it.
        app.open_grab(&screen);
        for _ in 0..4 {
            press(&mut app, "Right");
        }
        press(&mut app, "Shift+Right");
        press(&mut app, "Shift+Right");
        press(&mut app, "Shift+Down");
        let _ = app.take_requests();
        press(&mut app, "Ctrl+Ins");
        let copied = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::Clipboard { text } => Some(text),
                _ => None,
            })
            .expect("nothing was copied");
        assert_eq!(copied, "two\n fi");

        // `Esc` copies nothing.
        app.open_grab(&screen);
        let _ = app.take_requests();
        press(&mut app, "Esc");
        assert!(app.mode.is_normal());
        assert!(
            !app.take_requests()
                .iter()
                .any(|r| matches!(r, Request::Clipboard { .. })),
            "Esc put something on the clipboard"
        );
    }

    /// The two rows of *Interface settings* that used to be dim: the menu bar always on, and
    /// the settings written on the way out.
    #[test]
    fn the_interface_dialog_keeps_the_menu_bar_and_the_auto_save() {
        let mut app = app();
        app.run(Command::OptInterface);
        let Mode::Form(form) = &app.mode else {
            panic!("no dialog: {:?}", app.mode)
        };
        assert_eq!(form.kind, crate::menu::FormKind::Interface);
        assert!(!app.cfg.ui.menu_bar);
        assert!(!app.cfg.ui.save_setup_on_exit);

        set_toggle(&mut app, "ui.menu_bar", true);
        set_toggle(&mut app, "ui.save_setup_on_exit", true);
        press(&mut app, "F10");
        assert!(app.cfg.ui.menu_bar);
        assert!(app.cfg.ui.save_setup_on_exit);

        // And both are settings a configuration file can carry, so what the dialog did
        // survives being written and read back.
        let mut cfg = Config::default();
        cfg.set("ui.menu_bar", "yes").unwrap();
        cfg.set("ui.save_setup_on_exit", "yes").unwrap();
        assert!(cfg.ui.menu_bar);
        assert!(cfg.ui.save_setup_on_exit);
    }

    /// A panel showing the process list is not on a drive, and the dialog opens on the row
    /// that says so rather than on the drive the panel was on before.
    #[test]
    fn the_drive_dialog_opens_on_the_panel_one_is_actually_looking_at() {
        let mut app = app();
        app.run(Command::PanelDrive(fcmd_cmd::Side::Left));
        let Mode::Pick(pick) = &app.mode else {
            panic!("no dialog")
        };
        let processes = pick
            .rows
            .iter()
            .position(|r| r.value == ":processes")
            .expect("the process list is a row");
        assert_ne!(pick.cursor, processes, "nothing is showing it yet");
        press(&mut app, "Esc");

        // Open it, then ask for the dialog again.
        app.open_process_panel(0);
        if app.panels[0].temp_origin() != Some(":processes") {
            return; // this platform does not read the process list; see the test above
        }
        app.run(Command::PanelDrive(fcmd_cmd::Side::Left));
        let Mode::Pick(pick) = &app.mode else {
            panic!("no dialog")
        };
        assert_eq!(
            pick.chosen().map(|r| r.value.as_str()),
            Some(":processes"),
            "the cursor is on {:?}",
            pick.chosen()
        );
        // And no drive claims to be the current one while a list is in the panel.
        assert_eq!(
            pick.rows.iter().filter(|r| r.current).count(),
            1,
            "{:?}",
            pick.rows
        );
    }

    /// Each drive keeps the folder the panels were last in on it, as DOS does: from
    /// `C:\pippo` to `D:\pluto\paperino` and back to `C:` is `C:\pippo` again.
    #[test]
    fn a_drive_remembers_the_last_folder_a_panel_was_in_on_it() {
        let dir = tempfile::tempdir().unwrap();
        let c = dir.path().join("c");
        let d = dir.path().join("d");
        std::fs::create_dir_all(c.join("pippo")).unwrap();
        std::fs::create_dir_all(d.join("pluto/paperino")).unwrap();
        let (c_root, d_root) = (
            c.to_string_lossy().into_owned(),
            d.to_string_lossy().into_owned(),
        );
        let mut app = app_on_disk(dir.path());
        app.goto(VPath::local(c.join("pippo")));
        app.goto(VPath::local(d.join("pluto/paperino")));
        // The other panel is on neither drive.
        app.panels[1].cwd = VPath::parse("sftp://srv/");
        assert_eq!(
            app.drive_landing(0, &c_root),
            c.join("pippo").to_string_lossy(),
            "back to the folder this drive was left in"
        );
        // The drive the panel is on still means its root.
        assert_eq!(app.drive_landing(0, &d_root), d_root);
        // And a remembered folder that is gone is the root.
        std::fs::remove_dir(c.join("pippo")).unwrap();
        assert_eq!(app.drive_landing(0, &c_root), c_root);
        // Windows spellings fold: `C:\` holds `c:\pippo`, `/mnt/d` does not hold `/mnt/dd`.
        assert!(on_drive("c:\\pippo", "C:\\"));
        assert!(on_drive("C:/pippo/x", "c:"));
        assert!(!on_drive("/mnt/dd/src", "/mnt/d"));
        assert!(on_drive("/mnt/d", "/mnt/d/"));
    }

    /// Sending a panel to the drive the other one is already on lands it where that panel
    /// is, not at the top of the disk.
    #[test]
    fn a_drive_the_other_panel_is_on_opens_where_that_panel_is() {
        let mut app = app();
        app.panels[0].cwd = VPath::local("/mnt/c/work");
        app.panels[1].cwd = VPath::local("/mnt/d/src/deep");
        assert_eq!(app.drive_landing(0, "/mnt/d"), "/mnt/d/src/deep");
        // And the same in the other direction, because neither side is special.
        assert_eq!(app.drive_landing(1, "/mnt/c"), "/mnt/c/work");

        // The drive a panel is already on still means the top of it: that is how one gets
        // there in one keystroke, and the other panel's directory is in plain sight anyway.
        app.panels[0].cwd = VPath::local("/mnt/d/elsewhere");
        assert_eq!(app.drive_landing(0, "/mnt/d"), "/mnt/d");

        // A drive nobody is on is opened at its root, as it always was.
        app.panels[0].cwd = VPath::local("/mnt/c/work");
        assert_eq!(app.drive_landing(0, "/mnt/e"), "/mnt/e");

        // `/mnt/d` is not inside `/mnt/dd`: the comparison is by path component, so a drive
        // whose name merely starts with another's borrows nothing from it.
        app.panels[1].cwd = VPath::local("/mnt/dd/src");
        assert_eq!(app.drive_landing(0, "/mnt/d"), "/mnt/d");
    }

    /// And through the dialog, on the one row every machine has: the home directory. The
    /// panels have to be real directories here, because choosing a row really does send a
    /// panel there — so the other panel is put in a directory made under the home for the
    /// purpose, and the one being moved is put somewhere outside it.
    #[test]
    fn the_dialog_sends_a_panel_to_where_the_other_one_is() {
        let Some(home) = std::env::var_os("HOME").or_else(|| std::env::var_os("USERPROFILE"))
        else {
            return; // no home row to choose
        };
        let home = std::path::PathBuf::from(home);
        let Ok(theirs) = tempfile::tempdir_in(&home) else {
            return; // a home we may not write in
        };
        let mine = std::env::temp_dir();
        if mine.starts_with(&home) || !mine.is_dir() {
            return; // the two panels have to be on different sides of the home row
        }

        let mut app = app();
        app.panels[0].cwd = VPath::local(&mine);
        app.panels[1].cwd = VPath::local(theirs.path());
        app.run(Command::PanelDrive(fcmd_cmd::Side::Left));
        let Mode::Pick(pick) = &mut app.mode else {
            panic!("no dialog")
        };
        let home_text = home.to_string_lossy().into_owned();
        let Some(at) = pick.rows.iter().position(|r| r.value == home_text) else {
            return; // a machine whose mount table we could not read
        };
        pick.cursor = at;
        press(&mut app, "Enter");
        assert_eq!(
            app.panels[0].cwd,
            VPath::local(theirs.path()),
            "the panel went to {} rather than to the other panel's directory",
            app.panels[0].cwd
        );
    }

    /// The three cases where the rule would be a surprise, and so does not fire.
    #[test]
    fn a_drive_opens_at_its_root_where_lending_a_directory_would_surprise() {
        let mut app = app();
        app.panels[0].cwd = VPath::local("/mnt/c/work");

        // `/` is a prefix of every path there is. If it took the other panel's directory it
        // would never mean the root again, which is the one thing that row is for. The panel
        // being moved is put on a server, because a panel anywhere on this machine is under
        // `/` already and would be kept at the root by the next rule rather than by this one.
        app.panels[0].cwd = VPath::parse("sftp://srv/etc");
        app.panels[1].cwd = VPath::local("/usr/share");
        assert_eq!(app.drive_landing(0, "/"), "/");
        // The same panel, the same server, a drive that is not `/`: there the rule fires.
        assert_eq!(app.drive_landing(0, "/usr"), "/usr/share");
        app.panels[0].cwd = VPath::local("/mnt/c/work");

        // A panel on a server is not on a drive of this machine's.
        app.panels[1].cwd = VPath::parse("sftp://srv/var/log");
        assert_eq!(app.drive_landing(0, "/mnt/d"), "/mnt/d");

        // Neither is one showing a list that is not a filesystem. The row for that list is
        // where such a panel is, and the drive row still means the drive.
        app.panels[1].cwd = VPath::local("/mnt/d/src");
        app.open_process_panel(1);
        if app.panels[1].temp_origin() == Some(":processes") {
            assert_eq!(app.drive_landing(0, "/mnt/d"), "/mnt/d");
        }
    }

    /// A panel inside an archive lends the directory the archive lives in — never a path
    /// that would open the archive again, which is not what choosing a drive asks for.
    #[test]
    fn a_panel_inside_an_archive_lends_the_directory_that_holds_it() {
        let mut app = app();
        app.panels[0].cwd = VPath::local("/mnt/c/work");
        app.panels[1].cwd = VPath::local("/mnt/d/src/tree.zip").enter("/doc");
        assert_eq!(app.drive_landing(0, "/mnt/d"), "/mnt/d/src");

        // Two containers deep is the same answer: the directory holding the outermost one.
        app.panels[1].cwd = VPath::local("/mnt/d/src/outer.zip")
            .enter("/inner.tar")
            .enter("/etc");
        assert_eq!(app.drive_landing(0, "/mnt/d"), "/mnt/d/src");
    }

    /// `d:` and `D:` are the same disk, and the dialog's rows are built from `A:\` upwards
    /// while a path typed by hand keeps the case it was typed in.
    #[test]
    fn a_drive_letter_is_the_same_letter_in_either_case() {
        assert!(on_drive("d:/work/src", "D:/"));
        assert!(on_drive("D:\\work", "d:\\"));
        // Only a drive letter's case folds. A Unix path keeps its case whatever it starts
        // with.
        assert!(!on_drive("/mnt/data/x", "/mnt/Data"));
        assert!(on_drive("/mnt/Data/x", "/mnt/Data"));
    }

    /// `Shift+F3` on an archive: the menu names it, and what is on the menu is what we do.
    #[test]
    fn the_archive_menu_knows_which_archive_it_is_about() {
        let mut app = app();
        app.handle_event(Event::Listed {
            panel: 0,
            generation: app.panels[0].listing.generation,
            result: Ok(vec![
                entry("tree.zip", EntryKind::File, 100),
                entry("notes.txt", EntryKind::File, 10),
            ]),
        });
        app.panels[0].cursor = app.panels[0]
            .listing
            .order
            .iter()
            .position(|i| app.panels[0].listing.entries[*i as usize].name_str() == "tree.zip")
            .expect("the archive is in the listing");

        app.run(Command::ArcCommands);
        let Mode::Pick(pick) = &app.mode else {
            panic!("no menu: {:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::ArcCommands);
        let labels: Vec<String> = pick.rows.iter().map(|r| r.label.clone()).collect();
        assert!(
            labels.iter().any(|l| l.contains("tree.zip")),
            "the menu does not say which archive: {labels:?}"
        );
        let values: Vec<&str> = pick.rows.iter().map(|r| r.value.as_str()).collect();
        assert_eq!(values, ["test", "here", "to", "delete", "add"]);

        // On a file that is not an archive, only the one entry that does not need one.
        app.mode = Mode::Normal;
        app.panels[0].cursor = app.panels[0]
            .listing
            .order
            .iter()
            .position(|i| app.panels[0].listing.entries[*i as usize].name_str() == "notes.txt")
            .expect("the file is in the listing");
        app.run(Command::ArcCommands);
        let Mode::Pick(pick) = &app.mode else {
            panic!("no menu: {:?}", app.mode)
        };
        let values: Vec<&str> = pick.rows.iter().map(|r| r.value.as_str()).collect();
        assert_eq!(values, ["add"]);
    }

    #[test]
    fn the_system_dialog_writes_through_to_the_configuration() {
        let mut app = app();
        app.cfg.panel.natural_sort = false;
        open(&mut app, 3, "menu-system-settings");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog did not open")
        };
        assert_eq!(form.kind, FormKind::System);

        press(&mut app, "Space"); // the first row: natural number order
        press(&mut app, "Tab"); // to OK
        press(&mut app, "Enter");
        assert!(app.mode.is_normal());
        assert!(app.cfg.panel.natural_sort, "the dialog was not applied");

        // Esc throws the change away.
        open(&mut app, 3, "menu-system-settings");
        press(&mut app, "Space");
        press(&mut app, "Esc");
        assert!(app.cfg.panel.natural_sort);
    }

    #[test]
    fn the_case_of_the_sort_is_a_row_of_the_system_dialog_and_reaches_both_panels() {
        let mut app = app();
        assert_eq!(app.cfg.panel.sort_case, "auto");
        open(&mut app, 3, "menu-system-settings");
        press(&mut app, "Down"); // the second row, under the natural order
        press(&mut app, "Space"); // auto → yes
        press(&mut app, "F10");
        assert_eq!(app.cfg.panel.sort_case, "yes");
        assert!(
            app.panels.iter().all(|p| p.sort.case_sensitive),
            "the panels did not pick up the new setting"
        );

        open(&mut app, 3, "menu-system-settings");
        press(&mut app, "Down");
        press(&mut app, "Space"); // yes → no
        press(&mut app, "F10");
        assert_eq!(app.cfg.panel.sort_case, "no");
        assert!(app.panels.iter().all(|p| !p.sort.case_sensitive));
    }

