    // ── what to run for a kind of file (SPEC 06 §5) ─────────────────────────────────────────

    /// The command line a key asked to run, if it asked for one.
    /// The line a command was run with, caught or given the terminal (a `less` is the second).
    fn shell_line(app: &mut App) -> Option<String> {
        app.take_requests().into_iter().find_map(|r| match r {
            Request::Shell { line, .. } | Request::Interactive { line, .. } => Some(line),
            _ => None,
        })
    }

    // ── the user menu (`F2`, SPEC 06 §4) ────────────────────────────────────────────────

    /// An app whose `F2` reads the menu written here, in a directory of this test's own. The
    /// counter is what keeps two of these apart: the tests run in parallel, and a name made
    /// from the text itself would collide the moment two menus said the same thing.
    fn app_with_menu(text: &str) -> (App, std::path::PathBuf) {
        static NEXT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
        let n = NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!("fcmd-menu-{}-{n}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let file = dir.join(fcmd_config::usermenu::MENU_FILE_NAME);
        std::fs::write(&file, text).unwrap();
        let mut app = app();
        app.paths.menu_file = file;
        (app, dir)
    }

    fn pick_labels(app: &App) -> Vec<String> {
        let Mode::Pick(pick) = &app.mode else {
            panic!("no list is open; status: {}", app.status)
        };
        assert_eq!(pick.kind, PickKind::UserMenu);
        pick.rows.iter().map(|r| r.label.clone()).collect()
    }

    /// A separator is a rule in the list that the cursor does not stop on, and its name is
    /// drawn into the line; `Shift+F10` opens the menu again inside the submenu the row was
    /// in, with the cursor on it and nothing run until `Enter`.
    #[test]
    fn shift_f10_opens_the_menu_on_the_row_taken_last() {
        let (mut app, dir) = app_with_menu(
            r#"
[[menu]]
key = "w"
label = "Count the lines"
run = ["wc -l {file}"]

[[menu]]
separator = true
label = "Version control"

[[menu]]
key = "g"
label = "Git"
submenu = [
  { key = "s", label = "status", run = ["git status -sb"] },
  { key = "l", label = "log", run = ["git log --oneline -40"] },
]
"#,
        );
        press(&mut app, "F2");
        assert_eq!(
            pick_labels(&app),
            ["Count the lines", "Version control", "Git  \u{25b8}"]
        );
        let Mode::Pick(pick) = &app.mode else {
            unreachable!()
        };
        assert!(pick.rows[1].separator, "the heading is a rule, not a row");
        let mut buf = fcmd_ui::Buffer::new(80, 25);
        crate::render::draw(&mut app, &mut buf);
        let drawn = buf.to_text();
        assert!(drawn.contains(" Version control "), "{drawn}");

        press(&mut app, "g");
        press(&mut app, "l");
        assert_eq!(
            shell_line(&mut app).as_deref(),
            Some("git log --oneline -40")
        );

        app.mode = Mode::Normal;
        press(&mut app, "Shift+F10");
        assert_eq!(pick_labels(&app), ["status", "log"], "inside the submenu");
        let Mode::Pick(pick) = &app.mode else {
            unreachable!()
        };
        assert_eq!(pick.cursor, 1, "on the row taken last");
        assert!(shell_line(&mut app).is_none(), "selected, not run");

        // A row the file no longer has leaves the menu open and says why.
        std::fs::write(
            &app.paths.menu_file,
            "[[menu]]\nlabel = \"Other\"\nrun = [\"true\"]\n",
        )
        .unwrap();
        app.mode = Mode::Normal;
        press(&mut app, "Shift+F10");
        assert_eq!(pick_labels(&app), ["Other"]);
        assert!(app.status.contains("not in this menu"), "{}", app.status);
        let _ = std::fs::remove_dir_all(dir);
    }

    /// FAR's own menu file is read where ours is not: beside the configuration, and in the
    /// directory the panel is in, with that one's rows on top — and ours wins, whole, where
    /// both are there.
    #[test]
    fn f2_reads_fars_menu_as_it_stands_and_ours_wins_over_it() {
        let config = tempfile::tempdir().unwrap();
        let project = tempfile::tempdir().unwrap();
        std::fs::write(project.path().join("notes.txt"), "x").unwrap();
        let mut app = app_on_disk(project.path());
        app.paths.menu_file = config.path().join(fcmd_config::usermenu::MENU_FILE_NAME);
        app.panels[0].cursor = app.panels[0].listing.row_of_name("notes.txt").unwrap();

        // FAR 3 writes UTF-16 with a mark; the project's own is far2l's UTF-8.
        let global = "L:   List it\r\n    ls -l \"!.!\"\r\nD:   Free space\r\n    dir !:\r\n";
        let mut bytes = vec![0xff, 0xfe];
        bytes.extend(global.encode_utf16().flat_map(u16::to_le_bytes));
        std::fs::write(config.path().join("FarMenu.ini"), bytes).unwrap();
        std::fs::write(
            project.path().join("FarMenu.ini"),
            "B:   Build\n{\nR:   release\n    make !~\n}\n",
        )
        .unwrap();

        press(&mut app, "F2");
        let labels = pick_labels(&app);
        assert_eq!(labels[..3], ["Build  \u{25b8}", "List it", "Free space"]);
        assert_eq!(labels.len(), 5, "a rule and the remarks: {labels:?}");
        assert!(labels[4].contains('2'), "two remarks: {labels:?}");
        assert!(app.status.contains("FarMenu.ini"), "{}", app.status);

        // The remarks, each under the file it is about.
        press(&mut app, "End");
        press(&mut app, "Enter");
        let Mode::Message { lines, .. } = &app.mode else {
            panic!("the remarks are a message: {:?}", app.status)
        };
        let said = lines.join("\n");
        assert!(said.contains("8.3") && said.contains("drive"), "{said}");
        assert!(
            said.contains(&project.path().join("FarMenu.ini").display().to_string()),
            "{said}"
        );
        app.mode = Mode::Normal;

        // A row that was carried over runs as a command line of ours…
        press(&mut app, "F2");
        press(&mut app, "L");
        assert_eq!(shell_line(&mut app).as_deref(), Some("ls -l \"notes.txt\""));
        // …and the one that could not be says why and runs nothing.
        app.mode = Mode::Normal;
        press(&mut app, "F2");
        press(&mut app, "D");
        let Mode::Message { title, lines } = &app.mode else {
            panic!("a refused row says why")
        };
        assert_eq!(title, "Free space");
        assert!(lines[0].contains("drive"), "{lines:?}");
        assert!(shell_line(&mut app).is_none());
        app.mode = Mode::Normal;

        // Ours beside FAR's: FAR's is not read, and its rows are not on the menu.
        std::fs::write(
            &app.paths.menu_file,
            "[[menu]]\nkey = \"m\"\nlabel = \"Mine\"\nrun = [\"true\"]\n",
        )
        .unwrap();
        press(&mut app, "F2");
        let labels = pick_labels(&app);
        assert_eq!(labels[..2], ["Build  \u{25b8}", "Mine"]);
        assert!(!labels.iter().any(|l| l == "List it"), "{labels:?}");
        app.mode = Mode::Normal;

        // And ours broken is an error, not a reason to fall back on the other.
        std::fs::write(&app.paths.menu_file, "[[menu]]\nlabel = \"Nothing\"\n").unwrap();
        press(&mut app, "F2");
        assert!(matches!(app.mode, Mode::Normal));
        assert!(app.status.contains("Nothing"), "{}", app.status);
    }

