    #[test]
    fn the_calculator_answers_in_every_base_and_keeps_the_last_sum() {
        let mut app = app();
        app.run(Command::ToolCalculator);
        let Mode::Prompt(prompt) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(prompt.kind, PromptKind::Calculator);

        for c in "0x400+0x1c".chars() {
            press(&mut app, &c.to_string());
        }
        press(&mut app, "Enter");
        let Mode::Message { lines, .. } = &app.mode else {
            panic!("{:?}", app.mode)
        };
        let text = lines.join("\n");
        assert!(text.contains("1052"), "{text}");
        assert!(text.contains("0x41C"), "{text}");
        assert!(text.contains("0b10000011100"), "{text}");
        assert!(text.contains("0o2034"), "{text}");

        // It opens again on the sum just worked out.
        press(&mut app, "Esc");
        app.run(Command::ToolCalculator);
        let Mode::Prompt(prompt) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(prompt.text, "0x400+0x1c");

        // Something that is not arithmetic says so and keeps what was typed.
        press(&mut app, "End");
        for c in "/0".chars() {
            press(&mut app, &c.to_string());
        }
        press(&mut app, "Enter");
        assert!(app.status.contains("divide by zero"), "{}", app.status);
        let Mode::Prompt(prompt) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert!(prompt.text.contains("/0"), "the line should still be there");
    }

    /// A macro is recorded in a temporary configuration directory, so the test writes a real
    /// `fcmd-macros.toml` and reads it back — which is the half of the feature that a unit
    /// test of the type cannot reach.
    fn app_with_macros(dir: &std::path::Path) -> App {
        let mut app = App::new(Startup {
            cfg: Config::default(),
            paths: Paths::discover(Some(&dir.join("fcmd.toml")), None),
            i18n: I18n::new("en"),
            keymap: Keymap::builtin("far").unwrap(),
            themes: ThemeSet::builtin_only(),
            theme: Theme::default_theme(),
            left: VPath::local("/home/mb"),
            right: VPath::local("/tmp"),
            sites: Vec::new(),
            plugin_commands: Vec::new(),
            plugin_columns: Vec::new(),
            highlight: fcmd_ui::Highlight::far_default(),
            sort_groups: Default::default(),
            column_sets: Vec::new(),
        });
        app.requests.clear();
        let entries = vec![
            Entry::parent_entry(),
            entry("a.txt", EntryKind::File, 100),
            entry("b.rs", EntryKind::File, 200),
            entry("c.rs", EntryKind::File, 300),
        ];
        for side in [0, 1] {
            app.handle_event(Event::Listed {
                panel: side,
                generation: app.panels[side].generation,
                result: Ok(entries.clone()),
            });
        }
        app.requests.clear();
        app
    }

    #[test]
    fn a_macro_is_recorded_as_commands_assigned_to_a_key_and_played_back() {
        use fcmd_cmd::{Play, Step};
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_with_macros(dir.path());

        // Ctrl+. starts recording, and says so.
        press(&mut app, "Ctrl+.");
        assert!(app.recording.is_some());
        assert!(app.status.contains("Recording"), "{}", app.status);

        // Three keys: two that are commands, and one the panel consumed as a keystroke.
        press(&mut app, "Ctrl+H"); // panel.hidden.toggle
        press(&mut app, "Down"); // nav.down
        let steps = app.recording.clone().unwrap();
        assert_eq!(steps.len(), 2, "{steps:?}");
        assert!(
            matches!(steps[0], Step::Run(cmd) if cmd.id() == "panel.hidden.toggle"),
            "{steps:?}"
        );

        // Ctrl+. again asks for the key, and the recording keys are not in the recording.
        press(&mut app, "Ctrl+.");
        let Mode::MacroKey { steps } = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(steps.len(), 2);

        // The key is pressed rather than typed; then a description, which may be empty.
        press(&mut app, "Alt+9");
        let Mode::Prompt(prompt) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert!(matches!(prompt.kind, PromptKind::MacroDescription { .. }));
        for c in "hide-and-step".chars() {
            press(&mut app, &c.to_string());
        }
        press(&mut app, "Enter");
        // And the last question: how it plays. The first row is the ordinary answer.
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.rows.len(), 2);
        assert!(pick.rows[0].current);
        press(&mut app, "Enter");
        assert!(app.recording.is_none());
        assert_eq!(app.macros.all.len(), 1);
        let saved = &app.macros.all[0];
        assert_eq!(saved.key.to_string(), "Alt+9");
        assert_eq!(saved.description, "hide-and-step");
        assert_eq!(saved.play, Play::Once);
        assert!(!saved.trusted, "recording never trusts a macro");

        // It is on disk, and in the shape the file documents.
        let written = std::fs::read_to_string(dir.path().join("fcmd-macros.toml")).unwrap();
        assert!(written.contains("key = \"Alt+9\""), "{written}");
        assert!(written.contains("panel.hidden.toggle"), "{written}");

        // The scope is the one recording started in, which here is the panel.
        assert_eq!(saved.scope, fcmd_cmd::Scope::Panel);

        // Playing it: the key now does what was recorded, twice over.
        let hidden_before = app.panels[app.active].show_hidden;
        let cursor_before = app.panels[app.active].cursor;
        press(&mut app, "Alt+9");
        assert_ne!(app.panels[app.active].show_hidden, hidden_before);
        assert_eq!(app.panels[app.active].cursor, cursor_before + 1);

        // And a fresh application finds it again.
        let again = app_with_macros(dir.path());
        assert_eq!(again.macros.all.len(), 1);
        assert_eq!(again.macros.all[0].description, "hide-and-step");
    }

    #[test]
    fn a_macro_recorded_in_the_hex_editor_belongs_to_the_hex_editor() {
        let dir = tempfile::tempdir().unwrap();
        let text = dir.path().join("notes.txt");
        std::fs::write(&text, "one\ntwo\n").unwrap();
        let mut app = app_with_macros(dir.path());

        // Record inside the editor, and assign the macro while looking at something else:
        // the scope is where the recording started, not where it was stopped.
        app.open_hex(&text);
        press(&mut app, "Ctrl+.");
        press(&mut app, "Down");
        press(&mut app, "Ctrl+.");
        let Mode::MacroKey { .. } = &app.mode else {
            panic!("{:?}", app.mode)
        };
        press(&mut app, "Alt+7");
        press(&mut app, "Enter");
        // Esc out of the play question is "the ordinary way", not "throw it away".
        press(&mut app, "Esc");
        assert_eq!(app.macros.all.len(), 1, "{:?}", app.status);
        assert_eq!(app.macros.all[0].play, fcmd_cmd::Play::Once);
        // The hex editor's own scope, not the text editor's: a macro of block operations and
        // byte edits has no meaning in a buffer of text, and the two are told apart now.
        assert_eq!(app.macros.all[0].scope, fcmd_cmd::Scope::Hex);

        // So the key does nothing in the panels, and the macro is still there.
        app.mode = Mode::Normal;
        let before = app.panels[app.active].cursor;
        press(&mut app, "Alt+7");
        assert_eq!(app.panels[app.active].cursor, before);
    }

    #[test]
    fn a_macro_can_be_told_to_run_once_for_every_selected_file() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_with_macros(dir.path());

        // Record one step, assign it, and choose the second play mode.
        press(&mut app, "Ctrl+.");
        press(&mut app, "Ctrl+H");
        press(&mut app, "Ctrl+.");
        press(&mut app, "Alt+6");
        press(&mut app, "Enter"); // no description
        let Mode::Pick(pick) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        pick.cursor = 1;
        press(&mut app, "Enter");
        assert_eq!(app.macros.all.len(), 1);
        assert_eq!(app.macros.all[0].play, fcmd_cmd::Play::EachSelected);

        // It survives the file: the mode is written and read back.
        let written = std::fs::read_to_string(dir.path().join("fcmd-macros.toml")).unwrap();
        assert!(written.contains("each-selected"), "{written}");
        let again = app_with_macros(dir.path());
        assert_eq!(again.macros.all[0].play, fcmd_cmd::Play::EachSelected);

        // And it runs once per selected file. The recorded step re-reads the panel, so the
        // listing is fed again first: in a test nothing serves that read.
        let entries = vec![
            Entry::parent_entry(),
            entry("a.txt", EntryKind::File, 100),
            entry("b.rs", EntryKind::File, 200),
            entry("c.rs", EntryKind::File, 300),
        ];
        app.handle_event(Event::Listed {
            panel: app.active,
            generation: app.panels[app.active].generation,
            result: Ok(entries),
        });
        app.panel_mut().cursor_to(1);
        for _ in 0..3 {
            press(&mut app, "Insert");
        }
        assert_eq!(app.panels[app.active].selection.len(), 3);
        // Three selected files mean three runs, and three toggles of the hidden flag leave
        // it flipped — an odd number is the cheapest way to count them.
        let before = app.panels[app.active].show_hidden;
        press(&mut app, "Alt+6");
        assert_ne!(
            app.panels[app.active].show_hidden, before,
            "three files means three runs"
        );
    }

    #[test]
    fn a_macro_that_deletes_asks_before_it_plays_unless_the_file_trusts_it() {
        use fcmd_cmd::{Macro, Play, Scope, Step};
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_with_macros(dir.path());
        let key = "Alt+8".parse::<Key>().unwrap();
        let deleting = Macro {
            key,
            scope: Scope::Panel,
            steps: vec![Step::Run(Command::parse("file.delete").unwrap())],
            play: Play::Once,
            description: "the-one-that-bites".into(),
            trusted: false,
        };
        app.macros.set(deleting.clone());

        // The key does not delete: it asks, and names what it would run.
        press(&mut app, "Alt+8");
        let Mode::Confirm(confirm) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert!(matches!(confirm.action, ConfirmAction::PlayMacro(_)));
        assert!(
            confirm.lines.iter().any(|l| l.contains("file.delete")),
            "{:?}",
            confirm.lines
        );
        press(&mut app, "Esc");
        assert!(app.mode.is_normal());

        // A macro the file trusts plays without the question.
        app.macros.set(Macro {
            trusted: true,
            ..deleting
        });
        press(&mut app, "Alt+8");
        assert!(
            !matches!(app.mode, Mode::Confirm(_)),
            "a trusted macro must not ask: {:?}",
            app.mode
        );
    }

    /// `F11` lists every command, the ones that can run here first; the rest are greyed
    /// out with the reason, and `Enter` on one of them says the reason again and runs nothing.
    #[test]
    fn f11_lists_every_command_and_says_why_one_cannot_run_here() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), "x").unwrap();
        std::fs::write(dir.path().join("b.zip"), "x").unwrap();
        let mut app = app_on_disk(dir.path());
        let program = dir.path().join("go.sh");
        let cmd = |id: &str, when: fcmd_plug::When, scope: fcmd_cmd::Scope| PluginCommand {
            plugin: "demo".into(),
            id: format!("user.demo.{id}"),
            label: format!("Demo {id}"),
            scope,
            program: program.clone(),
            needs: Vec::new(),
            timeout: None,
            confirm: None,
            when,
        };
        use fcmd_cmd::Scope;
        app.plugin_commands = vec![
            cmd(
                "zip",
                fcmd_plug::When {
                    masks: Some("*.zip".into()),
                    ..Default::default()
                },
                Scope::Panel,
            ),
            cmd("view", Default::default(), Scope::Viewer),
            cmd("any", Default::default(), Scope::Panel),
            cmd(
                "env",
                fcmd_plug::When {
                    here: vec![".env".into()],
                    ..Default::default()
                },
                Scope::Panel,
            ),
            cmd(
                "repo",
                fcmd_plug::When {
                    local: true,
                    inside: vec!["fcmd-test-marker".into()],
                    ..Default::default()
                },
                Scope::Panel,
            ),
        ];
        app.panels[0].cursor = app.panels[0].listing.row_of_name("a.txt").unwrap();
        app.run(Command::PluginCommands);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        // The one that can run first, then a rule, then the others in the order they came.
        assert!(
            pick.rows[0].label.starts_with("Demo any"),
            "{:?}",
            pick.rows
        );
        assert!(pick.rows[1].separator);
        let label = |id: &str| {
            pick.rows
                .iter()
                .find(|r| r.label.starts_with(&format!("Demo {id}")))
                .unwrap()
                .label
                .clone()
        };
        assert!(label("zip").contains("*.zip"), "{}", label("zip"));
        assert!(label("view").contains("viewer"), "{}", label("view"));
        assert!(label("env").contains(".env"), "{}", label("env"));
        assert!(
            label("repo").contains("fcmd-test-marker"),
            "{}",
            label("repo")
        );
        let mut dim = app.plugin_dim.clone();
        dim.sort();
        assert_eq!(dim, ["0", "1", "3", "4"]);

        // `Enter` on a grey one: the reason, and nothing run.
        let Mode::Pick(pick) = &mut app.mode else {
            unreachable!()
        };
        pick.cursor = pick.rows.iter().position(|r| r.value == "0").unwrap();
        press(&mut app, "Enter");
        assert!(
            app.status_error && app.status.contains("*.zip"),
            "{}",
            app.status
        );
        assert!(
            !app.take_requests()
                .iter()
                .any(|r| matches!(r, Request::Plugin { .. })),
            "a greyed-out command ran"
        );

        // On the archive, the archive's command is one that can run; and with the marker
        // in a folder above, so is the one about the repository.
        std::fs::write(dir.path().join("fcmd-test-marker"), "").unwrap();
        app.mode = Mode::Normal;
        app.panels[0].cursor = app.panels[0].listing.row_of_name("b.zip").unwrap();
        app.run(Command::PluginCommands);
        let mut dim = app.plugin_dim.clone();
        dim.sort();
        assert_eq!(dim, ["1", "3"]);
    }

    /// With nothing installed `F11` is still a list, of the two things worth doing next:
    /// going to the folder plugins live in, and reading how they work.
    #[test]
    fn f11_with_no_plugins_says_where_they_go() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_on_disk(dir.path());
        app.plugin_commands.clear();
        app.run(Command::PluginCommands);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.rows.len(), 2);
        let plugins = app.paths.plugins_dir.clone();
        assert!(
            pick.rows[0].label.contains(&plugins.display().to_string()),
            "{}",
            pick.rows[0].label
        );
        // The help, at its heading on plugins.
        let Mode::Pick(pick) = &mut app.mode else {
            unreachable!()
        };
        pick.cursor = 1;
        press(&mut app, "Enter");
        let Mode::Help { scroll, .. } = app.mode else {
            panic!("{:?}", app.mode)
        };
        assert!(scroll > 0, "the help opened at its top, not at the plugins");
        // The folder: made, and the panel taken there.
        app.mode = Mode::Normal;
        app.run(Command::PluginCommands);
        press(&mut app, "Enter");
        assert!(plugins.is_dir());
        assert!(
            app.take_requests()
                .iter()
                .any(|r| matches!(r, Request::Read { .. })),
            "the panel was not sent to the folder"
        );
    }

    #[test]
    fn a_plugin_command_that_says_to_ask_is_asked_about_first() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_with_macros(dir.path());
        let program = dir.path().join("rename.sh");
        std::fs::write(&program, "#!/bin/sh\n").unwrap();

        // One that asks and one that does not: the plugin declares it, because the host
        // cannot know what somebody else's program will do.
        app.plugin_commands = vec![
            PluginCommand {
                plugin: "noisy".into(),
                id: "user.noisy.rename".into(),
                label: "Rename everything".into(),
                scope: fcmd_cmd::Scope::Panel,
                program: program.clone(),
                needs: vec!["panel".into(), "selection".into()],
                timeout: None,
                confirm: Some("This renames files.".into()),
                when: Default::default(),
            },
            PluginCommand {
                plugin: "quiet".into(),
                id: "user.quiet.look".into(),
                label: "Just look".into(),
                scope: fcmd_cmd::Scope::Panel,
                program,
                needs: vec!["panel".into()],
                timeout: None,
                confirm: None,
                when: Default::default(),
            },
        ];

        // Two files selected, so the question can count them.
        app.panel_mut().cursor_to(1);
        press(&mut app, "Insert");
        press(&mut app, "Insert");
        assert_eq!(app.panels[app.active].selection.len(), 2);

        app.run(Command::PluginCommands);
        let Mode::Pick(pick) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.rows.len(), 2);
        pick.cursor = 0;
        press(&mut app, "Enter");

        // The question, with the plugin's own sentence and our count of what it will act on.
        let Mode::Confirm(confirm) = &app.mode else {
            panic!("a plugin that renames must ask: {:?}", app.mode)
        };
        assert_eq!(confirm.action, ConfirmAction::RunPlugin(0));
        assert_eq!(confirm.title, "Rename everything");
        assert!(
            confirm
                .lines
                .iter()
                .any(|l| l.contains("This renames files.")),
            "{:?}",
            confirm.lines
        );
        assert!(
            confirm.lines.iter().any(|l| l.contains('2')),
            "the question says how many files: {:?}",
            confirm.lines
        );
        // Esc runs nothing.
        press(&mut app, "Esc");
        assert!(app.take_requests().is_empty(), "Esc must not run it");

        // The one that does not ask goes straight to the worker.
        app.run(Command::PluginCommands);
        let Mode::Pick(pick) = &mut app.mode else {
            unreachable!()
        };
        pick.cursor = 1;
        press(&mut app, "Enter");
        assert!(app.mode.is_normal(), "{:?}", app.mode);
        let asked: Vec<_> = app
            .take_requests()
            .into_iter()
            .filter(|r| matches!(r, Request::Plugin { .. }))
            .collect();
        assert_eq!(asked.len(), 1, "it should have been asked to run");
    }

    #[test]
    fn screens_keep_a_viewer_and_an_editor_open_behind_the_panels() {
        let dir = tempfile::tempdir().unwrap();
        let text = dir.path().join("notes.txt");
        let bin = dir.path().join("prog.bin");
        std::fs::write(&text, "one\ntwo\n").unwrap();
        std::fs::write(&bin, [0x55, 0x48, 0x89, 0xE5]).unwrap();
        let mut app = app();

        // Nothing open: the list still answers, with the panels alone.
        app.run(Command::AppScreens);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.rows.len(), 1);
        assert_eq!(pick.rows[0].value, "panels");
        press(&mut app, "Esc");

        // Open the viewer, then step back to the panels: it stays open behind them. The
        // panels are screen zero of the ring, so Ctrl+Tab from the only screen lands there.
        app.open_viewer_on(&text, VPath::local(&text));
        assert!(app.mode.viewer().is_some());
        app.run(Command::AppScreenNext);
        assert!(app.mode.is_normal(), "{:?}", app.mode);
        assert_eq!(app.background.len(), 1);

        // And the hex editor on top of that: Ctrl+Tab steps out to the panels again, and
        // both screens are now behind them.
        app.open_hex(&bin);
        app.run(Command::AppScreenNext);
        assert!(app.mode.is_normal(), "{:?}", app.mode);
        assert_eq!(app.background.len(), 2, "both are behind the panels now");

        // The list shows both, the panels first and the newest screen last.
        app.run(Command::AppScreens);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        let labels: Vec<&str> = pick.rows.iter().map(|r| r.label.as_str()).collect();
        assert_eq!(labels.len(), 3, "{labels:?}");
        assert!(labels[1].contains("prog.bin"), "{labels:?}");
        assert!(labels[2].contains("notes.txt"), "{labels:?}");

        // Choose the viewer: it comes forward and the panels are no longer in front.
        let at = pick
            .rows
            .iter()
            .position(|r| r.label.contains("notes"))
            .unwrap();
        let Mode::Pick(pick) = &mut app.mode else {
            unreachable!()
        };
        pick.cursor = at;
        press(&mut app, "Enter");
        assert!(app.mode.viewer().is_some(), "{:?}", app.mode);
        assert_eq!(app.background.len(), 1, "the hex editor is still behind");

        // Ctrl+Tab from a screen steps out to the panels, and again steps in to the next
        // one behind them: every screen is reachable, and the panels are one key away.
        app.run(Command::AppScreenNext);
        assert!(app.mode.is_normal(), "{:?}", app.mode);
        app.run(Command::AppScreenNext);
        assert!(app.mode.hex().is_some(), "{:?}", app.mode);
        // Backwards from the panels is the screen one stepped away from last.
        app.run(Command::AppScreenNext);
        assert!(app.mode.is_normal());
        app.run(Command::AppScreenPrev);
        assert!(app.mode.hex().is_some(), "{:?}", app.mode);
    }

    #[test]
    fn the_screens_list_does_not_lose_the_screen_it_is_drawn_over() {
        let dir = tempfile::tempdir().unwrap();
        let text = dir.path().join("notes.txt");
        std::fs::write(&text, "one\n").unwrap();
        let mut app = app();

        // F12 with a viewer in front: the viewer is the current row, and Esc gives it back.
        app.open_viewer_on(&text, VPath::local(&text));
        app.run(Command::AppScreens);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.rows.len(), 2, "the panels and the viewer");
        assert_eq!(pick.rows[1].value, "front");
        assert!(pick.rows[1].current, "the one in front is the current row");
        press(&mut app, "Esc");
        assert!(app.mode.viewer().is_some(), "{:?}", app.mode);

        // And choosing the panels sends it to the background rather than closing it.
        app.run(Command::AppScreens);
        let Mode::Pick(pick) = &mut app.mode else {
            unreachable!()
        };
        pick.cursor = 0;
        press(&mut app, "Enter");
        assert!(app.mode.is_normal(), "{:?}", app.mode);
        assert_eq!(app.background.len(), 1);

        // A question asked over a viewer belongs to that viewer: F12 from there lists the
        // viewer, not the panels, and nothing is left behind the list.
        app.run(Command::AppScreenPrev);
        assert!(app.mode.viewer().is_some());
        app.run(Command::ViewerSearch);
        assert!(matches!(app.mode, Mode::Form(_)), "{:?}", app.mode);
        app.run(Command::AppScreens);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert!(
            pick.rows.iter().any(|r| r.value == "front"),
            "the viewer under the prompt is the screen in front: {:?}",
            pick.rows
        );
        press(&mut app, "Esc");
        assert!(app.mode.viewer().is_some(), "{:?}", app.mode);
    }

    /// The two settings in the dialog that did nothing. Both were toggles one could turn and
    /// watch change nothing at all, which is worse than not offering them.
    #[test]
    fn the_confirmation_settings_are_the_settings_they_claim_to_be() {
        // Three applications rather than one reused: each half of this is about a setting's
        // default, and a setting changed in one must not be read in the next.
        let (mut quiet, mut asking, mut jobs) = (app(), app(), app());

        // `confirm_exit` off (the default) leaves on the first F10.
        assert!(!quiet.cfg.general.confirm_exit);
        quiet.run(Command::AppQuit);
        assert!(quiet.quit);

        // On, it asks — and Esc stays.
        asking.cfg.general.confirm_exit = true;
        asking.run(Command::AppQuit);
        assert!(!asking.quit, "it must ask first");
        assert!(matches!(asking.mode, Mode::Confirm(_)), "{:?}", asking.mode);
        press(&mut asking, "Esc");
        assert!(!asking.quit);
        asking.run(Command::AppQuit);
        press(&mut asking, "Enter");
        assert!(asking.quit);

        // `confirm_overwrite` on (the default) leaves the engine asking about a file that is
        // already there; off, the job is started with the policy that writes over it.
        fn conflict_of(app: &mut App) -> fcmd_jobs::ConflictPolicy {
            app.requests.clear();
            // Each one is a fresh job, not one waiting behind the last for the same disk.
            app.queue.jobs.clear();
            app.start_job(JobSpec::new(
                JobKind::Copy,
                vec![VPath::local("/a")],
                Some(VPath::local("/b")),
            ));
            app.take_requests()
                .into_iter()
                .find_map(|r| match r {
                    Request::Job { spec, .. } => Some(spec.options.on_conflict),
                    _ => None,
                })
                .expect("a job was asked for")
        }
        assert!(jobs.cfg.general.confirm_overwrite);
        assert_eq!(conflict_of(&mut jobs), fcmd_jobs::ConflictPolicy::Ask);
        jobs.cfg.general.confirm_overwrite = false;
        assert_eq!(conflict_of(&mut jobs), fcmd_jobs::ConflictPolicy::Overwrite);

        // And a dialog that chose `skip` on purpose is not overridden by a setting about
        // asking: the two mean different things.
        jobs.requests.clear();
        jobs.queue.jobs.clear();
        let mut spec = JobSpec::new(
            JobKind::Copy,
            vec![VPath::local("/a")],
            Some(VPath::local("/b")),
        );
        spec.options.on_conflict = fcmd_jobs::ConflictPolicy::Skip;
        jobs.start_job(spec);
        let chosen = jobs
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::Job { spec, .. } => Some(spec.options.on_conflict),
                _ => None,
            })
            .unwrap();
        assert_eq!(chosen, fcmd_jobs::ConflictPolicy::Skip);
    }

    /// Two copies onto the same disk: the second waits, and starts on its own once the first
    /// is done — in the background, because nobody asked to watch it (SPEC 03 §5).
    #[test]
    fn a_second_job_for_the_same_disk_waits_for_the_first() {
        let mut app = app();
        let copy = |to: &str| {
            JobSpec::new(
                JobKind::Copy,
                vec![VPath::local("/home/mb/a.txt")],
                Some(VPath::local(to)),
            )
        };
        app.start_job(copy("/home/mb/one"));
        let (first, _) = job_request(&mut app);
        assert!(matches!(app.mode, Mode::Job(_)));
        app.mode = Mode::Normal;
        app.start_job(copy("/home/mb/two"));
        assert!(
            !app.take_requests()
                .iter()
                .any(|r| matches!(r, Request::Job { .. })),
            "the second one must wait"
        );
        assert_eq!(app.queue.active(), 2);

        app.handle_event(Event::JobDone {
            id: first,
            kind: JobKind::Copy,
            outcome: Outcome::default(),
        });
        let (second, spec) = job_request(&mut app);
        assert_ne!(second, first);
        assert_eq!(spec.target, Some(VPath::local("/home/mb/two")));
        assert!(
            matches!(app.mode, Mode::Normal),
            "no box for a job from the queue"
        );
        assert_eq!(app.queue.active(), 1);
    }

    // ── the job journal (SPEC 03 §5a) ───────────────────────────────────────────────────

    /// A journal as startup would have read it: a copy of two files, one of them done.
    fn left_copy() -> (std::path::PathBuf, fcmd_jobs::Journal) {
        let spec = JobSpec::new(
            JobKind::Copy,
            vec![
                VPath::local("/home/mb/a.txt"),
                VPath::local("/home/mb/b.txt"),
            ],
            Some(VPath::local("/home/mb/backup")),
        );
        let mut journal = fcmd_jobs::Journal::of(&spec, 0).expect("a copy keeps a journal");
        journal
            .done
            .insert(VPath::local("/home/mb/backup").join("a.txt"));
        (std::path::PathBuf::from("9-1.journal"), journal)
    }

    #[test]
    fn a_copy_is_given_a_place_for_its_journal_and_a_delete_is_not() {
        let mut app = app();
        app.cfg.general.job_queue = fcmd_config::JobQueue::Off;
        app.start_job(JobSpec::new(
            JobKind::Copy,
            vec![VPath::local("/home/mb/a.txt")],
            Some(VPath::local("/home/mb/backup")),
        ));
        app.start_job(JobSpec::new(
            JobKind::Delete,
            vec![VPath::local("/home/mb/a.txt")],
            None,
        ));
        let journals: Vec<Option<Box<fcmd_jobs::Ticket>>> = app
            .take_requests()
            .into_iter()
            .filter_map(|r| match r {
                Request::Job { journal, .. } => Some(journal),
                _ => None,
            })
            .collect();
        assert_eq!(journals.len(), 2);
        let ticket = journals[0].as_ref().expect("the copy keeps a journal");
        assert!(
            ticket.path.starts_with(app.paths.jobs_dir()),
            "{:?}",
            ticket.path
        );
        assert!(ticket.resumes.is_none(), "a new job takes nothing up");
        assert!(journals[1].is_none(), "a delete keeps none");
    }

    #[test]
    fn unfinished_jobs_are_said_once_and_enter_goes_on_with_one() {
        let mut app = app();
        let (path, journal) = left_copy();
        app.offer_left_jobs(fcmd_jobs::journal::Left {
            journals: vec![(path.clone(), journal.clone())],
            problems: Vec::new(),
        });
        assert!(
            app.status.contains("1") && app.status.contains("Alt+Shift+F6"),
            "{}",
            app.status
        );

        press(&mut app, "Alt+Shift+F6");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list did not open: {:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::LeftJobs);
        assert_eq!(pick.rows.len(), 1);
        assert!(pick.rows[0].label.contains("a.txt (+1)"), "{:?}", pick.rows);

        press(&mut app, "Enter");
        assert!(
            app.left_jobs.is_empty(),
            "a job taken up is offered no more"
        );
        let (spec, ticket) = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::Job { spec, journal, .. } => Some((spec, journal)),
                _ => None,
            })
            .expect("the job was queued");
        assert_eq!(spec.sources, journal.sources);
        assert!(spec.options.resume, "it goes on from the part");
        let (from, old) = ticket
            .expect("a copy keeps a journal")
            .resumes
            .expect("and this one takes the dead run's up");
        assert_eq!(from, path);
        assert_eq!(old.done, journal.done);
        // What a dead session half wrote is not this session's to take back.
        assert!(app.queue.jobs.iter().all(|j| j.undo.is_none()));
    }

    #[test]
    fn del_discards_an_unfinished_job_and_an_unreadable_journal_alike() {
        let mut app = app();
        let (path, journal) = left_copy();
        app.offer_left_jobs(fcmd_jobs::journal::Left {
            journals: vec![(path.clone(), journal)],
            problems: vec![(
                std::path::PathBuf::from("9-2.journal"),
                fcmd_jobs::JournalError::Foreign,
            )],
        });
        app.run(Command::JobJournal);

        // Enter on the one that cannot be read does nothing but say so, and keeps the list.
        press(&mut app, "Down");
        press(&mut app, "Enter");
        assert!(app.status_error, "{}", app.status);
        assert!(matches!(app.mode, Mode::Pick(_)), "{:?}", app.mode);
        assert!(app.take_requests().is_empty(), "nothing was queued");

        press(&mut app, "Home");
        press(&mut app, "Delete");
        let Mode::Pick(pick) = &app.mode else {
            panic!("one row is left, so the list stays: {:?}", app.mode)
        };
        assert_eq!(pick.rows.len(), 1);
        press(&mut app, "Delete");
        assert!(app.mode.is_normal(), "an empty list closes: {:?}", app.mode);

        let discarded: Vec<(std::path::PathBuf, bool)> = app
            .take_requests()
            .into_iter()
            .filter_map(|r| match r {
                Request::DiscardJournal { path, journal } => Some((path, journal.is_some())),
                _ => None,
            })
            .collect();
        assert_eq!(
            discarded,
            vec![
                (path, true),
                (std::path::PathBuf::from("9-2.journal"), false)
            ]
        );

        // And with nothing left, the command says so rather than opening an empty box.
        app.run(Command::JobJournal);
        assert!(app.mode.is_normal());
        assert_eq!(app.status, app.i18n.t("journal-none"));
    }

    // ── saved synchronisations and their report (SPEC 03 §10a) ──────────────────────────

    /// An application whose configuration file is in a folder of its own, because these
    /// tests save the setup and the file has to land somewhere nobody else writes.
    fn app_saving_in(dir: &std::path::Path) -> App {
        let mut app = app();
        app.paths = Paths::discover(Some(&dir.join("fcmd.toml")), None);
        app
    }

    fn saved_pair(dir: &std::path::Path, name: &str) -> fcmd_config::SyncCfg {
        fcmd_config::SyncCfg {
            name: name.to_string(),
            left: dir.join(name).join("here").display().to_string(),
            right: dir.join(name).join("there").display().to_string(),
            delete_extra: true,
            ..fcmd_config::SyncCfg::default()
        }
    }

    #[test]
    fn a_name_in_the_sync_dialog_saves_the_pair_with_its_rules() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_saving_in(dir.path());
        let (left, right) = (app.panels[0].cwd.clone(), app.panels[1].cwd.clone());
        press(&mut app, "Ctrl+Shift+Y");
        set_toggle(&mut app, "sync.both_ways", true);
        {
            let Mode::Form(form) = &mut app.mode else {
                panic!("the dialog is open")
            };
            assert_eq!(form.buttons.len(), 3, "OK, the saved ones, Cancel");
            form.set_text("sync.name", "Evening backup".to_string());
            form.set_text("sync.filter", "*.rs".to_string());
            form.set_text("sync.report", "sync-report.txt".to_string());
        }
        press(&mut app, "F10");

        assert_eq!(app.cfg.syncs.len(), 1);
        let saved = &app.cfg.syncs[0];
        assert_eq!(saved.name, "Evening backup");
        assert_eq!(saved.left, left.to_string());
        assert_eq!(saved.right, right.to_string());
        assert!(saved.recursive && saved.both_ways && !saved.delete_extra);
        assert_eq!(saved.filter, "*.rs");
        assert_eq!(saved.report, "sync-report.txt", "kept as it was typed");
        let written = std::fs::read_to_string(dir.path().join("fcmd.toml")).unwrap();
        assert!(written.contains("[[sync]]"), "{written}");
        assert!(written.contains("Evening backup"), "{written}");

        // And it goes on to the table, as an unsaved one does, knowing where to report.
        let Mode::Sync(view) = &app.mode else {
            panic!("the walk did not start: {:?}", app.mode)
        };
        assert_eq!(view.name, "Evening backup");
        assert_eq!(
            view.report,
            Some(app.panel().cwd.join("sync-report.txt")),
            "a relative name is in the active panel's directory"
        );
        assert!(app
            .take_requests()
            .iter()
            .any(|r| matches!(r, Request::SyncPlan { .. })));

        // The same name again replaces the block rather than adding a second.
        press(&mut app, "Esc");
        press(&mut app, "Ctrl+Shift+Y");
        {
            let Mode::Form(form) = &mut app.mode else {
                panic!("the dialog is open")
            };
            form.set_text("sync.name", "Evening backup".to_string());
        }
        press(&mut app, "F10");
        assert_eq!(app.cfg.syncs.len(), 1);
        assert!(app.cfg.syncs[0].report.is_empty(), "the new answer won");
    }

    #[test]
    fn the_list_of_saved_synchronisations_runs_changes_and_forgets() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_saving_in(dir.path());
        app.cfg.syncs = vec![saved_pair(dir.path(), "one"), saved_pair(dir.path(), "two")];
        app.cfg.syncs[1].report = dir.path().join("two.txt").display().to_string();

        press(&mut app, "Ctrl+Alt+Y");
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list did not open: {:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::SavedSyncs);
        assert_eq!(pick.rows.len(), 2);
        assert!(pick.rows[0].label.starts_with("one: "), "{:?}", pick.rows);

        // Enter runs the second: its own two directories, not the panels', and its rules.
        press(&mut app, "Down");
        press(&mut app, "Enter");
        let Mode::Sync(view) = &app.mode else {
            panic!("the walk did not start: {:?}", app.mode)
        };
        assert_eq!(view.left, VPath::local(dir.path().join("two").join("here")));
        assert_eq!(view.report, Some(VPath::local(dir.path().join("two.txt"))));
        let options = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::SyncPlan { options, .. } => Some(options),
                _ => None,
            })
            .expect("the walk was asked for");
        assert!(options.delete_extra && options.recursive && !options.both_ways);
        press(&mut app, "Esc");

        // F4 opens its dialog, filled in.
        app.run(Command::ToolSyncSaved);
        press(&mut app, "F4");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog did not open: {:?}", app.mode)
        };
        assert_eq!(form.kind, FormKind::Sync);
        assert_eq!(form.text_value("sync.name"), "one");
        assert_eq!(form.text_value("sync.delete_extra"), "true");
        press(&mut app, "Esc");

        // Del forgets one, in the file as well; the last one closes the list.
        app.run(Command::ToolSyncSaved);
        press(&mut app, "Delete");
        assert_eq!(app.cfg.syncs.len(), 1);
        assert_eq!(app.cfg.syncs[0].name, "two");
        assert!(app.status.contains("one"), "{}", app.status);
        let written = std::fs::read_to_string(dir.path().join("fcmd.toml")).unwrap();
        assert!(!written.contains("name = \"one\""), "{written}");
        press(&mut app, "Delete");
        assert!(app.mode.is_normal(), "{:?}", app.mode);
        assert!(app.cfg.syncs.is_empty());
    }

