    /// A panel over a real directory, so `F3` can open a real file.
    fn app_on_disk(dir: &std::path::Path) -> App {
        // As in `app`: a kept shell is something a test asks for by name, never something it
        // inherits from the machine it runs on.
        let cfg = Config {
            term: fcmd_config::TermCfg {
                subshell: false,
                ..Default::default()
            },
            ..Config::default()
        };
        let mut app = App::new(Startup {
            cfg,
            paths: Paths::discover(Some(&dir.join("fcmd.toml")), None),
            i18n: I18n::new("en"),
            keymap: Keymap::builtin("far").unwrap(),
            themes: ThemeSet::builtin_only(),
            theme: Theme::default_theme(),
            left: VPath::local(dir),
            right: VPath::local(dir),
            sites: Vec::new(),
            plugin_commands: Vec::new(),
            plugin_columns: Vec::new(),
            highlight: fcmd_ui::Highlight::far_default(),
            sort_groups: Default::default(),
            column_sets: Vec::new(),
        });
        app.requests.clear();
        let entries = fcmd_vfs::local::list_blocking(&VPath::local(dir), &CancelToken::new())
            .expect("the test directory");
        for panel in 0..2 {
            app.handle_event(Event::Listed {
                panel,
                generation: 1,
                result: Ok(entries.clone()),
            });
        }
        app.viewer_size = (40, 4);
        app
    }

    /// A panel's names read in another code page: what the screen says, and the file it still
    /// opens (SPEC 02 §6b).
    ///
    /// The file is made with a name that is *not* UTF-8 — the bytes a Russian Windows writes
    /// for `привет.txt` in CP1251 — which is exactly the case this is for: the system has no
    /// opinion about those bytes, and the panel used to draw them as replacement characters.
    #[cfg(unix)]
    #[test]
    fn a_panels_names_can_be_read_in_another_code_page_and_still_open_the_file() {
        use std::os::unix::ffi::OsStrExt;

        let dir = tempfile::tempdir().unwrap();
        // "привет.txt" in CP1251: one byte per Cyrillic letter.
        let raw: &[u8] = &[0xEF, 0xF0, 0xE8, 0xE2, 0xE5, 0xF2, b'.', b't', b'x', b't'];
        let file = dir.path().join(std::ffi::OsStr::from_bytes(raw));
        // Not every filesystem will take such a name. macOS refuses one that is not valid
        // UTF-8 outright — `Illegal byte sequence` — so there is nothing there to read a
        // second way and nothing for this test to be about; it says so by not running rather
        // than by failing.
        if std::fs::write(&file, b"hello\n").is_err() {
            return;
        }

        let mut app = app_on_disk(dir.path());
        let names = |app: &App| -> Vec<String> {
            let l = &app.panels[app.active].listing;
            (0..l.len())
                .filter_map(|i| l.row(i))
                .map(|e| e.name_str().into_owned())
                .collect()
        };
        // As the system gives them: not UTF-8, so the name is drawn with replacements and
        // nobody can read it.
        let shown = names(&app);
        assert!(
            shown.iter().any(|n| n.contains('\u{fffd}')),
            "the bytes are not UTF-8 to begin with: {shown:?}"
        );

        // Read as CP1251 they are a name. The directory is read again, which is where the
        // names on the screen are made.
        app.panels[app.active].name_page =
            Some(fcmd_view::Codepage::parse("windows-1251").expect("CP1251 is a page"));
        let entries =
            fcmd_vfs::local::list_blocking(&app.panels[app.active].cwd, &CancelToken::new())
                .unwrap();
        let (panel, generation) = (app.active, app.panels[app.active].generation);
        app.handle_event(Event::Listed {
            panel,
            generation,
            result: Ok(entries),
        });
        let shown = names(&app);
        assert!(
            shown.iter().any(|n| n == "привет.txt"),
            "the name is readable now: {shown:?}"
        );

        // And it is still the file on the disk: the path under the cursor is the one the
        // filesystem has, bytes and all, not the text on the screen.
        let row = app.panels[app.active]
            .listing
            .row_of_name("привет.txt")
            .expect("the row is there");
        app.panels[app.active].cursor_to(row);
        let path = app.panels[app.active]
            .current_path()
            .expect("the cursor is on it");
        assert_eq!(
            path.as_path().file_name().map(|n| n.as_bytes()),
            Some(raw),
            "the real name, not the readable one"
        );
        assert_eq!(std::fs::read_to_string(path.as_path()).unwrap(), "hello\n");

        // And back to the system's answer, which is where every panel starts.
        app.panels[app.active].name_page = None;
        let entries =
            fcmd_vfs::local::list_blocking(&app.panels[app.active].cwd, &CancelToken::new())
                .unwrap();
        app.handle_event(Event::Listed {
            panel,
            generation: app.panels[panel].generation,
            result: Ok(entries),
        });
        assert!(names(&app).iter().any(|n| n.contains('\u{fffd}')));
    }

    /// FAR's insertion keys: what about a panel, and which panel — the whole table, with the
    /// two pairs that answer "which" differently (SPEC 06 §7.6).
    #[test]
    fn the_insertion_keys_put_each_part_of_a_panel_on_the_line() {
        use fcmd_cmd::{Insert, Which};

        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("notes.txt"), b"hi\n").unwrap();
        let mut app = app_on_disk(dir.path());
        press(&mut app, "Down"); // notes.txt
        let here = app.panels[0].cwd.to_string();

        app.run(Command::CmdInsert(Insert::Name, Which::Active));
        assert_eq!(app.cmd.text.trim(), "notes.txt");
        app.cmd.clear();

        app.run(Command::CmdInsert(Insert::Path, Which::Active));
        assert_eq!(app.cmd.text.trim(), crate::expand::quote(&here));
        app.cmd.clear();

        // The full name is the path and the name together, which is the one a command wants.
        app.run(Command::CmdInsert(Insert::Full, Which::Active));
        let full = app.cmd.text.trim().to_string();
        assert!(full.contains("notes.txt") && full.contains(here.trim_end_matches('/')));
        app.cmd.clear();

        // `left` and `right` do not follow the focus. The right panel is somewhere else.
        app.panels[1].cwd = VPath::local("/srv");
        app.run(Command::CmdInsert(Insert::Path, Which::Right));
        assert_eq!(app.cmd.text.trim(), "/srv");
        app.cmd.clear();
        app.active = 1;
        app.run(Command::CmdInsert(Insert::Path, Which::Left));
        assert_eq!(app.cmd.text.trim(), crate::expand::quote(&here));
        app.cmd.clear();
        app.active = 0;

        // A path on this disk has no network name, and the key says so rather than inserting
        // the local one under a name that promises more.
        app.run(Command::CmdInsert(Insert::Unc, Which::Active));
        assert!(app.cmd.text.is_empty(), "{}", app.cmd.text);
        assert!(app.status_error, "{}", app.status);

        // The ids the keymaps hold keep working, and the new ones read back.
        for (id, want) in [
            (
                "cmd.insert.name",
                Command::CmdInsert(Insert::Name, Which::Active),
            ),
            (
                "cmd.insert.path.other",
                Command::CmdInsert(Insert::Path, Which::Passive),
            ),
            (
                "cmd.insert.full(right)",
                Command::CmdInsert(Insert::Full, Which::Right),
            ),
        ] {
            assert_eq!(Command::parse(id), Some(want), "{id}");
            assert_eq!(want.id(), id, "round trip");
        }
    }

    /// FAR's *Select folders*: the keys that name a mask leave directories alone unless the
    /// setting says otherwise, and *select all* includes them either way (SPEC 02 §2).
    #[test]
    fn a_mask_selects_files_and_folders_only_when_the_setting_says_so() {
        let mut app = app();
        app.handle_event(Event::Listed {
            panel: 0,
            generation: app.panels[0].generation,
            result: Ok(vec![
                Entry::parent_entry(),
                entry("src", EntryKind::Dir, 0),
                entry("notes.txt", EntryKind::File, 10),
            ]),
        });

        let selected = |app: &App| -> usize {
            let listing = &app.panels[0].listing;
            (0..listing.len())
                .filter_map(|i| listing.row(i))
                .filter(|e| app.panels[0].selection.contains(e.id))
                .count()
        };

        // `+` with a mask that matches both: only the file, as in FAR.
        app.run(Command::SelMaskAdd);
        if let Mode::Prompt(prompt) = &mut app.mode {
            prompt.text = "*".to_string();
        }
        press(&mut app, "Enter");
        assert_eq!(selected(&app), 1, "the directory was left alone");

        app.panels[0].selection.clear();
        app.cfg.panel.select_folders = true;
        app.run(Command::SelMaskAdd);
        if let Mode::Prompt(prompt) = &mut app.mode {
            prompt.text = "*".to_string();
        }
        press(&mut app, "Enter");
        assert_eq!(selected(&app), 2, "now the directory too");

        // And *select all* never asked: it names no mask.
        app.panels[0].selection.clear();
        app.cfg.panel.select_folders = false;
        app.run(Command::SelAll);
        assert_eq!(selected(&app), 2);
    }

    /// A file one comes back to opens where it was left, in the code page and the mode it
    /// was read in (SPEC 05 §1.12).
    #[test]
    fn a_file_opens_where_it_was_left() {
        use fcmd_view::Codepage;

        let dir = tempfile::tempdir().unwrap();
        let body: String = (0..200).map(|n| format!("line {n}\n")).collect();
        std::fs::write(dir.path().join("log.txt"), body.as_bytes()).unwrap();
        let mut app = app_on_disk(dir.path());
        press(&mut app, "Down");
        press(&mut app, "F3");

        // Move, change the page, set a bookmark, and leave.
        {
            let viewer = app.mode.viewer_mut().expect("the viewer");
            viewer.top = 700;
            viewer.set_codepage(Codepage::Cp437);
            viewer.bookmarks[2] = Some(64);
            viewer.wrap = fcmd_view::Wrap::Word;
        }
        press(&mut app, "Esc");
        assert!(app.mode.is_normal());
        assert_eq!(app.seen.len(), 1, "{:?}", app.seen);
        assert_eq!(app.seen[0].top, 700);
        assert_eq!(app.seen[0].codepage, "cp437");
        assert_eq!(app.seen[0].wrap, "word", "{:?}", app.seen[0]);

        // `F3` again, and it is where it was.
        press(&mut app, "F3");
        let viewer = app.mode.viewer().expect("the viewer again");
        assert_eq!(viewer.top, 700);
        assert_eq!(viewer.codepage, Codepage::Cp437);
        assert_eq!(viewer.wrap, fcmd_view::Wrap::Word);
        assert_eq!(viewer.bookmarks[2], Some(64));
        press(&mut app, "Esc");

        // With the setting off, the file opens as a new one does.
        app.cfg.viewer.remember = false;
        press(&mut app, "F3");
        let viewer = app.mode.viewer().expect("the viewer");
        assert_eq!(viewer.top, 0, "nothing is put back");
        assert_eq!(viewer.codepage, Codepage::Utf8);
    }

    /// `Shift+F8` in the viewer is the list of code pages: the ones marked first, `Ins`
    /// marks one, `F4` gives it a name, and `F8` walks only the marked ones (SPEC 05 §1.12).
    #[test]
    fn the_code_page_list_marks_renames_and_sets() {
        use fcmd_view::Codepage;

        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("notes.txt"), b"one\ntwo\n").unwrap();
        let mut app = app_on_disk(dir.path());
        press(&mut app, "Down");
        press(&mut app, "F3");
        assert!(app.mode.viewer().is_some());

        // With nothing marked, `F8` walks the five the program handles itself.
        assert_eq!(
            app.codepage_favourites(),
            Codepage::ALL.to_vec(),
            "the default cycle"
        );

        press(&mut app, "Shift+F8");
        let Mode::Pick(pick) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.kind, crate::menu::PickKind::Codepages);
        assert!(pick.rows.len() > 30, "{} rows", pick.rows.len());

        // Mark KOI8-R: it joins the cycle and the list shows it marked.
        pick.cursor = pick
            .rows
            .iter()
            .position(|r| r.value.eq_ignore_ascii_case("koi8-r"))
            .expect("KOI8-R is offered");
        press(&mut app, "Ins");
        assert_eq!(
            app.codepage_favourites(),
            vec![Codepage::parse("koi8-r").unwrap()],
            "the marked one is the whole cycle now"
        );
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list stays open: {:?}", app.mode)
        };
        assert!(
            pick.lines().iter().any(|l| l.contains("* KOI8-R")),
            "{:?}",
            pick.lines()
        );

        // `F4` gives it a name of its own, and the list shows that instead.
        press(&mut app, "F4");
        let Mode::Prompt(prompt) = &mut app.mode else {
            panic!("{:?}", app.mode)
        };
        // It opens on what the page is called now, so a small change is a few keys.
        assert_eq!(prompt.text, "KOI8-R (Russian)");
        prompt.text = "Russo".to_string();
        press(&mut app, "Enter");
        let Mode::Pick(pick) = &mut app.mode else {
            panic!("back to the list: {:?}", app.mode)
        };
        assert!(
            pick.rows.iter().any(|r| r.label == "Russo"),
            "{:?}",
            pick.rows.iter().map(|r| &r.label).collect::<Vec<_>>()
        );

        // `Enter` reads the file as it, and the status line says the name we gave it.
        pick.cursor = pick
            .rows
            .iter()
            .position(|r| r.value.eq_ignore_ascii_case("koi8-r"))
            .expect("still there");
        press(&mut app, "Enter");
        let viewer = app.mode.viewer_mut().expect("back in the viewer");
        assert_eq!(viewer.codepage, Codepage::parse("koi8-r").unwrap());
        assert_eq!(viewer.status().codepage, "Russo");

        // And `F8` walks the marked ones: one marked page means `F8` stays on it.
        press(&mut app, "F8");
        let viewer = app.mode.viewer().expect("the viewer");
        assert_eq!(viewer.codepage, Codepage::parse("koi8-r").unwrap());
    }

    #[test]
    fn f3_opens_the_viewer_on_a_real_file() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("notes.txt"),
            b"one
two
three
four
five
",
        )
        .unwrap();
        let mut app = app_on_disk(dir.path());

        press(&mut app, "Down"); // notes.txt
        press(&mut app, "F3");
        let viewer = app.mode.viewer().expect("the viewer should be open");
        assert_eq!(viewer.path.display_name(), "notes.txt");
        assert_eq!(viewer.mode, fcmd_view::Mode::Text);

        // Movement goes to the viewer, not to the panel.
        let cursor_before = app.panel().cursor;
        press(&mut app, "Down");
        press(&mut app, "Down");
        assert_eq!(app.panel().cursor, cursor_before, "the panel moved instead");
        let rows = app
            .mode
            .viewer_mut()
            .unwrap()
            .rows(40, 2)
            .into_iter()
            .map(|r| r.text)
            .collect::<Vec<_>>();
        assert_eq!(rows, vec!["three", "four"]);

        press(&mut app, "Esc");
        assert!(app.mode.is_normal(), "Esc should close the viewer");
    }

    #[test]
    fn shift_f10_saves_the_file_and_leaves_the_editor() {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("note.txt");
        std::fs::write(&file, b"one\n").unwrap();
        let mut app = app_on_disk(dir.path());
        press(&mut app, "Down");
        press(&mut app, "F4");
        assert!(app.mode.editor().is_some(), "the editor is open");
        type_text(&mut app, "two");
        press(&mut app, "Shift+F10");
        assert!(app.mode.is_normal(), "it saved and left");
        let on_disk = std::fs::read_to_string(&file).unwrap();
        assert!(on_disk.starts_with("two"), "{on_disk:?}");
    }

    #[test]
    fn ctrl_p_hides_the_panel_that_does_not_have_the_focus() {
        let mut app = app();
        assert_eq!(app.active, 0);
        press(&mut app, "Ctrl+P");
        assert_eq!(app.hidden, Some(1), "the other one goes");
        assert_eq!(app.active, 0, "and the focus stays where it was");
        press(&mut app, "Ctrl+P");
        assert_eq!(app.hidden, None);
        // From the right panel it is the left one that goes.
        press(&mut app, "Tab");
        press(&mut app, "Ctrl+P");
        assert_eq!(app.hidden, Some(0));
        assert_eq!(app.active, 1);
    }

    #[test]
    fn ctrl_w_takes_the_word_before_the_caret_off_the_command_line() {
        let mut app = app();
        typed(&mut app, "cp /usr/local/bin");
        press(&mut app, "Ctrl+W");
        assert_eq!(app.cmd.text, "cp /usr/local/");
        press(&mut app, "Ctrl+W");
        assert_eq!(app.cmd.text, "cp /usr/");
    }

    /// On an empty line the same key is FAR's *Task list* — the operating system's
    /// processes, not this program's screens — because there is no word to take off.
    #[test]
    fn ctrl_w_on_an_empty_line_opens_the_running_processes() {
        let mut app = app();
        press(&mut app, "Ctrl+W");
        // A platform whose process list we cannot read says so and leaves the panel alone.
        if app.panels[0].temp_origin() != Some(":processes") {
            assert!(
                !app.status.is_empty(),
                "nothing opened and nothing was said"
            );
            return;
        }
        assert!(
            app.panels[0].listing.len() > 1,
            "a process list with no processes in it"
        );
    }

    #[test]
    fn the_viewer_toggles_wrap_hex_and_codepage() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("a.txt"),
            b"hello hex
",
        )
        .unwrap();
        let mut app = app_on_disk(dir.path());
        press(&mut app, "Down");
        press(&mut app, "F3");

        // `F4` turns the wheel: text, dump, hex, and round to text again — a plain text file
        // reads as no document and no table, so those two turns are not offered.
        press(&mut app, "F4");
        assert_eq!(app.mode.viewer().unwrap().mode, fcmd_view::Mode::Dump);
        press(&mut app, "F4");
        assert_eq!(app.mode.viewer().unwrap().mode, fcmd_view::Mode::Hex);
        press(&mut app, "F4");
        assert_eq!(app.mode.viewer().unwrap().mode, fcmd_view::Mode::Text);
        // `Shift+F4` is hex and straight back, for when hex is the one that was wanted.
        press(&mut app, "Shift+F4");
        assert_eq!(app.mode.viewer().unwrap().mode, fcmd_view::Mode::Hex);
        press(&mut app, "Shift+F4");
        assert_eq!(app.mode.viewer().unwrap().mode, fcmd_view::Mode::Text);

        press(&mut app, "F2");
        assert_eq!(app.mode.viewer().unwrap().wrap, fcmd_view::Wrap::Char);
        assert!(app.status.contains("wrap"), "{}", app.status);

        press(&mut app, "F8");
        assert_eq!(app.mode.viewer().unwrap().codepage.name(), "UTF-16LE");
        assert!(app.status.contains("codepage"), "{}", app.status);
    }

    /// A diff of two files that differ: the screen, the hunks, and what the three letters
    /// change (SPEC 05 §3).
    #[test]
    fn two_files_are_compared_side_by_side_and_the_hunks_are_walked() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), b"one\ntwo\nthree\nfour\nfive\n").unwrap();
        std::fs::write(dir.path().join("b.txt"), b"one\nTWO\nthree\nfour\nFIVE\n").unwrap();
        let mut app = app_on_disk(dir.path());
        // The left cursor on the first file, the right one on the second: the question
        // "which two files" is answered by where the cursors are.
        press(&mut app, "Down");
        press(&mut app, "Tab");
        press(&mut app, "Down");
        press(&mut app, "Down");
        press(&mut app, "Ctrl+Shift+D");

        let Mode::Diff(view) = &app.mode else {
            panic!("no diff: {}", app.status)
        };
        assert!(view.left_name.ends_with("a.txt"), "{}", view.left_name);
        assert!(view.right_name.ends_with("b.txt"), "{}", view.right_name);
        assert_eq!(view.hunks(), 2, "the second line and the fifth");
        assert!(!view.identical());

        // `Alt+↓` walks them, and the last one says it is the last rather than wrapping
        // round to the top of a file one has just read.
        assert_eq!(app.mode.diff().unwrap().hunk_at(), 0);
        press(&mut app, "Alt+Down");
        assert_eq!(app.mode.diff().unwrap().hunk_at(), 1);
        press(&mut app, "Alt+Down");
        assert_eq!(app.mode.diff().unwrap().hunk_at(), 2);
        press(&mut app, "Alt+Down");
        assert_eq!(
            app.mode.diff().unwrap().hunk_at(),
            2,
            "it stays on the last"
        );
        assert_eq!(app.status, app.i18n.t("diff-no-next"));
        assert!(app.status_error);
        press(&mut app, "Alt+Up");
        assert_eq!(app.mode.diff().unwrap().hunk_at(), 1);

        // `Tab` is the other column, for the sideways scroll and for reading a long line.
        assert!(!app.mode.diff().unwrap().right_focused);
        press(&mut app, "Tab");
        assert!(app.mode.diff().unwrap().right_focused);

        // Ignoring case lines the two files up completely: both differences were a word in
        // capitals, so the answer becomes "the same" while one looks at it.
        press(&mut app, "C");
        let view = app.mode.diff().unwrap();
        assert!(view.ignore.case);
        assert_eq!(view.hunks(), 0);
        assert!(view.identical());
        assert_eq!(app.status, app.i18n.t("diff-ignore-case-on"));
        press(&mut app, "C");
        assert_eq!(app.mode.diff().unwrap().hunks(), 2, "and back again");

        // `W` and `E` are the other two questions one asks of a diff.
        press(&mut app, "W");
        assert!(app.mode.diff().unwrap().ignore.whitespace);
        press(&mut app, "E");
        assert!(
            app.mode.diff().unwrap().ignore.line_endings,
            "the comparison dialog leaves line endings counting, so `E` turns them off"
        );

        press(&mut app, "Esc");
        assert!(matches!(app.mode, Mode::Normal), "and it closes");
    }

    /// `F5` and `F2` on the diff screen: take a difference across, and write it.
    #[test]
    fn a_difference_is_taken_across_and_written_to_the_file_that_took_it() {
        let dir = tempfile::tempdir().unwrap();
        let (a, b) = (dir.path().join("a.txt"), dir.path().join("b.txt"));
        std::fs::write(&a, b"one\ntwo\nthree\n").unwrap();
        std::fs::write(&b, b"one\nTWO\nthree\n").unwrap();
        let mut app = app_on_disk(dir.path());
        press(&mut app, "Down");
        press(&mut app, "Tab");
        press(&mut app, "Down");
        press(&mut app, "Down");
        press(&mut app, "Ctrl+Shift+D");
        assert!(app.mode.diff().is_some(), "no diff: {}", app.status);

        // Nothing to write before anything is taken, and the top row is a line both files
        // agree about, so `F5` there says so rather than taking the next hunk by surprise.
        press(&mut app, "F2");
        assert_eq!(app.status, app.i18n.t("diff-nothing-to-write"));
        press(&mut app, "F5");
        assert_eq!(app.status, app.i18n.t("diff-no-hunk-here"));
        assert!(!app.mode.diff().unwrap().edited());

        // On the hunk, `F5` gives the left file the right one's line. Nothing on the disk yet.
        press(&mut app, "Alt+Down");
        press(&mut app, "F5");
        assert_eq!(app.status, app.i18n.t("diff-merged-left"));
        let view = app.mode.diff().unwrap();
        assert!(view.left_edited && !view.right_edited);
        assert!(view.identical(), "the two now agree on screen");
        assert_eq!(
            std::fs::read_to_string(&a).unwrap(),
            "one\ntwo\nthree\n",
            "and the disk has not been touched"
        );

        // `Esc` does not throw that away without saying so; a second one would.
        press(&mut app, "Esc");
        assert!(app.mode.diff().is_some(), "it is still open");
        assert_eq!(app.status, app.i18n.t("diff-unwritten"));

        // `F2` writes it, and only the side that was merged into.
        press(&mut app, "F2");
        assert_eq!(std::fs::read_to_string(&a).unwrap(), "one\nTWO\nthree\n");
        assert_eq!(std::fs::read_to_string(&b).unwrap(), "one\nTWO\nthree\n");
        assert!(!app.mode.diff().unwrap().edited(), "nothing left to write");
        assert!(
            !dir.path().join("a.txt.fcmd-part").exists(),
            "and the part file it was written through is gone"
        );

        // Which means `Esc` now leaves at the first press.
        press(&mut app, "Esc");
        assert!(matches!(app.mode, Mode::Normal), "and it closes");
    }

    /// Two files that are the same open all the same — one wants to see that they are —
    /// and the screen says so rather than leaving the reader to scroll for a difference
    /// that is not there.
    #[test]
    fn a_diff_of_two_equal_files_says_they_are_the_same() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), b"same\nlines\n").unwrap();
        std::fs::write(dir.path().join("b.txt"), b"same\nlines\n").unwrap();
        let mut app = app_on_disk(dir.path());
        press(&mut app, "Down");
        press(&mut app, "Tab");
        press(&mut app, "Down");
        press(&mut app, "Down");
        press(&mut app, "Ctrl+Shift+D");

        let view = app.mode.diff().expect("the diff");
        assert!(view.identical());
        assert_eq!(view.hunks(), 0);
        assert_eq!(app.status, app.i18n.t("diff-same"));
    }

    /// `U` shows the same comparison as one column and back, and `Shift+F2` saves it as a
    /// unified diff under the name that is asked for — through the question and back to the
    /// comparison, whether the question was answered or left.
    #[test]
    fn the_diff_goes_unified_and_is_saved_as_a_patch() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), b"one\ntwo\nthree\n").unwrap();
        std::fs::write(dir.path().join("b.txt"), b"one\n2\nthree\nfour\n").unwrap();
        let mut app = app_on_disk(dir.path());
        let cwd = app.panels[0].cwd.clone();
        press(&mut app, "Down");
        press(&mut app, "Tab");
        press(&mut app, "Down");
        press(&mut app, "Down");
        press(&mut app, "Ctrl+Shift+D");
        assert!(!app.mode.diff().expect("the diff").unified);

        press(&mut app, "u");
        assert!(app.mode.diff().expect("the diff").unified);
        assert_eq!(app.status, app.i18n.t("diff-unified-on"));
        let mut buf = fcmd_ui::Buffer::new(80, 24);
        crate::render::draw(&mut app, &mut buf);
        let text = buf.to_text();
        let lines: Vec<&str> = text
            .lines()
            .filter(|l| l.contains("- two") || l.contains("+ 2") || l.contains("+ four"))
            .collect();
        assert_eq!(lines.len(), 3, "one line each, under one another:\n{text}");
        assert!(lines[0].contains("    2       - two"), "{text}");
        assert!(lines[1].contains("          2 + 2"), "{text}");
        assert!(
            text.contains("    3     3   three"),
            "both numbers on a line both have"
        );

        // The question offers the right file's name, and `Esc` comes back to the diff.
        press(&mut app, "Shift+F2");
        let Mode::Prompt(prompt) = &app.mode else {
            panic!("no question: {:?}", app.mode)
        };
        assert_eq!(prompt.text, "b.txt.diff");
        press(&mut app, "Esc");
        assert!(app.mode.diff().is_some_and(|d| d.unified), "{:?}", app.mode);
        assert!(!cwd.join("b.txt.diff").as_path().exists());

        press(&mut app, "Shift+F2");
        clear_prompt(&mut app);
        type_text(&mut app, "change.patch");
        press(&mut app, "Enter");
        assert!(
            app.mode.diff().is_some(),
            "back on the diff: {:?}",
            app.mode
        );
        assert!(!app.status_error, "{}", app.status);
        assert!(app.status.contains("change.patch"), "{}", app.status);
        let saved = std::fs::read_to_string(cwd.join("change.patch").as_path()).unwrap();
        let (left, right) = (cwd.join("a.txt"), cwd.join("b.txt"));
        assert_eq!(
            saved,
            format!("--- {left}\n+++ {right}\n@@ -1,3 +1,4 @@\n one\n-two\n+2\n three\n+four\n")
        );

        // A name in a folder that is not there is refused, and the diff is still in front.
        press(&mut app, "Shift+F2");
        clear_prompt(&mut app);
        type_text(&mut app, "no-such-folder/x.diff");
        press(&mut app, "Enter");
        assert!(app.status_error, "{}", app.status);
        assert!(app.mode.diff().is_some());

        press(&mut app, "u");
        assert!(!app.mode.diff().expect("the diff").unified);
        assert_eq!(app.status, app.i18n.t("diff-unified-off"));
    }

    /// Two files that are the same have no patch, and `Shift+F2` says so without asking for
