        std::fs::create_dir(dir.path().join("deep")).unwrap();
        let file = dir.path().join("deep/notes.txt");
        std::fs::write(&file, "x").unwrap();
        let mut app = editing_app(dir.path());
        app.file_history = vec![file.display().to_string()];
