    /// `Ctrl+Alt+G` in the viewer asks git who wrote the file, and the answer opens on the
    /// line that was on top.
    #[test]
    fn blame_in_the_viewer_keeps_the_line() {
        let dir = tempfile::tempdir().unwrap();
        let text: String = (0..40).map(|i| format!("line {i}\n")).collect();
        std::fs::write(dir.path().join("a.rs"), &text).unwrap();
        let mut app = app_on_disk(dir.path());
        app.panels[0].cursor = app.panels[0].listing.row_of_name("a.rs").unwrap();
        press(&mut app, "F3");
        for _ in 0..12 {
            press(&mut app, "Down");
        }
        app.take_requests();
        press(&mut app, "Ctrl+Alt+G");
        let (id, line) = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::Filter { id, line, .. } => Some((id, line)),
                _ => None,
            })
            .expect("git blame asked");
        assert!(line.starts_with("git blame --date=short -- "), "{line}");
        let blamed: String = (0..40)
            .map(|i| format!("abc1234 (Matteo 2026-11-11 {i:>2}) line {i}\n"))
            .collect();
        app.handle_event(Event::Decompiled {
            id,
            tool: line,
            result: Ok(blamed),
        });
        let viewer = app.mode.viewer_mut().expect("the viewer");
        assert_eq!(viewer.line_at_top(), 12);
        assert!(viewer.rows(80, 1)[0].text.ends_with("line 12"));
    }

    /// `file.strip_metadata` on a picture: three ways to choose from, and the one chosen
    /// goes to the worker with the picture and a place for the copy the undo needs.
    #[test]
    fn strip_metadata_asks_how_and_sends_the_pictures() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.png"), b"x").unwrap();
        std::fs::write(dir.path().join("notes.txt"), b"x").unwrap();
        let mut app = app_on_disk(dir.path());
        let row = |app: &App, name: &str| {
            (0..app.panels[0].listing.len())
                .find(|&r| app.panels[0].listing.row(r).unwrap().name_str() == name)
                .unwrap()
        };
        app.panels[0].cursor = row(&app, "notes.txt");
        app.run(Command::FileStripMeta);
        assert!(app.mode.is_normal(), "a text file has no picture metadata");
        app.panels[0].cursor = row(&app, "a.png");
        app.run(Command::FileStripMeta);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::StripMeta);
        assert_eq!(pick.rows.len(), 3);
        press(&mut app, "Down");
        press(&mut app, "Enter");
        let sent = app.take_requests().into_iter().find_map(|r| match r {
            Request::StripMeta { files, how, backup } => Some((files, how, backup)),
            _ => None,
        });
        let (files, how, backup) = sent.expect("the pictures went to the worker");
        assert_eq!(files, vec![dir.path().join("a.png")]);
        assert_eq!(how, fcmd_view::strip::Strip::Ai);
        assert!(backup.to_string_lossy().contains("fcmd-undo"));
        app.handle_event(Event::StripDone {
            done: vec![(dir.path().join("a.png"), backup.join("0-a.png"))],
            removed: 2,
            untouched: 0,
            errors: Vec::new(),
        });
        assert!(matches!(
            app.undo_stack.last(),
            Some(crate::undo::Undo::Restore { .. })
        ));
    }

    /// `Esc` while a question is out stops it: the token it went with is cancelled, the wait
    /// is gone from the screen, and an answer that still comes back is not shown.
    #[test]
    fn esc_stops_a_question_and_its_late_answer_is_dropped() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_on_disk(dir.path());
        app.cfg.ais.push(fcmd_config::AiCfg {
            name: "local".into(),
            url: "http://localhost:11434/api/chat".into(),
            api: "ollama".into(),
            ..Default::default()
        });
        app.ai_line("hello".into());
        let token = app
            .requests
            .iter()
            .find_map(|r| match r {
                Request::AiAsk { cancel, .. } => Some(cancel.clone()),
                _ => None,
            })
            .expect("a question went");
        press(&mut app, "Esc");
        assert!(token.is_cancelled());
        assert!(app.ai_busy.is_none());
        assert!(app.status.contains("stopped"), "{}", app.status);
        app.handle_event(Event::AiDone {
            result: Err("late".into()),
        });
        assert!(!app.status.contains("late"), "{}", app.status);
        // The next question is shown as usual.
        app.ai_line("again".into());
        app.handle_event(Event::AiDone {
            result: Err("nope".into()),
        });
        assert!(app.status.contains("nope"), "{}", app.status);
    }

    /// In the AI service dialog the address follows the protocol, `Alt+↓` lists the
    /// protocols, and `Ctrl+A` selects a whole line so typing replaces it.
    #[test]
    fn the_ai_address_follows_the_protocol_and_ctrl_a_selects_a_line() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_on_disk(dir.path());
        app.run(Command::ToolAi);
        press(&mut app, "Ins");
        let at = |app: &App, want: &str| {
            let Mode::Form(form) = &app.mode else {
                panic!("the dialog: {:?}", app.mode)
            };
            form.fields
                .iter()
                .position(|f| match f {
                    crate::form::Field::Text { key, .. }
                    | crate::form::Field::Choice { key, .. } => *key == want,
                    _ => false,
                })
                .unwrap()
        };
        let api = at(&app, "ai.api");
        let Mode::Form(form) = &mut app.mode else {
            unreachable!()
        };
        form.set_text("ai.url", "http://localhost:8080/v1/chat/completions".into());
        form.cursor = api;
        press(&mut app, "Alt+Down");
        let Mode::Pick(pick) = &mut app.mode else {
            panic!("the protocols are listed: {:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::FieldChoice);
        pick.cursor = pick.rows.iter().position(|r| r.value == "ollama").unwrap();
        press(&mut app, "Enter");
        let Mode::Form(form) = &mut app.mode else {
            panic!("back in the dialog: {:?}", app.mode)
        };
        assert_eq!(form.choice_value("ai.api"), "ollama");
        assert_eq!(form.text_value("ai.url"), "http://localhost:8080/api/chat");

        let url = at(&app, "ai.url");
        let Mode::Form(form) = &mut app.mode else {
            unreachable!()
        };
        form.cursor = url;
        press(&mut app, "Ctrl+A");
        let Mode::Form(form) = &app.mode else {
            unreachable!()
        };
        assert_eq!(form.selected_text(), Some("http://localhost:8080/api/chat"));
        press(&mut app, "Ctrl+C");
        assert!(app
            .take_requests()
            .iter()
            .any(|r| matches!(r, Request::Clipboard { text } if text.ends_with("/api/chat"))));
        for c in "h:1".chars() {
            press(&mut app, &c.to_string());
        }
        let Mode::Form(form) = &app.mode else {
            unreachable!()
        };
        assert_eq!(
            form.text_value("ai.url"),
            "h:1",
            "typing replaced the selected line"
        );
    }

    /// The AI services are a list kept like the sessions: a new one through its dialog, the
    /// one chosen becomes the one `ai:` asks, and a key nobody gave is asked for, not assumed.
    #[test]
    fn the_ai_services_are_a_list_and_a_missing_key_is_asked_for() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_on_disk(dir.path());
        app.run(Command::ToolAi);
        assert!(matches!(&app.mode, Mode::Pick(p) if p.kind == PickKind::AiServices));
        for name in ["first", "second"] {
            press(&mut app, "Ins");
            let Mode::Form(form) = &mut app.mode else {
                panic!("the dialog: {:?}", app.mode)
            };
            assert_eq!(form.kind, FormKind::AiService);
            form.set_text("ai.name", name.to_string());
            form.set_text("ai.token_env", "FCMD_TEST_NO_SUCH_KEY".to_string());
            press(&mut app, "F10");
        }
        assert_eq!(app.cfg.ais.len(), 2);
        let saved = std::fs::read_to_string(dir.path().join("fcmd.toml")).unwrap();
        assert!(saved.contains("second"), "kept in the settings");

        // The second, chosen, is the one `ai:` asks now.
        let Mode::Pick(pick) = &mut app.mode else {
            panic!("back to the list: {:?}", app.mode)
        };
        pick.cursor = 1;
        press(&mut app, "Enter");
        assert_eq!(app.cfg.ais[0].name, "second");

        // No key in the variable: asked for, secretly, and then the question goes.
        app.mode = Mode::Normal;
        app.take_requests();
        app.ai_line("hello".into());
        let Mode::Prompt(mut prompt) = std::mem::replace(&mut app.mode, Mode::Normal) else {
            panic!("the key is asked for: {:?}", app.mode)
        };
        assert!(prompt.secret && prompt.kind == PromptKind::AiKey);
        prompt.text = "sk-typed".into();
        app.prompt_accept(prompt);
        // Offered a secrets file around it; left empty, the key is for this session only.
        let Mode::Prompt(mut prompt) = std::mem::replace(&mut app.mode, Mode::Normal) else {
            panic!("the secrets file is offered: {:?}", app.mode)
        };
        assert_eq!(prompt.kind, PromptKind::VaultNew);
        prompt.text = String::new();
        app.prompt_accept(prompt);
        assert!(!app.vault_path().exists(), "nothing written when declined");
        let sent = app.take_requests().into_iter().find_map(|r| match r {
            Request::AiAsk { token, .. } => Some(token),
            _ => None,
        });
        assert_eq!(sent, Some(Some("sk-typed".to_string())));
        // Asked once: the next question uses the key already given.
        app.ai_line("again".into());
        assert!(!matches!(app.mode, Mode::Prompt(_)));
        assert!(
            !saved.contains("sk-typed")
                && !std::fs::read_to_string(dir.path().join("fcmd.toml"))
                    .unwrap()
                    .contains("sk-typed")
        );
    }

    /// A project's `.editorconfig` sets the indentation and the trailing blanks for the files
    /// under it, over the settings.
    #[test]
    fn an_editorconfig_tunes_the_editor_for_its_files() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join(".editorconfig"),
            "root = true\n[*.py]\nindent_style = space\nindent_size = 3\ntrim_trailing_whitespace = true\n",
        )
        .unwrap();
        std::fs::write(dir.path().join("a.py"), "x = 1\n").unwrap();
        std::fs::write(dir.path().join("b.txt"), "x\n").unwrap();
        let mut app = editing_app(dir.path());
        app.cfg.editor.tab_width = 8;
        app.open_editor_on(&VPath::local(dir.path().join("a.py")));
        let Mode::Editor(e) = &app.mode else {
            panic!("an editor")
        };
        assert_eq!(
            (e.tab_width, e.expand_tabs, e.trim_on_save),
            (3, true, Some(true))
        );
        app.mode = Mode::Normal;
        app.open_editor_on(&VPath::local(dir.path().join("b.txt")));
        let Mode::Editor(e) = &app.mode else {
            panic!("an editor")
        };
        assert_eq!(
            (e.tab_width, e.trim_on_save),
            (8, None),
            "not a .py: the settings"
        );
    }

