    /// The git menu over a folder of this disk, and what changed coming back as a panel of
    /// the real files, each row starting with its status.
    #[test]
    fn the_git_menu_asks_and_what_changed_is_a_panel() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), "x").unwrap();
        let mut app = editing_app(dir.path());
        app.run(Command::ToolGit);
        let Mode::Pick(pick) = &app.mode else {
            panic!("the menu: {:?}", app.mode)
        };
        assert_eq!(pick.kind, PickKind::Git);
        app.take_requests();
        press(&mut app, "Enter"); // what changed
        let asked = app.take_requests().into_iter().any(|r| {
            matches!(
                r,
                Request::Git {
                    what: GitAsk::Status,
                    ..
                }
            )
        });
        assert!(asked);
        app.handle_event(Event::GitDone {
            panel: 0,
            result: Ok(GitOut::Status {
                root: dir.path().to_path_buf(),
                files: vec![(" M".into(), "a.txt".into()), ("??".into(), "b.txt".into())],
            }),
        });
        let p = &app.panels[0];
        assert_eq!(p.temp_origin(), Some(":git"));
        let names: Vec<String> = (0..p.listing.len())
            .filter_map(|r| p.listing.row(r))
            .map(|e| e.name_str().into_owned())
            .collect();
        let has = |name: &str| names.iter().any(|n| n.ends_with(name));
        assert!(has("a.txt") && has("b.txt"), "{names:?}");
        assert!(names[0].starts_with("not staged") && names[0].contains("modified"));
        assert!(names[1].starts_with("untracked"), "{names:?}");
    }

    /// A copy into the repository from the other panel ends with git asked again, so the
    /// file it made shows up in what changed instead of the panel keeping the rows it had.
    #[test]
    fn a_job_that_ends_asks_git_again_for_what_changed() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), "x").unwrap();
        let mut app = editing_app(dir.path());
        app.handle_event(Event::GitDone {
            panel: 0,
            result: Ok(GitOut::Status {
                root: dir.path().to_path_buf(),
                files: vec![(" M".into(), "a.txt".into())],
            }),
        });
        assert_eq!(app.panels[0].temp_origin(), Some(":git"));
        app.start_job(JobSpec::new(
            JobKind::Copy,
            vec![VPath::local(dir.path().join("a.txt"))],
            Some(VPath::local(dir.path().join("b.txt"))),
        ));
        let id = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::Job { id, .. } => Some(id),
                _ => None,
            })
            .expect("the copy");
        app.handle_event(Event::JobDone {
            id,
            kind: JobKind::Copy,
            outcome: fcmd_jobs::Outcome {
                files: 1,
                ..Default::default()
            },
        });
        let asked = app.take_requests().into_iter().any(|r| {
            matches!(
                r,
                Request::Git {
                    panel: 0,
                    what: GitAsk::Status,
                    ..
                }
            )
        });
        assert!(asked, "what changed is asked again");
    }

    /// Everything git does here is a panel: in what changed `F5` stages, `F6` unstages, `F3`
    /// is the diff, `F7` commits after asking the message, `F8` is the file's log; the log is
    /// a panel whose `Enter` shows a commit; the branches are a panel whose `Enter` switches
    /// after asking; and `Ctrl+R` asks git again rather than reading the rows as files.
    /// `Alt+F1` offers Git only where there is a repository, and on it opens the log; the
    /// log's function keys are the rest of git; and the quick view beside the log shows the
    /// commit under the cursor, asked of git on a worker.
    #[test]
    fn git_is_a_drive_row_in_a_repository_and_the_log_drives_the_rest() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = editing_app(dir.path());
        let has_git = |app: &App| app.drive_list(0).rows.iter().any(|r| r.value == ":gitlog");
        app.panels[0].git = None;
        assert!(!has_git(&app), "no repository, no row");
        app.panels[0].git = Some(fcmd_core::git::Repo {
            root: dir.path().to_path_buf(),
            git_dir: dir.path().join(".git"),
            branch: Some("main".into()),
            head: None,
            state: None,
            index: None,
        });
        assert!(has_git(&app));

        let asked = |app: &mut App| -> Vec<GitAsk> {
            app.take_requests()
                .into_iter()
                .filter_map(|r| match r {
                    Request::Git { what, .. } => Some(what),
                    _ => None,
                })
                .collect()
        };
        app.take_requests();
        app.git_view = Some(GitAsk::Log {
            file: None,
            rev: None,
        });
        app.handle_event(Event::GitDone {
            panel: 0,
            result: Ok(GitOut::Log(vec![GitCommit {
                hash: "abc1234".into(),
                date: "2026-11-06".into(),
                author: "M".into(),
                subject: "first".into(),
            }])),
        });
        assert_eq!(app.panels[0].temp_origin(), Some(":gitlog"));
        app.panels[0].cursor = 0;
        app.take_requests();
        press(&mut app, "F4");
        assert_eq!(asked(&mut app), vec![GitAsk::Status]);
        press(&mut app, "F5");
        assert_eq!(asked(&mut app), vec![GitAsk::Pull]);
        press(&mut app, "F6");
        assert_eq!(asked(&mut app), vec![GitAsk::Push]);
        press(&mut app, "F8");
        assert_eq!(asked(&mut app), vec![GitAsk::Branches]);
        press(&mut app, "F7");
        assert!(matches!(&app.mode, Mode::Prompt(p) if p.kind == PromptKind::GitCommit));
        app.mode = Mode::Normal;

        // The quick view asks for the commit, and shows what comes back for that row.
        app.take_requests();
        app.quick_of = None;
        app.quick_view_for(0);
        let key = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::GitQuick { key, what, .. } => {
                    assert_eq!(what, GitAsk::Show("abc1234".into()));
                    Some(key)
                }
                _ => None,
            })
            .expect("asked git for the commit");
        app.handle_event(Event::GitQuick {
            key,
            result: Ok("commit abc1234\n\n    first\n".into()),
        });
        assert!(app.quick.is_some(), "{:?}", app.quick_why);
    }

    /// What changed says in words which part each row is in: a file staged and changed again
    /// is a row in each, with its own diff — side by side on `F3`, coloured in the quick view —
    /// and the tree heads the files with their folder, which `F5` stages whole.
    #[test]
    fn what_changed_has_a_row_per_part_a_diff_each_and_a_tree() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join("src")).unwrap();
        std::fs::write(dir.path().join("src/a.rs"), "x").unwrap();
        let mut app = editing_app(dir.path());
        let asked = |app: &mut App| -> Vec<GitAsk> {
            app.take_requests()
                .into_iter()
                .filter_map(|r| match r {
                    Request::Git { what, .. } => Some(what),
                    _ => None,
                })
                .collect()
        };
        app.handle_event(Event::GitDone {
            panel: 0,
            result: Ok(GitOut::Status {
                root: dir.path().to_path_buf(),
                files: vec![("MM".into(), "src/a.rs".into())],
            }),
        });
        let names = |app: &App| -> Vec<String> {
            let p = &app.panels[0];
            (0..p.listing.len())
                .filter_map(|r| p.listing.row(r))
                .map(|e| e.name_str().into_owned())
                .collect()
        };
        let list = names(&app);
        assert_eq!(list.len(), 2, "{list:?}");
        assert!(list[0].starts_with("staged") && list[0].ends_with("src/a.rs"));
        assert!(list[1].starts_with("not staged") && list[1].ends_with("src/a.rs"));
        let file = dir.path().join("src/a.rs");

        app.take_requests();
        app.panels[0].cursor = 0;
        press(&mut app, "F3");
        assert_eq!(
            asked(&mut app),
            vec![GitAsk::Sides {
                file: file.clone(),
                staged: true
            }]
        );
        app.panels[0].cursor = 1;
        press(&mut app, "F3");
        assert_eq!(
            asked(&mut app),
            vec![GitAsk::Sides {
                file: file.clone(),
                staged: false
            }]
        );
        // The quick view beside it asks for the diff of the row, not the whole file.
        app.quick_of = None;
        app.quick_view_for(0);
        let quick = app.take_requests().into_iter().find_map(|r| match r {
            Request::GitQuick { what, .. } => Some(what),
            _ => None,
        });
        assert_eq!(
            quick,
            Some(GitAsk::Diff {
                file: file.clone(),
                staged: false
            })
        );

        // As a tree: the folder heads each part, and `F5` on it stages the folder.
        app.git_menu("tree");
        let tree = names(&app);
        assert_eq!(tree.len(), 4, "{tree:?}");
        assert!(tree[0].ends_with("src/"), "{tree:?}");
        assert!(
            tree[1].ends_with("  a.rs") && !tree[1].contains("src/"),
            "{tree:?}"
        );
        app.panels[0].cursor = 0;
        app.take_requests();
        press(&mut app, "F5");
        assert_eq!(
            asked(&mut app),
            vec![GitAsk::Stage(vec![dir.path().join("src")])]
        );
        app.git_menu("tree");
        assert_eq!(names(&app).len(), 2, "back to the list");
    }

    #[test]
    fn the_git_panels_stage_commit_show_and_switch() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), "x").unwrap();
        let mut app = editing_app(dir.path());
        let asked = |app: &mut App| -> Vec<GitAsk> {
            app.take_requests()
                .into_iter()
                .filter_map(|r| match r {
                    Request::Git { what, .. } => Some(what),
                    _ => None,
                })
                .collect()
        };
        app.git_view = Some(GitAsk::Status);
        app.handle_event(Event::GitDone {
            panel: 0,
            result: Ok(GitOut::Status {
                root: dir.path().to_path_buf(),
                files: vec![(" M".into(), "a.txt".into())],
            }),
        });
        assert_eq!(app.panels[0].temp_origin(), Some(":git"));
        assert!(app.panels[0].temp.as_ref().unwrap().title.contains('0'));
        app.panels[0].cursor = 0;
        app.take_requests();
        let file = dir.path().join("a.txt");

        press(&mut app, "F5");
        assert_eq!(asked(&mut app), vec![GitAsk::Stage(vec![file.clone()])]);
        press(&mut app, "F6");
        assert_eq!(asked(&mut app), vec![GitAsk::Unstage(vec![file.clone()])]);
        press(&mut app, "F3");
        assert_eq!(
            asked(&mut app),
            vec![GitAsk::Sides {
                file: file.clone(),
                staged: false
            }]
        );
        // `F8` throws the change away, but only after asking — and Cancel is the button lit.
        press(&mut app, "F8");
        let Mode::Confirm(c) = &app.mode else {
            panic!("a question first: {:?}", app.mode)
        };
        assert_eq!(c.button, 1);
        assert!(c.lines.iter().any(|l| l.contains("a.txt")), "{:?}", c.lines);
        press(&mut app, "Esc");
        assert!(asked(&mut app).is_empty(), "nothing goes on Esc");
        press(&mut app, "F8");
        press(&mut app, "Left");
        press(&mut app, "Enter");
        assert_eq!(
            asked(&mut app),
            vec![GitAsk::Discard {
                worktree: vec![file.clone()],
                both: vec![],
                added: vec![],
            }]
        );
        // `F7` asks the message first, and an empty one commits nothing.
        press(&mut app, "F7");
        assert!(matches!(&app.mode, Mode::Prompt(p) if p.kind == PromptKind::GitCommit));
        for c in "fix".chars() {
            press(&mut app, &c.to_string());
        }
        press(&mut app, "Enter");
        assert_eq!(asked(&mut app), vec![GitAsk::Commit("fix".into())]);
        // What git did is said, and the panel is asked for again.
        app.handle_event(Event::GitDone {
            panel: 0,
            result: Ok(GitOut::Done("[main 1234567] fix".into())),
        });
        assert!(app.status.contains("1234567"), "{}", app.status);
        assert_eq!(asked(&mut app), vec![GitAsk::Status]);
        app.run(Command::PanelReread);
        assert_eq!(asked(&mut app), vec![GitAsk::Status]);

        // The log is a panel, newest first, and `Enter` shows a commit.
        app.git_view = Some(GitAsk::Log {
            file: None,
            rev: None,
        });
        app.handle_event(Event::GitDone {
            panel: 0,
            result: Ok(GitOut::Log(vec![
                GitCommit {
                    hash: "bbb2222".into(),
                    date: "2026-11-06".into(),
                    author: "M".into(),
                    subject: "second".into(),
                },
                GitCommit {
                    hash: "aaa1111".into(),
                    date: "2026-11-05".into(),
                    author: "M".into(),
                    subject: "first".into(),
                },
            ])),
        });
        assert_eq!(app.panels[0].temp_origin(), Some(":gitlog"));
        let first = app.panels[0]
            .listing
            .row(0)
            .unwrap()
            .name_str()
            .into_owned();
        assert!(first.starts_with("bbb2222"), "newest first: {first}");
        app.panels[0].cursor = 0;
        press(&mut app, "Enter");
        assert_eq!(asked(&mut app), vec![GitAsk::Show("bbb2222".into())]);
        // `F5` on the log is a pull, not a copy of a commit.
        press(&mut app, "F5");
        assert_eq!(asked(&mut app), vec![GitAsk::Pull]);

        // The branches are a panel; `Enter` on another asks, and yes switches.
        app.handle_event(Event::GitDone {
            panel: 0,
            result: Ok(GitOut::Branches(vec![
                ("main".into(), true),
                ("dev".into(), false),
            ])),
        });
        assert_eq!(app.panels[0].temp_origin(), Some(":gitbranches"));
        let at = (0..app.panels[0].listing.len())
            .find(|&r| {
                app.panels[0]
                    .listing
                    .row(r)
                    .unwrap()
                    .name_str()
                    .contains("dev")
            })
            .unwrap();
        app.panels[0].cursor = at;
        press(&mut app, "Enter");
        assert!(matches!(&app.mode, Mode::Confirm(_)), "{:?}", app.mode);
        press(&mut app, "Enter");
        assert_eq!(asked(&mut app), vec![GitAsk::Switch("dev".into())]);
        // `F2` there is the git menu, with push and pull in it.
        press(&mut app, "F2");
        let Mode::Pick(pick) = &app.mode else {
            panic!("no menu: {:?}", app.mode)
        };
        assert!(pick.rows.iter().any(|r| r.value == "push"));
        assert!(pick.rows.iter().any(|r| r.value == "pull"));
    }

    /// `ai:` asks the first service; `ai:name:` another; files go only after a dialog that
    /// names them and the host; `ai:` alone opens the answers as a panel.
    #[test]
    fn an_ai_line_asks_and_files_wait_for_a_yes() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), "hello").unwrap();
        let mut app = editing_app(dir.path());
        app.cmd.set("ai: why?");
        press(&mut app, "Enter");
        assert!(app.status_error, "no service yet: {}", app.status);
        let ai = |name: &str| fcmd_config::AiCfg {
            name: name.into(),
            url: "https://api.example.com/v1/chat/completions".into(),
            model: "m".into(),
            api: "openai".into(),
            ..Default::default()
        };
        app.cfg.ais = vec![ai("first"), ai("local")];
        // Keys typed earlier in the session, so the question goes without asking for one.
        app.ai_tokens.insert("first".into(), "k".into());
        app.ai_tokens.insert("local".into(), "k".into());
        app.take_requests();
        app.cmd.set("ai: local: why: really?");
        press(&mut app, "Enter");
        let asked = app.take_requests().into_iter().find_map(|r| match r {
            Request::AiAsk { query, .. } => Some((query.service.name, query.question, query.files)),
            _ => None,
        });
        assert_eq!(asked, Some(("local".into(), "why: really?".into(), vec![])));
        // A selected file: a dialog first, naming the host, and nothing asked yet.
        let at = app.panels[0].listing.row_of_name("a.txt").unwrap();
        app.panels[0].cursor = at;
        press(&mut app, "Insert");
        app.cmd.set("ai: what is this?");
        press(&mut app, "Enter");
        let Mode::Confirm(c) = &app.mode else {
            panic!("a dialog: {:?}", app.mode)
        };
        assert!(c.lines[0].contains("api.example.com"), "{:?}", c.lines);
        assert!(!app
            .take_requests()
            .iter()
            .any(|r| matches!(r, Request::AiAsk { .. })));
        press(&mut app, "Esc");
        assert!(!app
            .take_requests()
            .iter()
            .any(|r| matches!(r, Request::AiAsk { .. })));
    }

    /// `ai!` asks for one command in a shape the program can use and puts the answer on the
    /// command line, not run; `ai+` follows up the last answer, and with none says so; an
    /// answer for a commit opens the commit prompt with it.
    #[test]
    fn ai_marks_ask_for_a_command_a_follow_up_and_a_commit_message() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = editing_app(dir.path());
        app.cfg.ais = vec![fcmd_config::AiCfg {
            name: "local".into(),
            url: "http://127.0.0.1:11434/api/chat".into(),
            model: "m".into(),
            api: "ollama".into(),
            ..Default::default()
        }];
        app.take_requests();
        app.cmd.set("ai! list the ten largest files here");
        press(&mut app, "Enter");
        let query = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::AiAsk { query, .. } => Some(query),
                _ => None,
            })
            .expect("asked");
        assert_eq!(query.purpose, AiUse::Command);
        assert!(
            query.instruction.contains("one command line"),
            "{}",
            query.instruction
        );
        assert_eq!(query.question, "list the ten largest files here");

        // The answer goes on the line, fences and all taken off, and nothing is run.
        app.handle_event(Event::AiDone {
            result: Ok(AiAnswer {
                file: dir.path().join("a.md"),
                text: "```sh\nls -S | head -10\n```".into(),
                purpose: AiUse::Command,
                tokens: (Some(10), Some(5)),
                model: String::new(),
                redacted: 0,
            }),
        });
        assert_eq!(app.cmd.text, "ls -S | head -10");
        assert!(app.status.contains("10"), "{}", app.status);
        assert!(app
            .take_requests()
            .iter()
            .all(|r| !matches!(r, Request::Shell { .. })));

        // No answer yet in this session: a follow-up has nothing to follow.
        app.cmd.set("ai+ and the smallest?");
        press(&mut app, "Enter");
        assert!(app.status_error, "{}", app.status);
        // After one, it continues that one's thread.
        let answer = dir.path().join("1-why.md");
        std::fs::write(&answer, "# why?\n\n*local · m*\n\nbecause\n").unwrap();
        app.handle_event(Event::AiDone {
            result: Ok(AiAnswer {
                file: answer.clone(),
                text: "because".into(),
                purpose: AiUse::Answer,
                tokens: (None, None),
                model: String::new(),
                redacted: 0,
            }),
        });
        app.mode = Mode::Normal;
        app.cmd.set("ai+ and the smallest?");
        press(&mut app, "Enter");
        let query = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::AiAsk { query, .. } => Some(query),
                _ => None,
            })
            .expect("asked again");
        assert_eq!(query.thread, Some(answer));

        // A drafted commit message lands in the commit prompt, to be read and changed.
        app.handle_event(Event::AiDone {
            result: Ok(AiAnswer {
                file: dir.path().join("c.md"),
                text: "Add the git column".into(),
                purpose: AiUse::Commit {
                    root: dir.path().to_path_buf(),
                },
                tokens: (None, None),
                model: String::new(),
                redacted: 0,
            }),
        });
        let Mode::Prompt(p) = &app.mode else {
            panic!("the commit prompt: {:?}", app.mode)
        };
        assert_eq!(p.kind, PromptKind::GitCommit);
        assert_eq!(p.text, "Add the git column");
    }

    /// The git column costs a `git status` only when something on screen asks for it: a
    /// sort by it, or a column set that shows it — and its answer sorts the panel again.
    #[test]
    fn the_git_column_is_asked_for_only_when_shown_or_sorted_by() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), "a").unwrap();
        std::fs::write(dir.path().join("b.txt"), "b").unwrap();
        let mut app = editing_app(dir.path());
        app.take_requests();
        app.ask_for_git_column(0);
        assert!(app
            .take_requests()
            .iter()
            .all(|r| !matches!(r, Request::GitColumn { .. })));
        app.run(Command::PanelSortBy(SortKey::Git));
        let asked = app
            .take_requests()
            .into_iter()
            .any(|r| matches!(r, Request::GitColumn { panel: 0, .. }));
        assert!(asked);
        // `b.txt` is changed, so it comes before the clean `a.txt`.
        let generation = app.panels[0].generation;
        app.handle_event(Event::GitColumn {
            panel: 0,
            generation,
            status: [("b.txt".to_string(), " M".to_string())]
                .into_iter()
                .collect(),
        });
        let names: Vec<String> = (0..app.panels[0].listing.len())
            .filter_map(|r| app.panels[0].listing.row(r))
            .filter(|e| e.kind != fcmd_core::EntryKind::Parent)
            .map(|e| e.name_str().into_owned())
            .collect();
        assert_eq!(
            names.first().map(String::as_str),
            Some("b.txt"),
            "{names:?}"
        );
    }

    /// What the tests of a plugin's column stand on: a `lines` column over `*.txt`, a
    /// column set on `Ctrl+3` that draws it, and the panel in that view.
    fn app_with_a_plugin_column(dir: &std::path::Path, program: PathBuf, batch: bool) -> App {
        let mut app = editing_app(dir);
        app.plugin_columns = vec![crate::plugcol::PluginColumn {
            plugin: "counts".into(),
            id: "lines".into(),
            title: "Lines".into(),
            width: Some(6),
            right: true,
            program,
            masks: Some("*.txt".into()),
            timeout: Some(10),
            batch,
            folders: false,
        }];
        app.plugin_titles = vec!["Lines".into()];
        let (cfg, _) = Config::parse(
            "test.toml",
            r#"
            [[column_set]]
            id = 3
            columns = [{ type = "name" }, { type = "plugin:counts.lines" }]
            "#,
        )
        .expect("it parses");
        let mut warnings = Vec::new();
        app.column_sets = crate::colset::sets(&cfg, &app.plugin_columns, &mut warnings);
        assert!(warnings.is_empty(), "{warnings:?}");
        app.take_requests();
        app.run(Command::PanelViewSet(ViewMode::Full));
        app
    }

    /// The one request a plugin column made, if it made one.
    fn plugin_job(app: &mut App) -> Option<(u64, crate::plugcol::Job)> {
        app.take_requests().into_iter().find_map(|r| match r {
            Request::PluginColumn {
                panel: 0,
                generation,
                column: 0,
                job,
            } => Some((generation, job)),
            _ => None,
        })
    }

    /// The left panel, as text.
    fn left_panel(app: &mut App) -> String {
        let mut buf = fcmd_ui::Buffer::new(100, 14);
        crate::render::draw(app, &mut buf);
        buf.to_text()
            .lines()
            .map(|line| line.chars().take(50).collect::<String>())
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// A plugin's column asks about the files its masks name and no others, draws a
    /// placeholder until the program has answered, and never asks twice about a file that
    /// has not changed.
    #[test]
    fn a_plugin_column_asks_once_per_file_and_waits_with_a_placeholder() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("two.txt"), "a\nb\n").unwrap();
        std::fs::write(dir.path().join("five.txt"), "1\n2\n3\n4\n5\n").unwrap();
        std::fs::write(dir.path().join("picture.png"), "x").unwrap();
        std::fs::create_dir(dir.path().join("folder.txt")).unwrap();
        let mut app = app_with_a_plugin_column(dir.path(), PathBuf::from("lines"), false);

        let (generation, job) = plugin_job(&mut app).expect("the view asks");
        let mut asked: Vec<&str> = job.files.iter().map(|f| f.name.as_str()).collect();
        asked.sort_unstable();
        // Not the picture, which the masks leave out, and not the folder, whatever it is
        // called: a program that counts lines has nothing to say about one.
        assert_eq!(asked, ["five.txt", "two.txt"]);
        assert_eq!(job.dir, dir.path());
        let text = left_panel(&mut app);
        assert!(text.contains("Lines"), "the plugin's own heading:\n{text}");
        let row = |text: &str, name: &str| {
            text.lines()
                .find(|l| l.contains(name))
                .unwrap_or_else(|| panic!("no {name} in\n{text}"))
                .to_string()
        };
        assert!(row(&text, "two").contains(fcmd_ui::widgets::PLUGIN_PENDING));
        assert!(!row(&text, "picture").contains(fcmd_ui::widgets::PLUGIN_PENDING));

        // The answer for one file lands; the other is still waiting.
        let cell = |name: &str, value: &str| {
            let file = job.files.iter().find(|f| f.name == name).unwrap().clone();
            (file, value.to_string())
        };
        app.handle_event(Event::PluginColumn {
            panel: 0,
            generation,
            column: 0,
            dir: job.dir.clone(),
            answer: crate::plugcol::Answer {
                cells: vec![cell("two.txt", "2")],
                ..Default::default()
            },
        });
        let text = left_panel(&mut app);
        assert!(row(&text, "two").contains(" 2"), "{text}");
        assert!(row(&text, "five").contains(fcmd_ui::widgets::PLUGIN_PENDING));
        app.handle_event(Event::PluginColumn {
            panel: 0,
            generation,
            column: 0,
            dir: job.dir.clone(),
            answer: crate::plugcol::Answer {
                cells: vec![cell("five.txt", "5")],
                ..Default::default()
            },
        });

        // Read again, nothing changed: both come out of the memory, and nobody is asked.
        app.take_requests();
        let reread = |app: &mut App| {
            let generation = app.panels[0].generation + 1;
            app.panels[0].generation = generation;
            let entries = fcmd_vfs::local::list_blocking(&app.panels[0].cwd, &CancelToken::new())
                .expect("it lists");
            app.handle_event(Event::Listed {
                panel: 0,
                generation,
                result: Ok(entries),
            });
        };
        reread(&mut app);
        assert!(plugin_job(&mut app).is_none(), "nothing changed");
        let text = left_panel(&mut app);
        assert!(row(&text, "five").contains(" 5"), "{text}");

        // One of them is written to: that one is asked about again, and only that one.
        std::fs::write(dir.path().join("two.txt"), "a\nb\nc\n").unwrap();
        reread(&mut app);
        let (_, job) = plugin_job(&mut app).expect("the changed file");
        assert_eq!(
            job.files
                .iter()
                .map(|f| f.name.as_str())
                .collect::<Vec<_>>(),
            ["two.txt"]
        );
        let text = left_panel(&mut app);
        assert!(row(&text, "two").contains(fcmd_ui::widgets::PLUGIN_PENDING));
        assert!(row(&text, "five").contains(" 5"), "{text}");
    }

    /// An answer that arrives after the panel has gone elsewhere draws nothing there, is
    /// kept all the same, and a column that gave up says so and leaves its cells empty.
    #[test]
    fn a_late_plugin_answer_is_kept_and_a_column_that_gave_up_says_so() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), "a\n").unwrap();
        std::fs::write(dir.path().join("b.txt"), "b\n").unwrap();
        let mut app = app_with_a_plugin_column(dir.path(), PathBuf::from("lines"), true);
        let (generation, job) = plugin_job(&mut app).expect("the view asks");
        assert!(job.batch);
        // The listing the job was for is cancelled by the next one.
        let old = app.panels[0].plugin_cancel.clone();
        app.panels[0].forget_plugin_cells();
        assert!(old.load(std::sync::atomic::Ordering::Relaxed));
        assert!(!app.panels[0]
            .plugin_cancel
            .load(std::sync::atomic::Ordering::Relaxed));

        let a = job
            .files
            .iter()
            .find(|f| f.name == "a.txt")
            .unwrap()
            .clone();
        app.handle_event(Event::PluginColumn {
            panel: 0,
            generation: generation + 7,
            column: 0,
            dir: job.dir.clone(),
            answer: crate::plugcol::Answer {
                cells: vec![(a, "1".into())],
                ..Default::default()
            },
        });
        assert!(app.panels[0].plugin_cells.is_empty(), "not this listing's");
        app.ask_for_plugin_columns(0);
        let (_, job) = plugin_job(&mut app).expect("b is still unknown");
        assert_eq!(job.files.len(), 1);
        assert_eq!(job.files[0].name, "b.txt");
        assert_eq!(
            app.panels[0].plugin_cells.get(&(0, "a.txt".to_string())),
            Some(&Some("1".to_string()))
        );

        app.handle_event(Event::PluginColumn {
            panel: 0,
            generation,
            column: 0,
            dir: job.dir.clone(),
            answer: crate::plugcol::Answer {
                blank: vec!["b.txt".into()],
                error: Some("lines did not finish within 10 seconds".into()),
                ..Default::default()
            },
        });
        let said = app.status.clone();
        assert!(said.contains("plugin:counts.lines"), "{said}");
        assert!(said.contains("did not finish"), "{said}");
        assert_eq!(
            app.panels[0].plugin_cells.get(&(0, "b.txt".to_string())),
            Some(&Some(String::new()))
        );
    }

    /// The whole of it through a real script: the request the panel makes, run by the
    /// worker, fills the column. Skipped where there is no shell to run a script with.
    #[test]
    #[cfg(unix)]
    fn a_script_plugin_fills_its_column() {
        use std::os::unix::fs::PermissionsExt;
        if !std::path::Path::new("/bin/sh").exists() {
            return;
        }
        let plugin = tempfile::tempdir().unwrap();
        let program = plugin.path().join("lines.sh");
        std::fs::write(&program, "#!/bin/sh\nwc -l < \"$1\" | tr -d ' '\n").unwrap();
        std::fs::set_permissions(&program, std::fs::Permissions::from_mode(0o755)).unwrap();
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("three.txt"), "a\nb\nc\n").unwrap();
        std::fs::write(dir.path().join("none.txt"), "").unwrap();
        let mut app = app_with_a_plugin_column(dir.path(), program, false);
        let (generation, job) = plugin_job(&mut app).expect("the view asks");
        let mut answers = Vec::new();
        crate::plugcol::run(&job, &mut |a| answers.push(a));
        for answer in answers {
            app.handle_event(Event::PluginColumn {
                panel: 0,
                generation,
                column: 0,
                dir: job.dir.clone(),
                answer,
            });
        }
        let cells = &app.panels[0].plugin_cells;
        assert_eq!(
            cells.get(&(0, "three.txt".to_string())),
            Some(&Some("3".to_string()))
        );
        assert_eq!(
            cells.get(&(0, "none.txt".to_string())),
            Some(&Some("0".to_string()))
        );
    }

    /// `Ctrl+Alt+X` in the viewer sends nothing until a dialog has said what goes and where;
    /// `Shift+F7` in a panel does the same for the staged diff.
    #[test]
    fn explaining_and_drafting_a_commit_ask_before_anything_goes() {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("notes.txt");
        std::fs::write(&file, "fn main() {}\n").unwrap();
        let mut app = editing_app(dir.path());
        app.cfg.ais = vec![fcmd_config::AiCfg {
            name: "local".into(),
            url: "http://127.0.0.1:11434/api/chat".into(),
            model: "m".into(),
            api: "ollama".into(),
            ..Default::default()
        }];
        app.view_path(&file.display().to_string());
        app.take_requests();
        press(&mut app, "Ctrl+Alt+X");
        let Mode::Confirm(c) = &app.mode else {
            panic!("a dialog first: {:?}", app.mode)
        };
        assert!(
            c.lines.iter().any(|l| l.contains("notes.txt")),
            "{:?}",
            c.lines
        );
        assert!(c.lines[0].contains("127.0.0.1"), "{:?}", c.lines);
        assert!(app
            .take_requests()
            .iter()
            .all(|r| !matches!(r, Request::AiAsk { .. })));
        // *Cancel* is the button lit; the user moves to *Send*.
        if let Mode::Confirm(c) = &mut app.mode {
            c.button = 0;
        }
        press(&mut app, "Enter");
        let query = app
            .take_requests()
            .into_iter()
            .find_map(|r| match r {
                Request::AiAsk { query, .. } => Some(query),
                _ => None,
            })
            .expect("sent on yes");
        assert_eq!(query.inline[0].0, "notes.txt");
        assert!(query.inline[0].1.contains("fn main"));
    }

