    /// `sql:` on the command line asks the worker to query the database under the cursor;
    /// with no database anywhere near, it says so instead of asking.
    #[test]
    fn a_sql_line_queries_the_database_under_the_cursor() {
        let dir = tempfile::tempdir().unwrap();
        let db = dir.path().join("t.db");
        std::fs::write(&db, b"SQLite format 3\0 and the rest of a page").unwrap();
        std::fs::write(dir.path().join("notes.txt"), "x").unwrap();
        let mut app = editing_app(dir.path());
        let at = app.panels[0].listing.row_of_name("notes.txt").unwrap();
        app.panels[0].cursor = at;
        app.cmd.set("sql: SELECT 1");
        press(&mut app, "Enter");
        assert!(app.status_error, "no database here: {}", app.status);
        let at = app.panels[0].listing.row_of_name("t.db").unwrap();
        app.panels[0].cursor = at;
        app.take_requests();
        app.cmd.set("sql: SELECT 1");
        press(&mut app, "Enter");
        let asked = app.take_requests().into_iter().find_map(|r| match r {
            Request::SqlQuery { db, sql } => Some((db, sql)),
            _ => None,
        });
        assert_eq!(asked, Some((db, "SELECT 1".to_string())));
    }

    /// `Commands → Find duplicate files` on a folder: the dialog, the search in the worker,
    /// and the panel of groups with every copy but the oldest selected for `F8`.
    #[test]
    fn duplicates_come_back_as_a_panel_with_the_copies_selected() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("a.txt"), "same bytes").unwrap();
        std::fs::write(dir.path().join("b.txt"), "same bytes").unwrap();
        std::fs::write(dir.path().join("c.txt"), "different").unwrap();
        let old = std::time::SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(1_000_000);
        let f = std::fs::File::options()
            .write(true)
            .open(dir.path().join("b.txt"))
            .unwrap();
        f.set_modified(old).unwrap();
        drop(f);
        let mut app = editing_app(dir.path());
        app.run(Command::FileDupes);
        assert!(matches!(&app.mode, Mode::Form(f) if f.kind == FormKind::Dupes));
        press(&mut app, "Enter");
        let Some(Request::Dupes {
            panel,
            roots,
            opts,
            cancel,
        }) = app
            .take_requests()
            .into_iter()
            .find(|r| matches!(r, Request::Dupes { .. }))
        else {
            panic!("no search was asked for")
        };
        assert_eq!(roots, [VPath::local(dir.path())]);
        assert!(opts.recursive);
        let found = fcmd_jobs::dupes::find(
            &fcmd_jobs::LocalFs,
            &roots,
            &opts,
            &cancel,
            &mut |_, _, _| {},
        );
        app.handle_event(Event::DupesFound { panel, found });
        let p = &app.panels[0];
        assert_eq!(p.temp_origin(), Some(":dupes"));
        assert_eq!(p.listing.len(), 2, "c.txt has no twin");
        assert_eq!(p.selection.len(), 1, "every copy but the oldest");
        let sources = app.job_sources();
        assert_eq!(
            sources,
            [VPath::local(dir.path().join("a.txt"))],
            "b.txt is older"
        );
    }

    /// `Files → Split file` asks where and how big, then hands the file to the worker; the
    /// pieces it leaves are joined by `Files → Combine files` from any of them.
    #[test]
    fn a_file_is_split_from_the_menu_and_joined_from_a_piece() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("big.bin"), vec![5u8; 30_000]).unwrap();
        let mut app = editing_app(dir.path());
        press(&mut app, "Down"); // big.bin
        app.run(Command::FileSplit);
        {
            let Mode::Form(form) = &mut app.mode else {
                panic!("{:?}", app.mode)
            };
            assert_eq!(form.kind, FormKind::Split);
            form.cursor = form
                .fields
                .iter()
                .position(
                    |f| matches!(f, crate::form::Field::Text { key, .. } if *key == "split.size"),
                )
                .unwrap();
        }
        clear_prompt(&mut app);
        // In bytes: the test's typing helper sends letters lower case, and `10k` is decimal.
        type_text(&mut app, "10240");
        app.requests.clear();
        app.apply_form();
        let request = app
            .take_requests()
            .into_iter()
            .find(|r| matches!(r, Request::Split { .. }))
            .expect("the split was asked for");
        let Request::Split {
            id,
            src,
            out_dir,
            size,
            count,
            cancel,
        } = request
        else {
            unreachable!()
        };
        assert_eq!(size, 10 * 1024);
        assert_eq!(count, None, "by size: the pieces row was left empty");
        assert_eq!(src, dir.path().join("big.bin"));
        // The worker, run here, and what it says.
        let pieces = fcmd_jobs::split::split(&src, &out_dir, size, &cancel, &mut |_| {}).unwrap();
        app.handle_event(Event::PiecesDone {
            id,
            result: Ok(PiecesMade::Split {
                parts: pieces.parts.len(),
                list: "big.bin.crc".into(),
            }),
            cancelled: false,
        });
        assert!(app.status.contains('3'), "{}", app.status);
        assert!(app.status.contains("big.bin.crc"), "{}", app.status);

        // Combining from a piece asks for it; from a file that is not one it says so.
        // A fresh look at the folder, with the pieces in it.
        let mut app = editing_app(dir.path());
        let at = app.panels[0].listing.row_of_name("big.bin.002").unwrap();
        app.panels[0].cursor = at;
        app.run(Command::FileCombine);
        assert!(app
            .take_requests()
            .iter()
            .any(|r| matches!(r, Request::Combine { .. })));
        app.sum = None;
        let at = app.panels[0].listing.row_of_name("big.bin").unwrap();
        app.panels[0].cursor = at;
        app.run(Command::FileCombine);
        assert!(app.status_error, "{}", app.status);
    }

    /// The *pieces* row of the split dialog, filled in, decides: the request carries the
    /// count for the worker to turn into a size, and a size row that says nonsense is not read.
    /// A count that is not two or more is refused before anything is asked for.
    #[test]
    fn a_split_into_a_number_of_pieces_carries_the_count() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("big.bin"), vec![5u8; 30_000]).unwrap();
        let ask = |count: &str| -> (App, Option<Request>) {
            let mut app = editing_app(dir.path());
            press(&mut app, "Down");
            app.run(Command::FileSplit);
            for (key, value) in [("split.size", "nonsense"), ("split.count", count)] {
                let Mode::Form(form) = &mut app.mode else {
                    panic!("{:?}", app.mode)
                };
                form.cursor = form
                    .fields
                    .iter()
                    .position(|f| matches!(f, crate::form::Field::Text { key: k, .. } if *k == key))
                    .unwrap();
                clear_prompt(&mut app);
                type_text(&mut app, value);
            }
            app.requests.clear();
            app.apply_form();
            let split = app
                .take_requests()
                .into_iter()
                .find(|r| matches!(r, Request::Split { .. }));
            (app, split)
        };
        let (_, split) = ask("4");
        let Some(Request::Split {
            count,
            src,
            out_dir,
            cancel,
            ..
        }) = split
        else {
            panic!("no split was asked for")
        };
        assert_eq!(count, Some(4));
        // What the worker makes of it: four pieces of the same size, the last one shorter.
        let size = fcmd_jobs::split::size_for_count(30_000, 4).unwrap();
        let pieces = fcmd_jobs::split::split(&src, &out_dir, size, &cancel, &mut |_| {}).unwrap();
        assert_eq!(pieces.parts.len(), 4);

        let (app, split) = ask("1");
        assert!(split.is_none(), "one piece is not a split");
        assert!(app.status_error, "{}", app.status);
    }

    /// `Ctrl+Alt+B` lists every file under the folder by its path from there, the rows stand
    /// for the real files, and the same key goes back to the folder.
    #[test]
    fn the_branch_view_flattens_the_tree_and_goes_back() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join("src/deep")).unwrap();
        std::fs::write(dir.path().join("README"), "r").unwrap();
        std::fs::write(dir.path().join("src/deep/x.rs"), "xx").unwrap();
        let mut app = editing_app(dir.path());
        app.requests.clear();
        press(&mut app, "Ctrl+Alt+B");
        let Some(Request::Branch {
            panel,
            root,
            cancel,
        }) = app
            .take_requests()
            .into_iter()
            .find(|r| matches!(r, Request::Branch { .. }))
        else {
            panic!("the walk was asked for")
        };
        let branch = fcmd_jobs::branch::walk(&fcmd_jobs::LocalFs, &root, 100, &cancel);
        app.handle_event(Event::Branched {
            panel,
            root: root.clone(),
            branch,
        });
        let p = &app.panels[0];
        assert_eq!(p.temp_origin(), Some(":branch"));
        let names: Vec<String> = (0..p.listing.len())
            .filter_map(|r| p.listing.row(r))
            .map(|e| e.name_str().into_owned())
            .collect();
        assert!(names.contains(&"src/deep/x.rs".to_string()), "{names:?}");
        let at = p.listing.row_of_name("src/deep/x.rs").unwrap();
        app.panels[0].cursor = at;
        assert_eq!(
            app.panels[0].current_path(),
            Some(VPath::local(dir.path().join("src/deep/x.rs"))),
            "a row is the real file"
        );
        press(&mut app, "Ctrl+Alt+B");
        assert!(app.panels[0].temp.is_none(), "back to the folder");
        assert_eq!(app.panels[0].cwd, root);

        // An answer for a folder the panel has left is not shown.
        app.panels[0].go(VPath::local(dir.path().join("src")), true);
        app.handle_event(Event::Branched {
            panel: 0,
            root,
            branch: Default::default(),
        });
        assert!(app.panels[0].temp.is_none());
    }

    #[test]
    fn f4_opens_the_editor_on_a_real_file() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("notes.txt"), b"alpha\nbeta\n").unwrap();
        let mut app = editing_app(dir.path());

        press(&mut app, "Down"); // notes.txt
        press(&mut app, "F4");
        let editor = app.mode.editor().expect("the editor should be open");
        assert_eq!(editor.name(), "notes.txt");
        assert_eq!(editor.buffer.lines(), ["alpha", "beta"]);

        // Typing goes to the editor, not to the panel.
        let cursor_before = app.panel().cursor;
        press(&mut app, "End");
        for c in ["!", "!"] {
            press(&mut app, c);
        }
        assert_eq!(app.panel().cursor, cursor_before, "the panel moved instead");
        assert_eq!(app.mode.editor().unwrap().buffer.line(0), "alpha!!");
        assert!(app.mode.editor().unwrap().buffer.modified());
    }

    // ── the colour groups dialog (SPEC 10 §3.11) ───────────────────────────────────────────

    #[test]
    fn the_colour_groups_are_listed_edited_reordered_and_removed_from_the_list() {
        let mut app = app();
        app.cfg.highlight = vec![
            fcmd_config::HighlightCfg {
                name: "logs".into(),
                mask: "*.log".into(),
                fg: "#d7875f".into(),
                ..Default::default()
            },
            fcmd_config::HighlightCfg {
                name: "big".into(),
                size: "1G-".into(),
                fg: "red".into(),
                ..Default::default()
            },
        ];
        app.run(Command::OptHighlight);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.kind, crate::menu::PickKind::Highlight);
        assert_eq!(pick.rows.len(), 2);
        // The row says what the group is called and what it matches, in the file's own words.
        assert!(
            pick.rows[0].label.contains("logs"),
            "{:?}",
            pick.rows[0].label
        );
        assert!(
            pick.rows[0].label.contains("*.log"),
            "{:?}",
            pick.rows[0].label
        );
        // And it is drawn in the group's own colours.
        assert!(app.highlight_ink(0).is_some());
        assert!(app.highlight_ink(9).is_none(), "a row that is not there");

        // `Ctrl+Down` moves a group past the next one: the order is what decides which group
        // paints a row that both of them match.
        press(&mut app, "Ctrl+Down");
        assert_eq!(app.cfg.highlight[0].name, "big");
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.cursor, 1, "the cursor follows the row it moved");

        // `F4` opens the group under the cursor, filled in.
        press(&mut app, "F4");
        let Mode::Form(form) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(form.kind, crate::menu::FormKind::Highlight);
        assert_eq!(form.text_value("hl.mask"), "*.log");

        // A condition that does not parse comes back on the dialog, with the fields kept.
        set_text(&mut app, "hl.size", "not a size");
        press(&mut app, "F10");
        assert!(app.status_error, "{}", app.status);
        let Mode::Form(form) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(form.text_value("hl.size"), "not a size");

        // A sound change is in force at once, and the list comes back.
        set_text(&mut app, "hl.size", "1M-");
        press(&mut app, "F10");
        assert!(!app.status_error, "{}", app.status);
        assert_eq!(app.cfg.highlight[1].size, "1M-");
        assert!(matches!(app.mode, Mode::Pick(_)), "{:?}", app.mode);

        // A group with no condition at all would paint every row, so it is refused.
        press(&mut app, "Ins");
        set_text(&mut app, "hl.name", "nothing");
        press(&mut app, "F10");
        assert!(app.status_error, "{}", app.status);
        press(&mut app, "Esc");

        // `Del` takes one away.
        app.run(Command::OptHighlight);
        press(&mut app, "Del");
        assert_eq!(app.cfg.highlight.len(), 1);
        assert_eq!(app.cfg.highlight[0].name, "logs");
    }

    /// A history is long, so it is a list one types into — and one clears from inside it,
    /// on FAR's own three keys.
    #[test]
    fn a_history_is_narrowed_by_typing_and_cleared_with_del() {
        let mut app = app();
        app.cmd
            .load_history(vec!["make".into(), "cargo test".into(), "cargo fmt".into()]);
        app.run(Command::CmdHistory);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.kind, crate::menu::PickKind::CommandHistory);
        assert_eq!(pick.rows.len(), 3);

        // Typing narrows it; the frame says what was typed.
        for c in ["c", "a", "r"] {
            press(&mut app, c);
        }
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.rows.len(), 2, "{:?}", pick.rows);
        assert!(pick.heading().contains("car"), "{}", pick.heading());

        // `Shift+Del` takes the line under the cursor out of the history and leaves the list
        // — and the filter — where they were.
        let gone = pick.chosen().map(|r| r.value.clone()).unwrap();
        press(&mut app, "Shift+Del");
        assert!(
            !app.cmd.history().contains(&gone),
            "{:?}",
            app.cmd.history()
        );
        let Mode::Pick(pick) = &app.mode else {
            panic!("the list stays open: {:?}", app.mode)
        };
        assert_eq!(pick.filter, "car");
        assert_eq!(pick.rows.len(), 1, "{:?}", pick.rows);
    }

    /// `Ins` pins a line, `Shift+Del` refuses to take a pinned one away, and `Del` empties
    /// the history of everything that is not pinned — FAR's three keys, after FAR's question.
    #[test]
    fn a_pinned_history_line_outlives_del_and_the_size_limit() {
        let mut app = app();
        app.cmd
            .load_history(vec!["make".into(), "cargo test".into(), "cargo fmt".into()]);
        app.run(Command::CmdHistory);

        // Newest first, so the cursor is on `cargo fmt`. `Ins` pins it, and the list says so.
        press(&mut app, "Ins");
        assert!(
            app.marks.is_locked(crate::history::COMMANDS, "cargo fmt"),
            "the line under the cursor is pinned"
        );
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert!(
            pick.lines().iter().any(|line| line.contains("* cargo fmt")),
            "the pinned row is marked: {:?}",
            pick.lines()
        );

        // `Shift+Del` will not take a pinned line away.
        press(&mut app, "Shift+Del");
        assert!(
            app.cmd.history().contains(&"cargo fmt".to_string()),
            "{:?}",
            app.cmd.history()
        );

        // `Del` asks, and then empties the history of everything else.
        press(&mut app, "Del");
        assert!(matches!(app.mode, Mode::Confirm(_)), "{:?}", app.mode);
        press(&mut app, "Enter");
        assert_eq!(app.cmd.history(), ["cargo fmt"]);
        assert!(matches!(app.mode, Mode::Pick(_)), "the list stays open");

        // And the size limit passes over it as well: one line kept, and the pinned one is it.
        app.cfg.ui.command_history = 1;
        app.cmd
            .load_history(vec!["cargo fmt".into(), "make".into()]);
        let locked = app.marks.locked_lines(crate::history::COMMANDS);
        app.cmd.trim_history(1, &locked);
        assert_eq!(app.cmd.history(), ["cargo fmt"]);
    }

    /// `Alt+F10` is the folders the tree knows, as a list one types into: what was typed
    /// narrows it, `Enter` goes there (SPEC 02 §7).
    #[test]
    fn alt_f10_finds_a_folder_by_name() {
        let mut app = app();
        let root = app.panels[0].cwd.root();
        // What a walk would have left behind, and what the last session would have written.
        app.tree_cache.insert(
            root.clone(),
            vec![root.join("usr"), root.join("home"), root.join("srv")],
        );
        app.tree_cache
            .insert(root.join("usr"), vec![root.join("usr").join("share")]);

        app.run(Command::ToolFindFolder);
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert_eq!(pick.kind, crate::menu::PickKind::Folders);
        assert!(pick.rows.len() >= 4, "{:?}", pick.rows);
        // The walk is asked for once, and only once while it runs.
        assert!(app
            .take_requests()
            .iter()
            .any(|r| matches!(r, Request::TreeScan { .. })));

        // Typing narrows the list rather than jumping about in it.
        press(&mut app, "s");
        press(&mut app, "h");
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert!(
            pick.rows.iter().all(|r| r.label.contains("sh")),
            "{:?}",
            pick.rows.iter().map(|r| &r.label).collect::<Vec<_>>()
        );
        assert!(pick.heading().contains("sh"), "{}", pick.heading());
        // And `Backspace` gives the rows back.
        press(&mut app, "Backspace");
        press(&mut app, "Backspace");
        let Mode::Pick(pick) = &app.mode else {
            panic!("{:?}", app.mode)
        };
        assert!(pick.rows.len() >= 4);

        // `Enter` on a row takes the panel there.
        let wanted = root.join("home");
        let at = pick
            .rows
            .iter()
            .position(|r| r.value == wanted.to_string())
            .expect("the row is in the list");
        let Mode::Pick(pick) = &mut app.mode else {
            panic!()
        };
        pick.cursor = at;
        press(&mut app, "Enter");
        assert_eq!(app.panels[0].cwd, wanted);
    }

