    /// The four times FAR's own dialog shows, the three buttons that fill them in, and the
    /// box that says which clock they are in.
    #[test]
    fn the_attributes_dialog_has_the_four_times_and_the_buttons_that_fill_them() {
        let dir = tempfile::tempdir().expect("a directory");
        let file = dir.path().join("a.txt");
        std::fs::write(&file, b"hello").expect("written");
        let mut app = app();
        app.panels[0].cwd = VPath::local(dir.path());
        app.handle_event(Event::Listed {
            panel: 0,
            generation: app.panels[0].generation,
            result: Ok(vec![
                Entry::parent_entry(),
                entry("a.txt", EntryKind::File, 5),
            ]),
        });
        app.panel_mut().cursor_to(1);
        app.run(Command::FileAttributes);
        let Mode::Form(form) = &app.mode else {
            panic!("the attributes dialog did not open: {:?}", app.mode)
        };
        // The write time is seeded from the file itself; the record's own time is shown and
        // never offered, so it is not a row anything can write.
        assert!(!form.text_value("attr.mtime").is_empty());
        assert!(!form.text_value("attr.atime").is_empty());
        assert_eq!(form.text_value("attr.utc"), "false");

        // `Blank` empties them, which is how a row says "leave this one alone".
        app.form_mut_button(2);
        press(&mut app, "Enter");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed: {:?}", app.mode)
        };
        assert!(
            form.text_value("attr.mtime").is_empty(),
            "Blank did nothing"
        );

        // `Current` fills them with this moment, and the dialog is still open.
        app.form_mut_button(1);
        press(&mut app, "Enter");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed: {:?}", app.mode)
        };
        let now = form.text_value("attr.mtime");
        assert!(!now.is_empty(), "Current did nothing");

        // `Original` puts the file's own times back.
        app.form_mut_button(0);
        press(&mut app, "Enter");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed: {:?}", app.mode)
        };
        let original = form.text_value("attr.mtime");
        assert!(!original.is_empty(), "Original did nothing");
        assert_eq!(
            original,
            fcmd_ui::format_stamp(std::fs::metadata(&file).unwrap().modified().unwrap())
        );

        // And the `UTC` box re-reads them in that clock: the same instant, written the way
        // the file keeps it.
        let utc_row = form
            .fields
            .iter()
            .position(|f| matches!(f, crate::form::Field::Toggle { key, .. } if *key == "attr.utc"))
            .expect("the UTC box");
        let Mode::Form(form) = &mut app.mode else {
            unreachable!()
        };
        form.button = None;
        form.cursor = utc_row;
        press(&mut app, "Space");
        let Mode::Form(form) = &app.mode else {
            panic!("the dialog closed: {:?}", app.mode)
        };
        assert_eq!(form.text_value("attr.utc"), "true");
        assert_eq!(
            form.text_value("attr.mtime"),
            fcmd_ui::format_stamp_utc(std::fs::metadata(&file).unwrap().modified().unwrap())
        );
    }

    #[test]
    fn a_marked_letter_takes_its_menu_row_and_the_marker_is_never_drawn() {
        let mut app = app();
        // The Left menu's `&Medium` row: `m` takes it, and the view changes.
        open(&mut app, 0, "menu-medium");
        assert_eq!(app.panels[0].view, ViewMode::Medium);

        // And by the keys a user presses: `F9` lights the bar, `L` pulls the left menu down
        // — the letter the title wears — and `m` takes the row.
        let mut by_key = super::tests::app();
        by_key.run(Command::AppMenu);
        assert!(
            matches!(by_key.mode, Mode::Menu { open: false, .. }),
            "the bar pulled a menu down by itself: {:?}",
            by_key.mode
        );
        press(&mut by_key, "l");
        assert!(
            matches!(
                by_key.mode,
                Mode::Menu {
                    menu: 0,
                    open: true,
                    ..
                }
            ),
            "{:?}",
            by_key.mode
        );
        press(&mut by_key, "m");
        assert_eq!(by_key.panels[0].view, ViewMode::Medium);
        assert!(by_key.mode.is_normal(), "the menu stayed open");

        // `Esc` rolls the menu back up and leaves the bar lit; a second one gives the panels
        // back, which is the way out FAR has.
        let mut back = super::tests::app();
        back.run(Command::AppMenu);
        press(&mut back, "Enter");
        assert!(matches!(back.mode, Mode::Menu { open: true, .. }));
        press(&mut back, "Esc");
        assert!(
            matches!(back.mode, Mode::Menu { open: false, .. }),
            "{:?}",
            back.mode
        );
        press(&mut back, "Esc");
        assert!(back.mode.is_normal(), "{:?}", back.mode);
    }

    #[test]
    fn deleting_one_file_asks_about_that_file_and_not_about_one_items() {
        let mut app = app();
        app.panel_mut().cursor_to(2); // a.txt
        app.run(Command::FileDelete);
        let Mode::Confirm(confirm) = &app.mode else {
            panic!("the delete confirmation did not open: {:?}", app.mode)
        };
        let first = &confirm.lines[0];
        assert!(first.contains("a.txt"), "{first}");
        assert!(
            !first.contains("1 item"),
            "one file is a name, not a count: {first}"
        );
        // And the name is not then repeated underneath, which it was when the question
        // counted instead of naming.
        assert_eq!(
            confirm.lines.iter().filter(|l| l.contains("a.txt")).count(),
            1,
            "{:?}",
            confirm.lines
        );

        // Several are a count, with the names under it.
        let mut many = super::tests::app();
        many.panel_mut().cursor_to(2);
        many.run(Command::SelToggle);
        many.run(Command::SelToggle);
        many.run(Command::FileDelete);
        let Mode::Confirm(confirm) = &many.mode else {
            panic!("no confirmation for the selection")
        };
        assert!(confirm.lines[0].contains('2'), "{:?}", confirm.lines);
    }

